#[derive(Clone, Debug, PartialEq)]
struct RuntimeMediaPipelineAsset {
    registration: RuntimeMediaAssetRegistration,
    state: RuntimeMediaAssetState,
    cache_path: Option<String>,
    cache_byte_size: Option<u64>,
    rebuild_count: u32,
    last_error: Option<String>,
    analysis: RuntimeMediaAnalysisStateModel,
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeMediaPipelineStateModel {
    policy: RuntimeMediaPipelinePolicy,
    assets: BTreeMap<String, RuntimeMediaPipelineAsset>,
    previewing_asset_id: Option<String>,
    last_preview_error: Option<String>,
}

impl RuntimeMediaPipelineStateModel {
    fn snapshot(&self) -> RuntimeMediaPipelineSnapshot {
        let assets = self
            .assets
            .values()
            .map(|asset| RuntimeMediaAssetSnapshot {
                asset_id: asset.registration.asset_id.clone(),
                content_hash: asset.registration.content_hash.clone(),
                source_path: asset.registration.source_path.clone(),
                file_name: asset.registration.file_name.clone(),
                byte_size: asset.registration.byte_size,
                sample_rate_hz: asset.registration.sample_rate_hz,
                channel_count: asset.registration.channel_count,
                duration_samples: asset.registration.duration_samples,
                waveform_bin_count: asset.registration.waveform_bin_count,
                state: Some(asset.state),
                cache_path: asset.cache_path.clone(),
                cache_byte_size: asset.cache_byte_size,
                rebuild_count: asset.rebuild_count,
                last_error: asset.last_error.clone(),
                summary: format!(
                    "state={:?} cache={} rebuilds={} error={}",
                    asset.state,
                    asset.cache_path.as_deref().unwrap_or("none"),
                    asset.rebuild_count,
                    asset.last_error.as_deref().unwrap_or("none"),
                ),
            })
            .collect::<Vec<_>>();
        let ready_asset_count = assets
            .iter()
            .filter(|asset| asset.state == Some(RuntimeMediaAssetState::Ready))
            .count();
        let invalid_asset_count = assets
            .iter()
            .filter(|asset| asset.state == Some(RuntimeMediaAssetState::Invalid))
            .count();
        let ingesting_asset_count = assets
            .iter()
            .filter(|asset| asset.state == Some(RuntimeMediaAssetState::Ingesting))
            .count();
        let conforming_asset_count = assets
            .iter()
            .filter(|asset| asset.state == Some(RuntimeMediaAssetState::Conforming))
            .count();
        let rebuilding_asset_count = assets
            .iter()
            .filter(|asset| asset.state == Some(RuntimeMediaAssetState::Rebuilding))
            .count();

        RuntimeMediaPipelineSnapshot {
            cache_root_path: self.policy.cache_root.display().to_string(),
            asset_count: assets.len(),
            ready_asset_count,
            invalid_asset_count,
            ingesting_asset_count,
            conforming_asset_count,
            rebuilding_asset_count,
            assets,
            summary: format!(
                "assets={} ready={} invalid={} rebuilding={} cache_root={}",
                self.assets.len(),
                ready_asset_count,
                invalid_asset_count,
                rebuilding_asset_count,
                self.policy.cache_root.display(),
            ),
        }
    }

    fn service_snapshot(&self) -> RuntimeMediaServiceSnapshot {
        let indexed_asset_count = self.assets.len();
        let analysis_ready_asset_count = self
            .assets
            .values()
            .filter(|asset| asset.state == RuntimeMediaAssetState::Ready)
            .count();
        let invalidated_assets = self
            .assets
            .values()
            .filter(|asset| asset.state == RuntimeMediaAssetState::Invalid)
            .collect::<Vec<_>>();
        let invalidated_asset_count = invalidated_assets.len();
        let waveform_ready_asset_count = self
            .assets
            .values()
            .filter(|asset| {
                asset.registration.waveform_bin_count > 0
                    && asset.state == RuntimeMediaAssetState::Ready
            })
            .count();
        let waveform_pending_asset_count = self
            .assets
            .values()
            .filter(|asset| {
                asset.registration.waveform_bin_count > 0
                    && matches!(
                        asset.state,
                        RuntimeMediaAssetState::Ingesting
                            | RuntimeMediaAssetState::Conforming
                            | RuntimeMediaAssetState::Rebuilding
                    )
            })
            .count();
        let previewable_asset_count = analysis_ready_asset_count;
        let invalidation_active = invalidated_asset_count > 0;
        let indexing_state = if indexed_asset_count == 0 {
            RuntimeMediaIndexingState::Empty
        } else if self.assets.values().any(|asset| {
            matches!(
                asset.state,
                RuntimeMediaAssetState::Ingesting
                    | RuntimeMediaAssetState::Conforming
                    | RuntimeMediaAssetState::Rebuilding
            )
        }) {
            RuntimeMediaIndexingState::Syncing
        } else if invalidation_active {
            RuntimeMediaIndexingState::Invalidated
        } else {
            RuntimeMediaIndexingState::Ready
        };
        let preview_state = if self.previewing_asset_id.is_some() && previewable_asset_count > 0 {
            RuntimeMediaPreviewState::Previewing
        } else if previewable_asset_count > 0 {
            RuntimeMediaPreviewState::Ready
        } else if invalidation_active {
            RuntimeMediaPreviewState::Invalidated
        } else {
            RuntimeMediaPreviewState::Unavailable
        };
        let last_invalidated_asset = invalidated_assets.last().copied();

        RuntimeMediaServiceSnapshot {
            indexed_asset_count,
            analysis_ready_asset_count,
            waveform_ready_asset_count,
            waveform_pending_asset_count,
            previewable_asset_count,
            invalidated_asset_count,
            invalidation_active,
            indexing_state,
            preview_state,
            previewing_asset_id: self.previewing_asset_id.clone(),
            last_invalidated_asset_id: last_invalidated_asset
                .map(|asset| asset.registration.asset_id.clone()),
            last_invalidation_error: last_invalidated_asset
                .and_then(|asset| asset.last_error.clone()),
            last_preview_error: self.last_preview_error.clone(),
            summary: format!(
                "indexed={} ready={} waveform_ready={} waveform_pending={} previewable={} invalidated={} indexing={:?} preview={:?} previewing={} last_invalidated={} invalidation_error={} preview_error={}",
                indexed_asset_count,
                analysis_ready_asset_count,
                waveform_ready_asset_count,
                waveform_pending_asset_count,
                previewable_asset_count,
                invalidated_asset_count,
                indexing_state,
                preview_state,
                self.previewing_asset_id.as_deref().unwrap_or("none"),
                last_invalidated_asset
                    .map(|asset| asset.registration.asset_id.as_str())
                    .unwrap_or("none"),
                last_invalidated_asset
                    .and_then(|asset| asset.last_error.as_deref())
                    .unwrap_or("none"),
                self.last_preview_error.as_deref().unwrap_or("none"),
            ),
        }
    }

    fn library_service_snapshot(&self) -> RuntimeMediaLibraryServiceSnapshot {
        let descriptors = self
            .assets
            .values()
            .map(|asset| self.asset_library_descriptor(asset))
            .collect::<Vec<_>>();
        let ready_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.metadata_state == RuntimeMediaAnalysisDescriptorState::Ready
            })
            .count();
        let pending_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.metadata_state == RuntimeMediaAnalysisDescriptorState::Pending
            })
            .count();
        let invalidated_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.metadata_state == RuntimeMediaAnalysisDescriptorState::Invalidated
            })
            .count();
        let unavailable_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.metadata_state == RuntimeMediaAnalysisDescriptorState::Unavailable
            })
            .count();
        let loudness_ready_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.loudness_state == RuntimeMediaAnalysisFamilyState::Ready
            })
            .count();
        let character_ready_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.character_state == RuntimeMediaAnalysisFamilyState::Ready
            })
            .count();
        let rhythm_deferred_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.rhythm_state == RuntimeMediaAnalysisFamilyState::Deferred
            })
            .count();
        let tonal_deferred_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.tonal_state == RuntimeMediaAnalysisFamilyState::Deferred
            })
            .count();
        let embedding_deferred_descriptor_count = descriptors
            .iter()
            .filter(|descriptor| {
                descriptor.embedding_state == RuntimeMediaAnalysisFamilyState::Deferred
            })
            .count();

        RuntimeMediaLibraryServiceSnapshot {
            indexed_asset_count: descriptors.len(),
            ready_descriptor_count,
            pending_descriptor_count,
            invalidated_descriptor_count,
            unavailable_descriptor_count,
            loudness_ready_descriptor_count,
            character_ready_descriptor_count,
            rhythm_deferred_descriptor_count,
            tonal_deferred_descriptor_count,
            embedding_deferred_descriptor_count,
            descriptors,
            summary: format!(
                "indexed={} ready={} pending={} invalidated={} unavailable={} loudness_ready={} character_ready={} rhythm_deferred={} tonal_deferred={} embedding_deferred={}",
                self.assets.len(),
                ready_descriptor_count,
                pending_descriptor_count,
                invalidated_descriptor_count,
                unavailable_descriptor_count,
                loudness_ready_descriptor_count,
                character_ready_descriptor_count,
                rhythm_deferred_descriptor_count,
                tonal_deferred_descriptor_count,
                embedding_deferred_descriptor_count,
            ),
        }
    }

    fn asset_library_descriptor(
        &self,
        asset: &RuntimeMediaPipelineAsset,
    ) -> RuntimeMediaLibraryAssetDescriptor {
        RuntimeMediaLibraryAssetDescriptor {
            asset_id: asset.registration.asset_id.clone(),
            content_hash: asset.registration.content_hash.clone(),
            file_name: asset.registration.file_name.clone(),
            asset_state: Some(asset.state),
            metadata_state: asset.analysis.descriptor_state,
            loudness_state: media_family_state(
                asset.analysis.descriptor_state,
                asset.analysis.loudness.is_some(),
            ),
            character_state: media_family_state(
                asset.analysis.descriptor_state,
                asset.analysis.character.is_some(),
            ),
            rhythm_state: RuntimeMediaAnalysisFamilyState::Deferred,
            tonal_state: RuntimeMediaAnalysisFamilyState::Deferred,
            embedding_state: RuntimeMediaAnalysisFamilyState::Deferred,
            loudness: asset.analysis.loudness.clone(),
            character: asset.analysis.character.clone(),
            last_error: asset
                .analysis
                .last_error
                .clone()
                .or_else(|| asset.last_error.clone()),
            summary: format!(
                "asset={} state={:?} metadata={:?} loudness={:?} character={:?} rhythm={:?} tonal={:?} embedding={:?}",
                asset.registration.asset_id,
                asset.state,
                asset.analysis.descriptor_state,
                media_family_state(
                    asset.analysis.descriptor_state,
                    asset.analysis.loudness.is_some(),
                ),
                media_family_state(
                    asset.analysis.descriptor_state,
                    asset.analysis.character.is_some(),
                ),
                RuntimeMediaAnalysisFamilyState::Deferred,
                RuntimeMediaAnalysisFamilyState::Deferred,
                RuntimeMediaAnalysisFamilyState::Deferred,
            ),
        }
    }

    fn start_preview(&mut self, asset_id: &str) -> Result<(), RuntimeError> {
        let asset = self.assets.get(asset_id).ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!("media asset not indexed for preview: {asset_id}"),
            )
        })?;
        if asset.state != RuntimeMediaAssetState::Ready {
            let message = format!(
                "media asset not ready for preview: {asset_id} state={:?}",
                asset.state
            );
            self.previewing_asset_id = None;
            self.last_preview_error = Some(message.clone());
            return Err(RuntimeError::new(RuntimeErrorKind::InvalidState, message));
        }
        self.previewing_asset_id = Some(asset_id.to_string());
        self.last_preview_error = None;
        Ok(())
    }

    fn stop_preview(&mut self) {
        self.previewing_asset_id = None;
        self.last_preview_error = None;
    }

    fn reconcile_preview_state(&mut self) {
        if let Some(asset_id) = self.previewing_asset_id.clone() {
            match self.assets.get(&asset_id) {
                Some(asset) if asset.state == RuntimeMediaAssetState::Ready => {}
                Some(asset) => {
                    self.previewing_asset_id = None;
                    self.last_preview_error = Some(format!(
                        "preview invalidated for asset {} state={:?}",
                        asset.registration.asset_id, asset.state
                    ));
                }
                None => {
                    self.previewing_asset_id = None;
                    self.last_preview_error = Some(format!(
                        "preview asset removed from runtime index: {asset_id}"
                    ));
                }
            }
        }
    }

    fn reconcile_assets(
        &mut self,
        registrations: Vec<RuntimeMediaAssetRegistration>,
    ) -> Result<(), RuntimeError> {
        fs::create_dir_all(&self.policy.cache_root).map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to create media cache root {}: {error}",
                    self.policy.cache_root.display()
                ),
            )
        })?;

        let retained_ids = registrations
            .iter()
            .map(|asset| asset.asset_id.clone())
            .collect::<BTreeSet<_>>();
        self.assets
            .retain(|asset_id, _| retained_ids.contains(asset_id));

        for registration in registrations {
            let cache_path = self.cache_path_for(&registration);
            let cache_exists = cache_path.is_file();
            let rebuild = self
                .assets
                .get(&registration.asset_id)
                .map(|existing| {
                    existing.registration.content_hash != registration.content_hash
                        || existing.registration.source_path != registration.source_path
                        || !cache_exists
                })
                .unwrap_or(false);
            let mut asset =
                self.assets
                    .remove(&registration.asset_id)
                    .unwrap_or(RuntimeMediaPipelineAsset {
                        registration: registration.clone(),
                        state: RuntimeMediaAssetState::Ingesting,
                        cache_path: None,
                        cache_byte_size: None,
                        rebuild_count: 0,
                        last_error: None,
                        analysis: RuntimeMediaAnalysisStateModel::default(),
                    });
            asset.registration = registration;
            if rebuild {
                asset.rebuild_count = asset.rebuild_count.saturating_add(1);
                asset.state = RuntimeMediaAssetState::Rebuilding;
            } else if asset.cache_path.is_none() {
                asset.state = RuntimeMediaAssetState::Ingesting;
            }
            self.materialize_asset(&mut asset, &cache_path);
            self.assets
                .insert(asset.registration.asset_id.clone(), asset);
        }

        self.reconcile_preview_state();

        Ok(())
    }

    fn materialize_asset(&self, asset: &mut RuntimeMediaPipelineAsset, cache_path: &Path) {
        if asset.registration.source_path.trim().is_empty() {
            asset.state = RuntimeMediaAssetState::Invalid;
            asset.cache_path = None;
            asset.cache_byte_size = None;
            let message = "source path must not be empty".to_string();
            asset.last_error = Some(message.clone());
            asset.analysis.descriptor_state = RuntimeMediaAnalysisDescriptorState::Invalidated;
            asset.analysis.last_error = Some(message);
            return;
        }
        let source_path = Path::new(&asset.registration.source_path);
        if !source_path.is_file() {
            asset.state = RuntimeMediaAssetState::Invalid;
            asset.cache_path = None;
            asset.cache_byte_size = None;
            let message = format!("source media missing at {}", source_path.display());
            asset.last_error = Some(message.clone());
            asset.analysis.descriptor_state = RuntimeMediaAnalysisDescriptorState::Invalidated;
            asset.analysis.last_error = Some(message);
            return;
        }
        asset.state = if asset.rebuild_count > 0 {
            RuntimeMediaAssetState::Rebuilding
        } else {
            RuntimeMediaAssetState::Ingesting
        };
        asset.analysis.descriptor_state = RuntimeMediaAnalysisDescriptorState::Pending;
        asset.analysis.last_error = None;
        asset.state = RuntimeMediaAssetState::Conforming;
        match fs::copy(source_path, cache_path) {
            Ok(_) => match fs::metadata(cache_path) {
                Ok(metadata) => {
                    asset.state = RuntimeMediaAssetState::Ready;
                    asset.cache_path = Some(cache_path.display().to_string());
                    asset.cache_byte_size = Some(metadata.len());
                    asset.last_error = None;
                    match analyze_runtime_media_asset(cache_path, &asset.registration) {
                        Ok(analysis) => asset.analysis = analysis,
                        Err(error) => {
                            asset.analysis = RuntimeMediaAnalysisStateModel {
                                descriptor_state: RuntimeMediaAnalysisDescriptorState::Unavailable,
                                loudness: None,
                                character: None,
                                last_error: Some(error),
                            };
                        }
                    }
                }
                Err(error) => {
                    asset.state = RuntimeMediaAssetState::Invalid;
                    asset.cache_path = None;
                    asset.cache_byte_size = None;
                    let message =
                        format!("cached media written but metadata lookup failed: {error}");
                    asset.last_error = Some(message.clone());
                    asset.analysis.descriptor_state =
                        RuntimeMediaAnalysisDescriptorState::Invalidated;
                    asset.analysis.last_error = Some(message);
                }
            },
            Err(error) => {
                asset.state = RuntimeMediaAssetState::Invalid;
                asset.cache_path = None;
                asset.cache_byte_size = None;
                let message = format!("cache conform failed: {error}");
                asset.last_error = Some(message.clone());
                asset.analysis.descriptor_state = RuntimeMediaAnalysisDescriptorState::Invalidated;
                asset.analysis.last_error = Some(message);
            }
        }
    }

    fn cache_path_for(&self, registration: &RuntimeMediaAssetRegistration) -> PathBuf {
        let extension = Path::new(&registration.file_name)
            .extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("wav");
        self.policy.cache_root.join(format!(
            "{}-{}.{}",
            sanitize_asset_id(&registration.asset_id),
            registration.content_hash,
            extension
        ))
    }
}

impl Default for RuntimeMediaPipelineStateModel {
    fn default() -> Self {
        Self {
            policy: RuntimeMediaPipelinePolicy::default(),
            assets: BTreeMap::new(),
            previewing_asset_id: None,
            last_preview_error: None,
        }
    }
}

fn media_family_state(
    descriptor_state: RuntimeMediaAnalysisDescriptorState,
    available: bool,
) -> RuntimeMediaAnalysisFamilyState {
    if available && descriptor_state == RuntimeMediaAnalysisDescriptorState::Ready {
        RuntimeMediaAnalysisFamilyState::Ready
    } else if matches!(
        descriptor_state,
        RuntimeMediaAnalysisDescriptorState::Unavailable
    ) {
        RuntimeMediaAnalysisFamilyState::Unavailable
    } else {
        RuntimeMediaAnalysisFamilyState::Deferred
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
struct RuntimeTempoMapStateModel {
    projection: Option<RuntimeTempoMapProjection>,
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeResolvedTempo {
    tempo_bpm: f64,
    source: RuntimeTempoSource,
    active_segment_id: Option<String>,
    active_segment_index: Option<usize>,
    next_segment_start_samples: Option<i64>,
    timeline_position_samples: Option<i64>,
}

impl RuntimeTempoMapStateModel {
    fn apply_projection(&mut self, mut projection: RuntimeTempoMapProjection) {
        projection.segment_count = projection.segments.len();
        projection
            .segments
            .sort_by_key(|segment| (segment.start_samples, segment.segment_id.clone()));
        self.projection = Some(projection);
    }

    fn resolve(
        &self,
        timeline_position_samples: Option<i64>,
        projected_transport: Option<TransportProjection>,
        observed_tempo_bpm: Option<f64>,
    ) -> RuntimeResolvedTempo {
        let projected_tempo_bpm = projected_transport
            .map(|transport| transport.tempo_bpm)
            .or(observed_tempo_bpm)
            .filter(|tempo| tempo.is_finite() && *tempo > 0.0);
        let mut resolved = RuntimeResolvedTempo {
            tempo_bpm: projected_tempo_bpm.unwrap_or(120.0),
            source: if projected_tempo_bpm.is_some() {
                RuntimeTempoSource::TransportProjection
            } else {
                RuntimeTempoSource::DefaultFallback
            },
            active_segment_id: None,
            active_segment_index: None,
            next_segment_start_samples: None,
            timeline_position_samples,
        };

        let Some(position) = timeline_position_samples else {
            return resolved;
        };
        let Some(projection) = self.projection.as_ref() else {
            return resolved;
        };

        for (index, segment) in projection.segments.iter().enumerate() {
            if segment.start_samples > position {
                resolved.next_segment_start_samples = Some(segment.start_samples);
                break;
            }
            let segment_end = segment.end_samples.unwrap_or(i64::MAX);
            if position < segment_end {
                resolved.tempo_bpm = resolved_tempo_for_segment(segment, position);
                resolved.source = RuntimeTempoSource::TempoMapSegment;
                resolved.active_segment_id = Some(segment.segment_id.clone());
                resolved.active_segment_index = Some(index);
                resolved.next_segment_start_samples = projection
                    .segments
                    .get(index + 1)
                    .map(|next| next.start_samples);
                break;
            }
        }

        resolved
    }

    fn snapshot(&self, resolved: &RuntimeResolvedTempo) -> RuntimeTempoMapSnapshot {
        let segments = self
            .projection
            .as_ref()
            .map(|projection| {
                projection
                    .segments
                    .iter()
                    .enumerate()
                    .map(|(index, segment)| RuntimeTempoMapSegmentSnapshot {
                        segment_id: segment.segment_id.clone(),
                        start_samples: segment.start_samples,
                        end_samples: segment.end_samples,
                        start_tempo_bpm: segment.start_tempo_bpm,
                        end_tempo_bpm: segment.end_tempo_bpm,
                        interpolation: segment.interpolation,
                        covers_timeline_position: resolved.active_segment_index == Some(index),
                        summary: format!(
                            "segment={} interpolation={:?} start={} end={:?} tempo={:.3}->{:?}",
                            segment.segment_id,
                            segment.interpolation,
                            segment.start_samples,
                            segment.end_samples,
                            segment.start_tempo_bpm,
                            segment.end_tempo_bpm,
                        ),
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        RuntimeTempoMapSnapshot {
            segment_count: segments.len(),
            active_segment_id: resolved.active_segment_id.clone(),
            active_segment_index: resolved.active_segment_index,
            next_segment_start_samples: resolved.next_segment_start_samples,
            resolved_tempo_bpm: resolved.tempo_bpm,
            tempo_source: resolved.source,
            timeline_position_samples: resolved.timeline_position_samples,
            segments,
            summary: format!(
                "tempo_map segments={} active={:?}/{:?} source={:?} tempo={:.3} next_segment={:?}",
                self.projection
                    .as_ref()
                    .map_or(0, |projection| projection.segment_count),
                resolved.active_segment_index,
                resolved.active_segment_id,
                resolved.source,
                resolved.tempo_bpm,
                resolved.next_segment_start_samples,
            ),
        }
    }
}

fn resolved_tempo_for_segment(segment: &RuntimeTempoMapSegmentProjection, position: i64) -> f64 {
    match (
        segment.interpolation,
        segment.end_samples,
        segment.end_tempo_bpm,
    ) {
        (RuntimeTempoMapInterpolation::Linear, Some(end_samples), Some(end_tempo_bpm))
            if end_samples > segment.start_samples =>
        {
            let span = (end_samples - segment.start_samples) as f64;
            let offset = (position - segment.start_samples)
                .clamp(0, end_samples - segment.start_samples) as f64;
            segment.start_tempo_bpm + ((end_tempo_bpm - segment.start_tempo_bpm) * (offset / span))
        }
        _ => segment.start_tempo_bpm,
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
struct RuntimeWarpPipelineStateModel {
    clips: BTreeMap<String, RuntimeWarpClipRegistration>,
}

impl RuntimeWarpPipelineStateModel {
    fn snapshot(
        &self,
        resolved_tempo: &RuntimeResolvedTempo,
        media_pipeline: &RuntimeMediaPipelineStateModel,
    ) -> RuntimeWarpPipelineSnapshot {
        let project_tempo_bpm =
            if resolved_tempo.tempo_bpm.is_finite() && resolved_tempo.tempo_bpm > 0.0 {
                resolved_tempo.tempo_bpm
            } else {
                120.0
            };
        let clips = self
            .clips
            .values()
            .map(|registration| {
                self.snapshot_clip(registration, resolved_tempo, &media_pipeline.assets)
            })
            .collect::<Vec<_>>();
        let ready_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeWarpReadiness::Ready)
            .count();
        let degraded_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeWarpReadiness::Degraded)
            .count();
        let bypassed_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeWarpReadiness::Bypassed)
            .count();
        let active_warp_count = clips
            .iter()
            .filter(|clip| clip.mode != RuntimeWarpMode::Off)
            .count();

        RuntimeWarpPipelineSnapshot {
            clip_count: clips.len(),
            ready_clip_count,
            degraded_clip_count,
            bypassed_clip_count,
            active_warp_count,
            resolved_project_tempo_bpm: project_tempo_bpm,
            resolved_project_tempo_source: resolved_tempo.source,
            resolved_project_tempo_segment_id: resolved_tempo.active_segment_id.clone(),
            clips,
            summary: format!(
                "warp clips={} active={} ready={} degraded={} bypassed={} project_tempo={project_tempo_bpm:.2} source={:?} segment={:?}",
                self.clips.len(),
                active_warp_count,
                ready_clip_count,
                degraded_clip_count,
                bypassed_clip_count,
                resolved_tempo.source,
                resolved_tempo.active_segment_id,
            ),
        }
    }

    fn snapshot_clip(
        &self,
        registration: &RuntimeWarpClipRegistration,
        resolved_tempo: &RuntimeResolvedTempo,
        media_assets: &BTreeMap<String, RuntimeMediaPipelineAsset>,
    ) -> RuntimeWarpClipSnapshot {
        let project_tempo_bpm =
            if resolved_tempo.tempo_bpm.is_finite() && resolved_tempo.tempo_bpm > 0.0 {
                resolved_tempo.tempo_bpm
            } else {
                120.0
            };
        let mut realized_ratio = 1.0;
        let (readiness, last_error) = match registration.mode {
            RuntimeWarpMode::Off => (RuntimeWarpReadiness::Bypassed, None),
            RuntimeWarpMode::Repitch | RuntimeWarpMode::ElastiqueDraft => {
                match registration.source_tempo_bpm {
                    Some(source_tempo_bpm)
                        if source_tempo_bpm.is_finite() && source_tempo_bpm > 0.0 =>
                    {
                        realized_ratio = project_tempo_bpm / source_tempo_bpm;
                        if !realized_ratio.is_finite() || realized_ratio <= 0.0 {
                            (
                                RuntimeWarpReadiness::Degraded,
                                Some("warp ratio is invalid".to_string()),
                            )
                        } else if let Some(media_asset_id) = registration.media_asset_id.as_deref()
                        {
                            match media_assets.get(media_asset_id) {
                                Some(asset) if asset.state == RuntimeMediaAssetState::Ready => {
                                    if registration.mode == RuntimeWarpMode::ElastiqueDraft
                                        && !(0.5..=2.0).contains(&realized_ratio)
                                    {
                                        (
                                            RuntimeWarpReadiness::Degraded,
                                            Some(format!(
                                                "elastique draft ratio {realized_ratio:.3} outside baseline support"
                                            )),
                                        )
                                    } else {
                                        (RuntimeWarpReadiness::Ready, None)
                                    }
                                }
                                Some(asset) => (
                                    RuntimeWarpReadiness::Degraded,
                                    Some(format!("media asset not ready: {:?}", asset.state)),
                                ),
                                None => (
                                    RuntimeWarpReadiness::Degraded,
                                    Some(format!(
                                        "media asset `{media_asset_id}` missing from runtime cache"
                                    )),
                                ),
                            }
                        } else {
                            (
                                RuntimeWarpReadiness::Degraded,
                                Some("warp clip missing media asset".to_string()),
                            )
                        }
                    }
                    Some(_) => (
                        RuntimeWarpReadiness::Degraded,
                        Some("warp source tempo must be positive".to_string()),
                    ),
                    None => (
                        RuntimeWarpReadiness::Degraded,
                        Some("warp source tempo missing".to_string()),
                    ),
                }
            }
        };

        RuntimeWarpClipSnapshot {
            clip_id: registration.clip_id.clone(),
            media_asset_id: registration.media_asset_id.clone(),
            mode: registration.mode,
            source_tempo_bpm: registration.source_tempo_bpm,
            project_tempo_bpm,
            project_tempo_source: resolved_tempo.source,
            project_tempo_segment_id: resolved_tempo.active_segment_id.clone(),
            realized_ratio,
            anchor_timeline_samples: registration.anchor_timeline_samples,
            start_samples: registration.start_samples,
            duration_samples: registration.duration_samples,
            readiness,
            last_error: last_error.clone(),
            summary: format!(
                "clip={} mode={:?} readiness={:?} ratio={realized_ratio:.3} source_tempo={} project_tempo={project_tempo_bpm:.2}/{:?}/{:?} error={}",
                registration.clip_id,
                registration.mode,
                readiness,
                registration
                    .source_tempo_bpm
                    .map(|tempo| format!("{tempo:.2}"))
                    .unwrap_or_else(|| "none".to_string()),
                resolved_tempo.source,
                resolved_tempo.active_segment_id,
                last_error.as_deref().unwrap_or("none"),
            ),
        }
    }

    fn reconcile_clips(&mut self, clips: Vec<RuntimeWarpClipRegistration>) {
        let retained_ids = clips
            .iter()
            .map(|clip| clip.clip_id.clone())
            .collect::<BTreeSet<_>>();
        self.clips
            .retain(|clip_id, _| retained_ids.contains(clip_id));
        for clip in clips {
            self.clips.insert(clip.clip_id.clone(), clip);
        }
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
struct RuntimeClipProcessingPipelineStateModel {
    clips: BTreeMap<String, RuntimeClipProcessingRegistration>,
}

impl RuntimeClipProcessingPipelineStateModel {
    fn treatment_stages(
        &self,
        registration: &RuntimeClipProcessingRegistration,
    ) -> Vec<RuntimeClipProcessingStage> {
        let mut stages = Vec::new();
        if registration.warp_mode != RuntimeWarpMode::Off {
            stages.push(RuntimeClipProcessingStage::Warp);
        }
        if registration.fade_in.duration_samples > 0 {
            stages.push(RuntimeClipProcessingStage::FadeIn);
        }
        if registration.clip_gain.shape != RuntimeClipGainShape::Hold
            || (registration.clip_gain.start_linear - 1.0).abs() > f32::EPSILON
            || (registration.clip_gain.end_linear - 1.0).abs() > f32::EPSILON
        {
            stages.push(RuntimeClipProcessingStage::GainShape);
        }
        if registration.fade_out.duration_samples > 0 {
            stages.push(RuntimeClipProcessingStage::FadeOut);
        }
        stages
    }

    fn warp_context(
        &self,
        registration: &RuntimeClipProcessingRegistration,
        warp_clips: &[RuntimeWarpClipSnapshot],
    ) -> (Option<f64>, Option<RuntimeTempoSource>, Option<String>) {
        warp_clips
            .iter()
            .find(|clip| clip.clip_id == registration.clip_id)
            .map(|clip| {
                (
                    Some(clip.realized_ratio),
                    Some(clip.project_tempo_source),
                    clip.project_tempo_segment_id.clone(),
                )
            })
            .unwrap_or((None, None, None))
    }

    fn validate_registration(
        &self,
        registration: &RuntimeClipProcessingRegistration,
    ) -> Option<String> {
        if !registration.clip_gain.start_linear.is_finite()
            || !registration.clip_gain.end_linear.is_finite()
            || registration.clip_gain.start_linear < 0.0
            || registration.clip_gain.end_linear < 0.0
        {
            return Some("clip gain envelope must be finite and non-negative".to_string());
        }
        if registration.clip_gain.shape == RuntimeClipGainShape::Hold
            && (registration.clip_gain.start_linear - registration.clip_gain.end_linear).abs()
                > f32::EPSILON
        {
            return Some("hold clip gain shape requires identical start and end gain".to_string());
        }
        if u64::from(registration.fade_in.duration_samples)
            + u64::from(registration.fade_out.duration_samples)
            > u64::from(registration.duration_samples)
        {
            return Some("clip fades exceed clip duration".to_string());
        }
        None
    }

    fn snapshot(
        &self,
        media_pipeline: &RuntimeMediaPipelineStateModel,
        warp_pipeline: &RuntimeWarpPipelineStateModel,
        resolved_tempo: &RuntimeResolvedTempo,
    ) -> RuntimeClipProcessingPipelineSnapshot {
        let warp_snapshot = warp_pipeline.snapshot(resolved_tempo, media_pipeline);
        let clips = self
            .clips
            .values()
            .map(|registration| {
                self.snapshot_clip(registration, media_pipeline, &warp_snapshot.clips)
            })
            .collect::<Vec<_>>();
        let ready_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeClipProcessingReadiness::Ready)
            .count();
        let pending_media_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeClipProcessingReadiness::PendingMedia)
            .count();
        let pending_warp_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeClipProcessingReadiness::PendingWarp)
            .count();
        let invalid_clip_count = clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeClipProcessingReadiness::Invalid)
            .count();
        let faded_clip_count = clips
            .iter()
            .filter(|clip| clip.fade_in.duration_samples > 0 || clip.fade_out.duration_samples > 0)
            .count();
        let gain_shaped_clip_count = clips
            .iter()
            .filter(|clip| {
                clip.clip_gain.shape != RuntimeClipGainShape::Hold
                    || (clip.clip_gain.start_linear - 1.0).abs() > f32::EPSILON
                    || (clip.clip_gain.end_linear - 1.0).abs() > f32::EPSILON
            })
            .count();
        let warped_clip_count = clips
            .iter()
            .filter(|clip| clip.realized_warp_ratio.is_some())
            .count();
        let treatment_stage_count = clips.iter().map(|clip| clip.treatment_stages.len()).sum();

        RuntimeClipProcessingPipelineSnapshot {
            clip_count: clips.len(),
            ready_clip_count,
            pending_media_clip_count,
            pending_warp_clip_count,
            invalid_clip_count,
            faded_clip_count,
            gain_shaped_clip_count,
            warped_clip_count,
            treatment_stage_count,
            clips,
            summary: format!(
                "clip_processing clips={} ready={} pending_media={} pending_warp={} invalid={} faded={} gain_shaped={} warped={} treatment_stages={}",
                self.clips.len(),
                ready_clip_count,
                pending_media_clip_count,
                pending_warp_clip_count,
                invalid_clip_count,
                faded_clip_count,
                gain_shaped_clip_count,
                warped_clip_count,
                treatment_stage_count,
            ),
        }
    }

    fn snapshot_clip(
        &self,
        registration: &RuntimeClipProcessingRegistration,
        media_pipeline: &RuntimeMediaPipelineStateModel,
        warp_clips: &[RuntimeWarpClipSnapshot],
    ) -> RuntimeClipProcessingSnapshot {
        let fade_in_end_samples = registration
            .start_samples
            .saturating_add(i64::from(registration.fade_in.duration_samples));
        let fade_out_start_samples = registration.start_samples.saturating_add(i64::from(
            registration
                .duration_samples
                .saturating_sub(registration.fade_out.duration_samples),
        ));
        let treatment_stages = self.treatment_stages(registration);
        let treatment_stages_summary = treatment_stages.clone();
        let (realized_warp_ratio, project_tempo_source, project_tempo_segment_id) =
            self.warp_context(registration, warp_clips);
        let project_tempo_segment_id_summary = project_tempo_segment_id.clone();
        let (readiness, last_error) = if let Some(error) = self.validate_registration(registration)
        {
            (RuntimeClipProcessingReadiness::Invalid, Some(error))
        } else if let Some(media_asset_id) = registration.media_asset_id.as_deref() {
            match media_pipeline.assets.get(media_asset_id) {
                Some(asset) if asset.state == RuntimeMediaAssetState::Ready => {
                    if registration.warp_mode == RuntimeWarpMode::Off {
                        (RuntimeClipProcessingReadiness::Ready, None)
                    } else if let Some(warp_clip) = warp_clips
                        .iter()
                        .find(|clip| clip.clip_id == registration.clip_id)
                    {
                        match warp_clip.readiness {
                            RuntimeWarpReadiness::Ready | RuntimeWarpReadiness::Bypassed => {
                                (RuntimeClipProcessingReadiness::Ready, None)
                            }
                            RuntimeWarpReadiness::Degraded => (
                                RuntimeClipProcessingReadiness::Invalid,
                                warp_clip
                                    .last_error
                                    .clone()
                                    .or_else(|| Some("warp processing degraded".to_string())),
                            ),
                        }
                    } else {
                        (
                            RuntimeClipProcessingReadiness::PendingWarp,
                            Some("warp pipeline has not realized this clip yet".to_string()),
                        )
                    }
                }
                Some(asset)
                    if matches!(
                        asset.state,
                        RuntimeMediaAssetState::Ingesting
                            | RuntimeMediaAssetState::Conforming
                            | RuntimeMediaAssetState::Rebuilding
                    ) =>
                {
                    (
                        RuntimeClipProcessingReadiness::PendingMedia,
                        Some(format!("media asset not ready: {:?}", asset.state)),
                    )
                }
                Some(asset) => (
                    RuntimeClipProcessingReadiness::Invalid,
                    Some(format!("media asset invalid: {:?}", asset.state)),
                ),
                None => (
                    RuntimeClipProcessingReadiness::PendingMedia,
                    Some(format!(
                        "media asset `{media_asset_id}` not yet available in runtime cache"
                    )),
                ),
            }
        } else if registration.warp_mode != RuntimeWarpMode::Off {
            (
                RuntimeClipProcessingReadiness::Invalid,
                Some("warp-enabled clip has no media asset".to_string()),
            )
        } else {
            (RuntimeClipProcessingReadiness::Ready, None)
        };

        RuntimeClipProcessingSnapshot {
            clip_id: registration.clip_id.clone(),
            media_asset_id: registration.media_asset_id.clone(),
            warp_mode: registration.warp_mode,
            start_samples: registration.start_samples,
            duration_samples: registration.duration_samples,
            fade_in: registration.fade_in.clone(),
            fade_out: registration.fade_out.clone(),
            fade_in_end_samples,
            fade_out_start_samples,
            clip_gain: registration.clip_gain.clone(),
            treatment_stages,
            realized_warp_ratio,
            project_tempo_source,
            project_tempo_segment_id,
            readiness,
            last_error: last_error.clone(),
            summary: format!(
                "clip={} readiness={:?} gain={:.3}->{:.3}/{:?} fade_in={}/{:?} fade_out={}/{:?} stages={:?} media={} warp={:?} warp_ratio={:?} tempo={:?}/{:?} error={}",
                registration.clip_id,
                readiness,
                registration.clip_gain.start_linear,
                registration.clip_gain.end_linear,
                registration.clip_gain.shape,
                registration.fade_in.duration_samples,
                registration.fade_in.shape,
                registration.fade_out.duration_samples,
                registration.fade_out.shape,
                treatment_stages_summary,
                registration.media_asset_id.as_deref().unwrap_or("none"),
                registration.warp_mode,
                realized_warp_ratio,
                project_tempo_source,
                project_tempo_segment_id_summary,
                last_error.as_deref().unwrap_or("none"),
            ),
        }
    }

    fn render_clip(
        &self,
        request: RuntimeClipRenderRequest,
        media_pipeline: &RuntimeMediaPipelineStateModel,
        warp_pipeline: &RuntimeWarpPipelineStateModel,
        resolved_tempo: &RuntimeResolvedTempo,
        transform_artifact_snapshot: RuntimeTransformArtifactClipSnapshot,
        preview_transform_snapshot: RuntimePreviewTransformClipSnapshot,
    ) -> Result<RuntimeClipRenderResult, RuntimeError> {
        let registration = self.clips.get(&request.clip_id).ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!(
                    "clip processing render request references unknown clip `{}`",
                    request.clip_id
                ),
            )
        })?;
        let warp_snapshot = warp_pipeline.snapshot(resolved_tempo, media_pipeline);
        let clip_processing_snapshot =
            self.snapshot_clip(registration, media_pipeline, &warp_snapshot.clips);
        let stretch_engine_snapshot =
            RuntimeStretchClipSnapshot::from_clip_processing_snapshot(&clip_processing_snapshot);
        if clip_processing_snapshot.readiness != RuntimeClipProcessingReadiness::Ready {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                clip_processing_snapshot
                    .last_error
                    .clone()
                    .unwrap_or_else(|| "clip processing render path is not ready".to_string()),
            ));
        }
        if registration.warp_mode != RuntimeWarpMode::Off
            && request.input_stage != RuntimeClipRenderInputStage::PostWarp
        {
            return Err(RuntimeError::new(
                RuntimeErrorKind::UnsupportedCapability,
                "warp-enabled clip render requests currently require post-warp input",
            ));
        }

        let mut output = request.buffer;
        let mut first_frame_gain = None;
        let mut last_frame_gain = None;
        let mut peak_applied_gain: Option<f32> = None;
        let channels = output.channel_count().0;
        for frame_index in 0..output.frames().0 {
            let timeline_position_samples = request
                .timeline_start_samples
                .saturating_add(frame_index as i64);
            let gain = Self::clip_frame_gain(registration, timeline_position_samples);
            if frame_index == 0 {
                first_frame_gain = Some(gain);
            }
            last_frame_gain = Some(gain);
            peak_applied_gain = Some(
                peak_applied_gain
                    .map(|current| current.max(gain))
                    .unwrap_or(gain),
            );
            let frame_start = frame_index.saturating_mul(channels);
            let frame_end = frame_start.saturating_add(channels);
            for sample in &mut output.samples_mut()[frame_start..frame_end] {
                *sample *= gain;
            }
        }

        let timeline_end_samples = request
            .timeline_start_samples
            .saturating_add(output.frames().0 as i64);
        Ok(RuntimeClipRenderResult {
            clip_id: request.clip_id,
            timeline_start_samples: request.timeline_start_samples,
            timeline_end_samples,
            input_stage: request.input_stage,
            clip_processing_snapshot: clip_processing_snapshot.clone(),
            stretch_engine_snapshot: stretch_engine_snapshot.clone(),
            transform_artifact_snapshot: transform_artifact_snapshot.clone(),
            preview_transform_snapshot: preview_transform_snapshot.clone(),
            first_frame_gain,
            last_frame_gain,
            peak_applied_gain,
            output,
            summary: format!(
                "clip_render clip={} input_stage={:?} timeline={}..{} stretch={:?}/{:?}/{:?} transform={:?}/{:?}/cached_media={} preview={:?}/{:?}/{:?}/{:?} first_gain={:?} last_gain={:?} peak_gain={:?} stages={:?}",
                clip_processing_snapshot.clip_id,
                request.input_stage,
                request.timeline_start_samples,
                timeline_end_samples,
                stretch_engine_snapshot.engine_class,
                stretch_engine_snapshot.readiness,
                stretch_engine_snapshot.fallback_kind,
                transform_artifact_snapshot.readiness,
                transform_artifact_snapshot.reuse_state,
                transform_artifact_snapshot.cached_media_ready,
                preview_transform_snapshot.service_class,
                preview_transform_snapshot.readiness,
                preview_transform_snapshot.degraded_state,
                preview_transform_snapshot.fallback_kind,
                first_frame_gain,
                last_frame_gain,
                peak_applied_gain,
                clip_processing_snapshot.treatment_stages,
            ),
        })
    }

    fn clip_frame_gain(
        registration: &RuntimeClipProcessingRegistration,
        timeline_position_samples: i64,
    ) -> f32 {
        let clip_offset_samples =
            timeline_position_samples.saturating_sub(registration.start_samples);
        if clip_offset_samples < 0
            || clip_offset_samples >= i64::from(registration.duration_samples)
        {
            return 0.0;
        }
        let clip_offset_samples = clip_offset_samples as u32;
        let fade_in_gain = Self::fade_in_gain(registration, clip_offset_samples);
        let fade_out_gain = Self::fade_out_gain(registration, clip_offset_samples);
        let gain_shape = Self::gain_shape_gain(registration, clip_offset_samples);
        fade_in_gain * fade_out_gain * gain_shape
    }

    fn fade_in_gain(
        registration: &RuntimeClipProcessingRegistration,
        clip_offset_samples: u32,
    ) -> f32 {
        let fade_in = registration.fade_in.duration_samples;
        if fade_in == 0 {
            return 1.0;
        }
        if clip_offset_samples >= fade_in {
            return 1.0;
        }
        if fade_in == 1 {
            return 1.0;
        }
        let progress = clip_offset_samples as f32 / (fade_in - 1) as f32;
        Self::fade_shape_gain(registration.fade_in.shape, progress)
    }

    fn fade_out_gain(
        registration: &RuntimeClipProcessingRegistration,
        clip_offset_samples: u32,
    ) -> f32 {
        let fade_out = registration.fade_out.duration_samples;
        if fade_out == 0 {
            return 1.0;
        }
        let fade_out_start = registration.duration_samples.saturating_sub(fade_out);
        if clip_offset_samples < fade_out_start {
            return 1.0;
        }
        if fade_out == 1 {
            return 0.0;
        }
        let fade_offset = clip_offset_samples.saturating_sub(fade_out_start) as f32;
        let progress = 1.0 - (fade_offset / (fade_out - 1) as f32);
        Self::fade_shape_gain(registration.fade_out.shape, progress)
    }

    fn fade_shape_gain(shape: RuntimeClipFadeShape, progress: f32) -> f32 {
        let progress = progress.clamp(0.0, 1.0);
        match shape {
            RuntimeClipFadeShape::Linear => progress,
            RuntimeClipFadeShape::EqualPower => (progress * std::f32::consts::FRAC_PI_2).sin(),
            RuntimeClipFadeShape::SmoothStep => progress * progress * (3.0 - 2.0 * progress),
        }
    }

    fn gain_shape_gain(
        registration: &RuntimeClipProcessingRegistration,
        clip_offset_samples: u32,
    ) -> f32 {
        match registration.clip_gain.shape {
            RuntimeClipGainShape::Hold => registration.clip_gain.start_linear,
            RuntimeClipGainShape::Linear => {
                if registration.duration_samples <= 1 {
                    return registration.clip_gain.end_linear;
                }
                let progress =
                    clip_offset_samples as f32 / (registration.duration_samples - 1) as f32;
                registration.clip_gain.start_linear
                    + (registration.clip_gain.end_linear - registration.clip_gain.start_linear)
                        * progress.clamp(0.0, 1.0)
            }
        }
    }

    fn reconcile_clips(&mut self, clips: Vec<RuntimeClipProcessingRegistration>) {
        let retained_ids = clips
            .iter()
            .map(|clip| clip.clip_id.clone())
            .collect::<BTreeSet<_>>();
        self.clips
            .retain(|clip_id, _| retained_ids.contains(clip_id));
        for clip in clips {
            self.clips.insert(clip.clip_id.clone(), clip);
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeRecordingCaptureActiveSession {
    capture_kind: RuntimeRecordingCaptureKind,
    take_id: String,
    track_id: String,
    start_samples: i64,
    capture_path: String,
    sample_rate_hz: u32,
    channel_count: usize,
    samples: Vec<f32>,
    buffered_block_count: u64,
    buffered_frame_count: u64,
    buffered_event_count: u64,
    peak_level: f32,
    pressure_event_count: u64,
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeRecordingCaptureStateModel {
    policy: RuntimeRecordingCapturePolicy,
    active: Option<RuntimeRecordingCaptureActiveSession>,
    last_committed_take_id: Option<String>,
    last_committed_path: Option<String>,
    last_committed_duration_samples: Option<u32>,
    last_checkpoint: Option<RuntimeRecordingCaptureCheckpointSnapshot>,
    last_error: Option<String>,
}

impl RuntimeRecordingCaptureStateModel {
    fn capture_ready(&self, configured: bool, readiness: &RuntimeReadiness) -> bool {
        configured
            && !matches!(
                readiness,
                RuntimeReadiness::Stopped | RuntimeReadiness::Failed { .. }
            )
    }

    fn snapshot(
        &self,
        configured: bool,
        readiness: &RuntimeReadiness,
    ) -> RuntimeRecordingCaptureSnapshot {
        let active_checkpoint = self
            .active
            .as_ref()
            .map(|active| self.active_checkpoint(active, readiness));
        let state = if self.last_error.is_some() {
            Some(RuntimeRecordingCaptureState::Failed)
        } else if self.active.is_some() {
            Some(RuntimeRecordingCaptureState::Capturing)
        } else {
            Some(RuntimeRecordingCaptureState::Idle)
        };
        let summary = if let Some(checkpoint) = active_checkpoint.as_ref() {
            format!(
                "state=capturing ready={} kind={:?} checkpoint={:?}/{:?} take={} track={} frames={} events={} blocks={} pressure={} path={}",
                self.capture_ready(configured, readiness),
                checkpoint.capture_kind,
                checkpoint.checkpoint_class,
                checkpoint.interruption_class,
                checkpoint.take_id,
                checkpoint.track_id,
                checkpoint.buffered_frame_count,
                checkpoint.buffered_event_count,
                checkpoint.buffered_block_count,
                checkpoint.pressure_event_count,
                checkpoint.capture_path
            )
        } else {
            format!(
                "state={} ready={} last_take={} last_path={} duration={} last_checkpoint={:?}/{:?} error={}",
                if self.last_error.is_some() {
                    "failed"
                } else {
                    "idle"
                },
                self.capture_ready(configured, readiness),
                self.last_committed_take_id.as_deref().unwrap_or("none"),
                self.last_committed_path.as_deref().unwrap_or("none"),
                self.last_committed_duration_samples.unwrap_or(0),
                self.last_checkpoint.as_ref().map(|checkpoint| checkpoint.checkpoint_class),
                self.last_checkpoint
                    .as_ref()
                    .map(|checkpoint| checkpoint.interruption_class),
                self.last_error.as_deref().unwrap_or("none"),
            )
        };

        RuntimeRecordingCaptureSnapshot {
            capture_ready: self.capture_ready(configured, readiness),
            state,
            capture_kind: self
                .active
                .as_ref()
                .map(|active| active.capture_kind)
                .or_else(|| {
                    self.last_checkpoint
                        .as_ref()
                        .map(|checkpoint| checkpoint.capture_kind)
                }),
            active_take_id: self.active.as_ref().map(|active| active.take_id.clone()),
            active_track_id: self.active.as_ref().map(|active| active.track_id.clone()),
            capture_start_samples: self.active.as_ref().map(|active| active.start_samples),
            active_capture_path: self
                .active
                .as_ref()
                .map(|active| active.capture_path.clone()),
            buffered_block_count: self
                .active
                .as_ref()
                .map(|active| active.buffered_block_count)
                .unwrap_or(0),
            buffered_frame_count: self
                .active
                .as_ref()
                .map(|active| active.buffered_frame_count)
                .unwrap_or(0),
            buffered_event_count: self
                .active
                .as_ref()
                .map(|active| active.buffered_event_count)
                .unwrap_or(0),
            captured_channel_count: self
                .active
                .as_ref()
                .map(|active| active.channel_count)
                .unwrap_or(0),
            peak_level: self.active.as_ref().map(|active| active.peak_level),
            pressure_event_count: self
                .active
                .as_ref()
                .map(|active| active.pressure_event_count)
                .unwrap_or(0),
            active_checkpoint,
            last_checkpoint: self.last_checkpoint.clone(),
            last_committed_take_id: self.last_committed_take_id.clone(),
            last_committed_path: self.last_committed_path.clone(),
            last_committed_duration_samples: self.last_committed_duration_samples,
            last_error: self.last_error.clone(),
            summary,
        }
    }

    fn active_checkpoint(
        &self,
        active: &RuntimeRecordingCaptureActiveSession,
        readiness: &RuntimeReadiness,
    ) -> RuntimeRecordingCaptureCheckpointSnapshot {
        let checkpoint_class = if self.last_error.is_some() {
            RuntimeRecordingCaptureCheckpointClass::Failed
        } else if active.buffered_frame_count > 0 || active.buffered_event_count > 0 {
            RuntimeRecordingCaptureCheckpointClass::Streaming
        } else {
            RuntimeRecordingCaptureCheckpointClass::Armed
        };
        let interruption_class = if self.last_error.is_some() {
            RuntimeInterruptionClass::Terminal
        } else if matches!(readiness, RuntimeReadiness::Degraded { .. }) {
            RuntimeInterruptionClass::Resumable
        } else {
            RuntimeInterruptionClass::Steady
        };
        self.checkpoint_from_active(
            active,
            checkpoint_class,
            interruption_class,
            self.last_error.clone(),
            if self.last_error.is_some() {
                "active capture failed"
            } else {
                "active capture checkpoint"
            },
        )
    }

    fn checkpoint_from_active(
        &self,
        active: &RuntimeRecordingCaptureActiveSession,
        checkpoint_class: RuntimeRecordingCaptureCheckpointClass,
        interruption_class: RuntimeInterruptionClass,
        last_error: Option<String>,
        reason: &str,
    ) -> RuntimeRecordingCaptureCheckpointSnapshot {
        RuntimeRecordingCaptureCheckpointSnapshot {
            capture_kind: active.capture_kind,
            checkpoint_class,
            interruption_class,
            take_id: active.take_id.clone(),
            track_id: active.track_id.clone(),
            capture_start_samples: active.start_samples,
            capture_path: active.capture_path.clone(),
            buffered_block_count: active.buffered_block_count,
            buffered_frame_count: active.buffered_frame_count,
            buffered_event_count: active.buffered_event_count,
            captured_channel_count: active.channel_count,
            peak_level: (active.channel_count > 0).then_some(active.peak_level),
            pressure_event_count: active.pressure_event_count,
            last_error,
            summary: format!(
                "kind={:?} checkpoint={:?} interruption={:?} take={} track={} frames={} events={} blocks={} pressure={} reason={} path={}",
                active.capture_kind,
                checkpoint_class,
                interruption_class,
                active.take_id,
                active.track_id,
                active.buffered_frame_count,
                active.buffered_event_count,
                active.buffered_block_count,
                active.pressure_event_count,
                reason,
                active.capture_path,
            ),
        }
    }

    fn interrupt_active_capture(
        &mut self,
        interruption_class: RuntimeInterruptionClass,
        reason: &str,
    ) {
        let Some(active) = self.active.as_ref() else {
            return;
        };
        let checkpoint_class = if interruption_class == RuntimeInterruptionClass::Terminal {
            RuntimeRecordingCaptureCheckpointClass::Failed
        } else if active.buffered_frame_count > 0 || active.buffered_event_count > 0 {
            RuntimeRecordingCaptureCheckpointClass::Buffered
        } else {
            RuntimeRecordingCaptureCheckpointClass::Armed
        };
        self.last_checkpoint = Some(self.checkpoint_from_active(
            active,
            checkpoint_class,
            interruption_class,
            self.last_error.clone(),
            reason,
        ));
        self.active = None;
    }

    fn reset_for_runtime_reconfigure(&mut self) {
        self.policy = RuntimeRecordingCapturePolicy::default();
        self.active = None;
        self.last_error = None;
    }

    fn start_capture(
        &mut self,
        request: RuntimeRecordingCaptureStartRequest,
        sample_rate_hz: u32,
        configured: bool,
        readiness: &RuntimeReadiness,
    ) -> Result<(), RuntimeError> {
        if !self.capture_ready(configured, readiness) {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime is not ready to begin recording capture",
            ));
        }
        if self.active.is_some() {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "recording capture is already active",
            ));
        }
        self.last_error = None;
        self.active = Some(RuntimeRecordingCaptureActiveSession {
            capture_kind: request.capture_kind,
            take_id: request.take_id,
            track_id: request.track_id,
            start_samples: request.start_samples,
            capture_path: request.capture_path,
            sample_rate_hz,
            channel_count: 0,
            samples: Vec::new(),
            buffered_block_count: 0,
            buffered_frame_count: 0,
            buffered_event_count: 0,
            peak_level: 0.0,
            pressure_event_count: 0,
        });
        Ok(())
    }

    fn record_output_block(&mut self, output: &AudioBuffer) {
        let Some(active) = self.active.as_mut() else {
            return;
        };

        let channel_count = output.channel_count().0;
        let frame_count = output.frames().0 as u64;
        if active.channel_count == 0 {
            active.channel_count = channel_count;
        } else if active.channel_count != channel_count {
            self.last_error = Some(format!(
                "capture channel-count mismatch: expected {} got {}",
                active.channel_count, channel_count
            ));
            self.interrupt_active_capture(
                RuntimeInterruptionClass::Terminal,
                "capture channel-count mismatch",
            );
            return;
        }

        active.samples.extend_from_slice(output.samples());
        active.buffered_block_count = active.buffered_block_count.saturating_add(1);
        active.buffered_frame_count = active.buffered_frame_count.saturating_add(frame_count);
        let block_peak = output
            .samples()
            .iter()
            .fold(0.0_f32, |peak, sample| peak.max(sample.abs()));
        active.peak_level = active.peak_level.max(block_peak);
        if active.buffered_frame_count >= self.policy.pressure_threshold_frames {
            active.pressure_event_count = active.pressure_event_count.saturating_add(1);
        }
    }

    fn finish_capture(&mut self) -> Result<RuntimeRecordingCaptureCommitReceipt, RuntimeError> {
        let active = self.active.as_ref().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "recording capture is not active",
            )
        })?;
        if active.channel_count == 0 || active.samples.is_empty() {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "recording capture has no buffered audio to commit",
            ));
        }

        let committed_active = active.clone();
        let duration_samples = committed_active.buffered_frame_count.min(u32::MAX as u64) as u32;
        let capture_path = committed_active.capture_path.clone();
        let write_result = (|| -> Result<(), RuntimeError> {
            if let Some(parent) = Path::new(&capture_path).parent() {
                fs::create_dir_all(parent).map_err(|error| {
                    RuntimeError::new(
                        RuntimeErrorKind::ResourceUnavailable,
                        format!("failed to create recording capture directory: {error}"),
                    )
                })?;
            }

            let spec = WavSpec {
                channels: committed_active.channel_count as u16,
                sample_rate: committed_active.sample_rate_hz,
                bits_per_sample: 32,
                sample_format: HoundSampleFormat::Float,
            };
            let mut writer = WavWriter::create(&capture_path, spec).map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!("failed to create recording capture wav: {error}"),
                )
            })?;
            for sample in &committed_active.samples {
                writer.write_sample(*sample).map_err(|error| {
                    RuntimeError::new(
                        RuntimeErrorKind::ResourceUnavailable,
                        format!("failed to write recording capture sample: {error}"),
                    )
                })?;
            }
            writer.finalize().map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!("failed to finalize recording capture wav: {error}"),
                )
            })?;
            Ok(())
        })();
        if let Err(error) = write_result {
            self.last_error = Some(error.message.clone());
            self.interrupt_active_capture(
                RuntimeInterruptionClass::Terminal,
                "capture commit failed terminally",
            );
            return Err(error);
        }

        let committed_checkpoint = self.checkpoint_from_active(
            &committed_active,
            RuntimeRecordingCaptureCheckpointClass::Committed,
            RuntimeInterruptionClass::Steady,
            None,
            "capture committed",
        );
        let receipt = RuntimeRecordingCaptureCommitReceipt {
            capture_kind: committed_active.capture_kind,
            take_id: committed_active.take_id.clone(),
            track_id: committed_active.track_id.clone(),
            start_samples: committed_active.start_samples,
            duration_samples,
            channel_count: committed_active.channel_count,
            peak_level: committed_active.peak_level,
            capture_path,
            committed_checkpoint,
        };

        self.last_error = None;
        self.last_committed_take_id = Some(receipt.take_id.clone());
        self.last_committed_path = Some(receipt.capture_path.clone());
        self.last_committed_duration_samples = Some(receipt.duration_samples);
        self.last_checkpoint = Some(receipt.committed_checkpoint.clone());
        self.active = None;
        Ok(receipt)
    }

    fn cancel_capture(&mut self) -> Result<(), RuntimeError> {
        if self.active.is_none() {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "recording capture is not active",
            ));
        }
        self.last_error = None;
        self.interrupt_active_capture(
            RuntimeInterruptionClass::Restartable,
            "capture cancelled before commit",
        );
        Ok(())
    }
}

impl Default for RuntimeRecordingCaptureStateModel {
    fn default() -> Self {
        Self {
            policy: RuntimeRecordingCapturePolicy::default(),
            active: None,
            last_committed_take_id: None,
            last_committed_path: None,
            last_committed_duration_samples: None,
            last_checkpoint: None,
            last_error: None,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeMeteringWindowBlock {
    mean_square: f64,
    sample_count: usize,
}

#[derive(Clone, Debug, PartialEq)]
struct RuntimeMeteringStateModel {
    snapshot: RuntimeMeteringSnapshot,
    momentary_blocks: VecDeque<RuntimeMeteringWindowBlock>,
    short_term_blocks: VecDeque<RuntimeMeteringWindowBlock>,
    momentary_sum: f64,
    short_term_sum: f64,
    momentary_sample_count: usize,
    short_term_sample_count: usize,
    integrated_sum: f64,
    integrated_sample_count: u64,
    clipped_sample_count: u64,
}

impl RuntimeMeteringStateModel {
    fn snapshot(&self) -> RuntimeMeteringSnapshot {
        self.snapshot.clone()
    }

    fn capture(
        &mut self,
        sample_rate_hz: u32,
        output: &AudioBuffer,
        meter_sources: Vec<RuntimeMeterSourceSnapshot>,
    ) {
        let samples = output.samples();
        let sample_count = samples.len();
        let mean_square = if sample_count == 0 {
            0.0
        } else {
            samples
                .iter()
                .copied()
                .map(|sample| {
                    let sample = f64::from(sample);
                    sample * sample
                })
                .sum::<f64>()
                / sample_count as f64
        };
        let clipped_samples = samples
            .iter()
            .filter(|sample| sample.abs() >= 0.999)
            .count() as u64;
        self.clipped_sample_count = self.clipped_sample_count.saturating_add(clipped_samples);
        self.integrated_sum += mean_square * sample_count as f64;
        self.integrated_sample_count = self
            .integrated_sample_count
            .saturating_add(sample_count.min(u64::MAX as usize) as u64);
        Self::push_window_block(
            &mut self.momentary_blocks,
            &mut self.momentary_sum,
            &mut self.momentary_sample_count,
            RuntimeMeteringWindowBlock {
                mean_square,
                sample_count,
            },
            Self::window_sample_target(sample_rate_hz, output.channel_count().0, 0.4),
        );
        Self::push_window_block(
            &mut self.short_term_blocks,
            &mut self.short_term_sum,
            &mut self.short_term_sample_count,
            RuntimeMeteringWindowBlock {
                mean_square,
                sample_count,
            },
            Self::window_sample_target(sample_rate_hz, output.channel_count().0, 3.0),
        );

        let meters = meter_sources;
        let main_output = meters.iter().find(|meter| meter.bus_id == "main:out");

        self.snapshot = RuntimeMeteringSnapshot {
            meter_count: meters.len(),
            main_output_peak_level: main_output.map(|meter| meter.peak_level),
            main_output_rms_level: main_output.map(|meter| meter.rms_level),
            momentary_loudness_lufs: Self::lufs_from_weighted_sum(
                self.momentary_sum,
                self.momentary_sample_count,
            ),
            short_term_loudness_lufs: Self::lufs_from_weighted_sum(
                self.short_term_sum,
                self.short_term_sample_count,
            ),
            integrated_loudness_lufs: Self::lufs_from_weighted_sum_u64(
                self.integrated_sum,
                self.integrated_sample_count,
            ),
            clipped_sample_count: self.clipped_sample_count,
            track_lanes: Vec::new(),
            bus_groups: Vec::new(),
            console_groups: Vec::new(),
            send_returns: Vec::new(),
            bus_connection_count: 0,
            auxiliary_path_count: 0,
            bus_connections: Vec::new(),
            auxiliary_paths: Vec::new(),
            summary: format!(
                "meters={} main_peak={:?} main_rms={:?} momentary_lufs={:?} short_term_lufs={:?} integrated_lufs={:?} clipped={}",
                meters.len(),
                main_output.map(|meter| meter.peak_level),
                main_output.map(|meter| meter.rms_level),
                Self::lufs_from_weighted_sum(self.momentary_sum, self.momentary_sample_count),
                Self::lufs_from_weighted_sum(self.short_term_sum, self.short_term_sample_count),
                Self::lufs_from_weighted_sum_u64(
                    self.integrated_sum,
                    self.integrated_sample_count,
                ),
                self.clipped_sample_count,
            ),
            meters,
        };
    }

    fn push_window_block(
        window: &mut VecDeque<RuntimeMeteringWindowBlock>,
        sum: &mut f64,
        sample_count: &mut usize,
        block: RuntimeMeteringWindowBlock,
        target_samples: usize,
    ) {
        *sum += block.mean_square * block.sample_count as f64;
        *sample_count = sample_count.saturating_add(block.sample_count);
        window.push_back(block);
        while *sample_count > target_samples.max(1) {
            let Some(removed) = window.pop_front() else {
                break;
            };
            *sum -= removed.mean_square * removed.sample_count as f64;
            *sample_count = sample_count.saturating_sub(removed.sample_count);
        }
    }

    fn window_sample_target(sample_rate_hz: u32, channel_count: usize, seconds: f64) -> usize {
        ((sample_rate_hz as f64) * seconds).round() as usize * channel_count.max(1)
    }

    fn lufs_from_weighted_sum(sum: f64, sample_count: usize) -> Option<f32> {
        if sample_count == 0 {
            return None;
        }
        Self::lufs_from_mean_square(sum / sample_count as f64)
    }

    fn lufs_from_weighted_sum_u64(sum: f64, sample_count: u64) -> Option<f32> {
        if sample_count == 0 {
            return None;
        }
        Self::lufs_from_mean_square(sum / sample_count as f64)
    }

    fn lufs_from_mean_square(mean_square: f64) -> Option<f32> {
        if mean_square <= f64::EPSILON {
            None
        } else {
            Some((10.0 * mean_square.log10()) as f32)
        }
    }

    fn meter_contract_metadata(
        contract: &signal_graph::GraphContractSummary,
        bus_id: &str,
    ) -> (
        RuntimeMeterSourceRole,
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        Vec<String>,
    ) {
        let matching = contract
            .node_contracts
            .iter()
            .filter(|node| node.output_bus_id == bus_id)
            .collect::<Vec<_>>();
        if matching.is_empty() {
            return (
                RuntimeMeterSourceRole::Utility,
                None,
                None,
                None,
                None,
                Vec::new(),
            );
        }

        let producer_node_ids = matching
            .iter()
            .map(|node| node.node_id.clone())
            .collect::<Vec<_>>();
        let topology_role = {
            let first = matching[0].topology_role;
            if matching.iter().all(|node| node.topology_role == first) {
                runtime_meter_source_role(first)
            } else {
                RuntimeMeterSourceRole::Utility
            }
        };
        let track_lane_id = unique_string(
            matching
                .iter()
                .filter_map(|node| node.track_lane_id.as_ref()),
        );
        let bus_group_id = unique_string(
            matching
                .iter()
                .filter_map(|node| node.bus_group_id.as_ref()),
        );
        let console_group_id = unique_string(
            matching
                .iter()
                .filter_map(|node| node.console_group_id.as_ref()),
        );
        let send_return_id = unique_string(
            matching
                .iter()
                .filter_map(|node| node.send_return_id.as_ref()),
        );
        (
            topology_role,
            track_lane_id,
            bus_group_id,
            console_group_id,
            send_return_id,
            producer_node_ids,
        )
    }
}

impl Default for RuntimeMeteringStateModel {
    fn default() -> Self {
        Self {
            snapshot: RuntimeMeteringSnapshot {
                meter_count: 0,
                main_output_peak_level: None,
                main_output_rms_level: None,
                momentary_loudness_lufs: None,
                short_term_loudness_lufs: None,
                integrated_loudness_lufs: None,
                clipped_sample_count: 0,
                meters: Vec::new(),
                track_lanes: Vec::new(),
                bus_groups: Vec::new(),
                console_groups: Vec::new(),
                send_returns: Vec::new(),
                bus_connection_count: 0,
                auxiliary_path_count: 0,
                bus_connections: Vec::new(),
                auxiliary_paths: Vec::new(),
                summary: "runtime metering unavailable".to_string(),
            },
            momentary_blocks: VecDeque::new(),
            short_term_blocks: VecDeque::new(),
            momentary_sum: 0.0,
            short_term_sum: 0.0,
            momentary_sample_count: 0,
            short_term_sample_count: 0,
            integrated_sum: 0.0,
            integrated_sample_count: 0,
            clipped_sample_count: 0,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RuntimeTransportConcurrencyPolicy {
    steady_session_limit: usize,
    recovery_session_limit: usize,
}

impl Default for RuntimeTransportConcurrencyPolicy {
    fn default() -> Self {
        Self {
            steady_session_limit: 1,
            recovery_session_limit: 2,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeTransportConcurrencySession {
    sandbox_id: String,
    lease_id: String,
    region_id: String,
    intent: TransportAttachIntent,
    provenance: TransportSessionProvenance,
    attach_sequence: u64,
    attach_processing_epoch: Option<u64>,
    state: TransportSessionState,
    backing_path: Option<String>,
    total_bytes: Option<u32>,
    cleanup_attempt_count: u32,
    last_cleanup_mode: Option<LingeringCleanupMode>,
    last_cleanup_wave: Option<u64>,
    cleanup_in_progress: bool,
    last_cleanup_epoch: Option<u64>,
    last_cleanup_error: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeTransportConcurrencyState {
    policy: RuntimeTransportConcurrencyPolicy,
    active_sessions: BTreeMap<(String, String, String), RuntimeTransportConcurrencySession>,
    pending_cleanup_work: VecDeque<RuntimeLingeringCleanupWorkItem>,
    peak_attached_sessions: usize,
    peak_recovery_overlap_sessions: usize,
    peak_lingering_sessions: usize,
    next_attach_sequence: u64,
    next_cleanup_work_id: u64,
    next_cleanup_epoch: u64,
    next_cleanup_wave_by_sandbox: BTreeMap<String, u64>,
    last_admitted_sandbox_id: Option<String>,
    last_rejected_sandbox_id: Option<String>,
    last_rejection_reason: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeLingeringCleanupWorkItem {
    work_id: u64,
    cleanup_epoch: u64,
    cleanup_wave: u64,
    sandbox_id: String,
    mode: LingeringCleanupMode,
    trigger: LingeringCleanupTrigger,
    retry_count: u32,
    processing_epoch: u64,
    ready_at_processing_epoch: u64,
    exclude_lease_id: Option<String>,
    exclude_region_id: Option<String>,
}

impl RuntimeTransportConcurrencyState {
    fn set_policy(
        &mut self,
        steady_session_limit: usize,
        recovery_session_limit: usize,
    ) -> Result<RuntimeTransportConcurrencySnapshot, RuntimeError> {
        if steady_session_limit == 0 {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "steady-state transport session limit must be greater than zero",
            ));
        }
        if recovery_session_limit <= steady_session_limit {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "recovery transport session limit must exceed steady-state limit",
            ));
        }
        if self.steady_session_count() > steady_session_limit {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "active steady-state transport sessions exceed the requested limit",
            ));
        }
        if self.active_sessions.len() > recovery_session_limit {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "active transport sessions exceed the requested recovery limit",
            ));
        }
        self.policy = RuntimeTransportConcurrencyPolicy {
            steady_session_limit,
            recovery_session_limit,
        };
        Ok(self.snapshot())
    }

    fn pending_work_item_count(&self) -> usize {
        self.pending_cleanup_work.len()
    }

    fn active_session_view(
        session: &RuntimeTransportConcurrencySession,
    ) -> crate::interfaces::ActiveTransportConcurrencySession {
        crate::interfaces::ActiveTransportConcurrencySession {
            sandbox_id: session.sandbox_id.clone(),
            lease_id: session.lease_id.clone(),
            region_id: session.region_id.clone(),
            intent: session.intent,
            provenance: session.provenance,
            attach_sequence: session.attach_sequence,
            attach_processing_epoch: session.attach_processing_epoch,
            state: session.state,
            backing_path: session.backing_path.clone(),
            total_bytes: session.total_bytes,
            cleanup_attempt_count: session.cleanup_attempt_count,
            last_cleanup_mode: session.last_cleanup_mode,
            last_cleanup_wave: session.last_cleanup_wave,
            cleanup_in_progress: session.cleanup_in_progress,
            last_cleanup_epoch: session.last_cleanup_epoch,
            last_cleanup_error: session.last_cleanup_error.clone(),
        }
    }

    fn next_cleanup_wave_for_sandbox(&mut self, sandbox_id: &str) -> u64 {
        let next = self
            .next_cleanup_wave_by_sandbox
            .entry(sandbox_id.to_string())
            .or_insert(1);
        let cleanup_wave = *next;
        *next = next.saturating_add(1);
        cleanup_wave
    }

    fn has_lingering_candidates(
        &self,
        sandbox_id: &str,
        exclude_lease_id: Option<&str>,
        exclude_region_id: Option<&str>,
    ) -> bool {
        self.active_sessions.values().any(|session| {
            session.sandbox_id == sandbox_id
                && matches!(
                    session.state,
                    TransportSessionState::DetachRequested | TransportSessionState::DetachFaulted
                )
                && !matches!(
                    (exclude_lease_id, exclude_region_id),
                    (Some(exclude_lease_id), Some(exclude_region_id))
                        if session.lease_id == exclude_lease_id
                            && session.region_id == exclude_region_id
                )
        })
    }

    fn enqueue_cleanup_work(
        &mut self,
        sandbox_id: &str,
        mode: LingeringCleanupMode,
        trigger: LingeringCleanupTrigger,
        retry_count: u32,
        processing_epoch: u64,
        cleanup_wave: Option<u64>,
        exclude_lease_id: Option<&str>,
        exclude_region_id: Option<&str>,
    ) -> Option<LingeringCleanupQueueReceipt> {
        if !self.has_lingering_candidates(sandbox_id, exclude_lease_id, exclude_region_id) {
            return None;
        }

        let work_id = self.next_cleanup_work_id;
        self.next_cleanup_work_id = self.next_cleanup_work_id.saturating_add(1);
        let cleanup_epoch = self.next_cleanup_epoch;
        self.next_cleanup_epoch = self.next_cleanup_epoch.saturating_add(1);
        let cleanup_wave =
            cleanup_wave.unwrap_or_else(|| self.next_cleanup_wave_for_sandbox(sandbox_id));
        let backoff = match trigger {
            LingeringCleanupTrigger::DeferredRetry => retry_count.max(1) as u64,
            LingeringCleanupTrigger::RecoveryPreAttach
            | LingeringCleanupTrigger::PostStartReconciliation => 0,
        };
        self.pending_cleanup_work
            .push_back(RuntimeLingeringCleanupWorkItem {
                work_id,
                cleanup_epoch,
                cleanup_wave,
                sandbox_id: sandbox_id.to_string(),
                mode,
                trigger,
                retry_count,
                processing_epoch,
                ready_at_processing_epoch: processing_epoch.saturating_add(backoff),
                exclude_lease_id: exclude_lease_id.map(ToOwned::to_owned),
                exclude_region_id: exclude_region_id.map(ToOwned::to_owned),
            });
        Some(LingeringCleanupQueueReceipt {
            work_id,
            cleanup_epoch,
            cleanup_wave,
        })
    }

    fn cleanup_attempt_count(&self, sandbox_id: &str, lease_id: &str, region_id: &str) -> u32 {
        self.active_sessions
            .get(&(
                sandbox_id.to_string(),
                lease_id.to_string(),
                region_id.to_string(),
            ))
            .map(|session| session.cleanup_attempt_count)
            .unwrap_or(0)
    }

    fn cleanup_wave_for_session(
        &self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
    ) -> Option<u64> {
        self.active_sessions
            .get(&(
                sandbox_id.to_string(),
                lease_id.to_string(),
                region_id.to_string(),
            ))
            .and_then(|session| session.last_cleanup_wave)
    }

    fn pending_deferred_retry_work_count(&self) -> usize {
        self.pending_cleanup_work
            .iter()
            .filter(|item| item.trigger == LingeringCleanupTrigger::DeferredRetry)
            .count()
    }

    fn oldest_pending_cleanup_ready_epoch(&self) -> Option<u64> {
        self.pending_cleanup_work
            .iter()
            .map(|item| item.ready_at_processing_epoch)
            .min()
    }

    fn pending_cleanup_waves(&self) -> Vec<crate::interfaces::PendingLingeringCleanupWaveSummary> {
        let mut by_wave: BTreeMap<
            (String, u64),
            crate::interfaces::PendingLingeringCleanupWaveSummary,
        > = BTreeMap::new();
        for item in &self.pending_cleanup_work {
            let key = (item.sandbox_id.clone(), item.cleanup_wave);
            let entry = by_wave.entry(key).or_insert_with(|| {
                crate::interfaces::PendingLingeringCleanupWaveSummary {
                    sandbox_id: item.sandbox_id.clone(),
                    cleanup_wave: item.cleanup_wave,
                    mode: item.mode,
                    first_trigger: item.trigger,
                    latest_trigger: item.trigger,
                    pending_work_items: 0,
                    deferred_retry_work_items: 0,
                    first_cleanup_epoch: item.cleanup_epoch,
                    latest_cleanup_epoch: item.cleanup_epoch,
                    first_processing_epoch: item.processing_epoch,
                    latest_processing_epoch: item.processing_epoch,
                    oldest_ready_at_processing_epoch: item.ready_at_processing_epoch,
                    newest_ready_at_processing_epoch: item.ready_at_processing_epoch,
                }
            });
            entry.latest_trigger = item.trigger;
            entry.pending_work_items = entry.pending_work_items.saturating_add(1);
            if item.trigger == LingeringCleanupTrigger::DeferredRetry {
                entry.deferred_retry_work_items = entry.deferred_retry_work_items.saturating_add(1);
            }
            entry.first_cleanup_epoch = entry.first_cleanup_epoch.min(item.cleanup_epoch);
            entry.latest_cleanup_epoch = entry.latest_cleanup_epoch.max(item.cleanup_epoch);
            entry.first_processing_epoch = entry.first_processing_epoch.min(item.processing_epoch);
            entry.latest_processing_epoch =
                entry.latest_processing_epoch.max(item.processing_epoch);
            entry.oldest_ready_at_processing_epoch = entry
                .oldest_ready_at_processing_epoch
                .min(item.ready_at_processing_epoch);
            entry.newest_ready_at_processing_epoch = entry
                .newest_ready_at_processing_epoch
                .max(item.ready_at_processing_epoch);
        }
        by_wave.into_values().collect()
    }

    fn dequeue_cleanup_work_for_sandbox(
        &mut self,
        sandbox_id: &str,
        current_processing_epoch: u64,
    ) -> Option<crate::interfaces::LingeringCleanupPlan> {
        let position = self.pending_cleanup_work.iter().position(|item| {
            item.sandbox_id == sandbox_id
                && item.ready_at_processing_epoch <= current_processing_epoch
        })?;
        let work = self.pending_cleanup_work.remove(position)?;
        let candidates = self.lingering_cleanup_candidates(
            work.sandbox_id.as_str(),
            work.exclude_lease_id.as_deref(),
            work.exclude_region_id.as_deref(),
            work.mode,
            work.processing_epoch,
            work.cleanup_wave,
        );
        if candidates.is_empty() {
            return None;
        }
        Some(crate::interfaces::LingeringCleanupPlan {
            work_id: work.work_id,
            cleanup_epoch: work.cleanup_epoch,
            cleanup_wave: work.cleanup_wave,
            sandbox_id: work.sandbox_id,
            mode: work.mode,
            trigger: work.trigger,
            retry_count: work.retry_count,
            processing_epoch: work.processing_epoch,
            ready_at_processing_epoch: work.ready_at_processing_epoch,
            exclude_lease_id: work.exclude_lease_id,
            exclude_region_id: work.exclude_region_id,
            candidates,
        })
    }

    fn lingering_cleanup_candidates(
        &mut self,
        sandbox_id: &str,
        exclude_lease_id: Option<&str>,
        exclude_region_id: Option<&str>,
        mode: LingeringCleanupMode,
        processing_epoch: u64,
        cleanup_wave: u64,
    ) -> Vec<crate::interfaces::ActiveTransportConcurrencySession> {
        let mut session_keys: Vec<_> = self
            .active_sessions
            .iter()
            .filter(|(_, session)| {
                session.sandbox_id == sandbox_id
                    && matches!(
                        session.state,
                        TransportSessionState::DetachRequested
                            | TransportSessionState::DetachFaulted
                    )
                    && !matches!(
                        (exclude_lease_id, exclude_region_id),
                        (Some(exclude_lease_id), Some(exclude_region_id))
                            if session.lease_id == exclude_lease_id
                                && session.region_id == exclude_region_id
                    )
            })
            .map(|(key, _)| key.clone())
            .collect();

        session_keys.sort_by(|left, right| {
            let left = self
                .active_sessions
                .get(left)
                .expect("missing left session");
            let right = self
                .active_sessions
                .get(right)
                .expect("missing right session");
            let left_key = (
                match left.provenance {
                    TransportSessionProvenance::SteadyOrigin => 0_u8,
                    TransportSessionProvenance::RecoveryReplacement => 1_u8,
                },
                left.attach_sequence,
                match left.state {
                    TransportSessionState::DetachRequested => 0_u8,
                    TransportSessionState::DetachFaulted => 1_u8,
                    _ => 2_u8,
                },
                left.lease_id.as_str(),
                left.region_id.as_str(),
            );
            let right_key = (
                match right.provenance {
                    TransportSessionProvenance::SteadyOrigin => 0_u8,
                    TransportSessionProvenance::RecoveryReplacement => 1_u8,
                },
                right.attach_sequence,
                match right.state {
                    TransportSessionState::DetachRequested => 0_u8,
                    TransportSessionState::DetachFaulted => 1_u8,
                    _ => 2_u8,
                },
                right.lease_id.as_str(),
                right.region_id.as_str(),
            );
            left_key.cmp(&right_key)
        });

        let mut sessions = Vec::with_capacity(session_keys.len());
        for key in session_keys {
            if let Some(session) = self.active_sessions.get_mut(&key) {
                session.cleanup_attempt_count = session.cleanup_attempt_count.saturating_add(1);
                session.last_cleanup_mode = Some(mode);
                session.last_cleanup_wave = Some(cleanup_wave);
                session.cleanup_in_progress = true;
                session.last_cleanup_epoch = Some(processing_epoch);
                session.last_cleanup_error = None;
                sessions.push(Self::active_session_view(session));
            }
        }

        sessions
    }

    fn steady_session_count(&self) -> usize {
        self.active_sessions
            .values()
            .filter(|session| session.intent == TransportAttachIntent::SteadyState)
            .count()
    }

    fn recovery_overlap_session_count(&self) -> usize {
        self.active_sessions
            .values()
            .filter(|session| session.intent == TransportAttachIntent::RecoveryOverlap)
            .count()
    }

    fn lingering_session_count(&self) -> usize {
        self.active_sessions
            .values()
            .filter(|session| {
                matches!(
                    session.state,
                    TransportSessionState::DetachRequested | TransportSessionState::DetachFaulted
                )
            })
            .count()
    }

    fn detach_requested_session_count(&self) -> usize {
        self.active_sessions
            .values()
            .filter(|session| session.state == TransportSessionState::DetachRequested)
            .count()
    }

    fn detach_faulted_session_count(&self) -> usize {
        self.active_sessions
            .values()
            .filter(|session| session.state == TransportSessionState::DetachFaulted)
            .count()
    }

    fn recovery_overlap_limit(&self) -> usize {
        self.policy
            .recovery_session_limit
            .saturating_sub(self.policy.steady_session_limit)
            .max(1)
    }

    fn lingering_reason_suffix(&self, intent: TransportAttachIntent) -> String {
        let lingering = self
            .active_sessions
            .values()
            .filter(|session| {
                session.intent == intent
                    && matches!(
                        session.state,
                        TransportSessionState::DetachRequested
                            | TransportSessionState::DetachFaulted
                    )
            })
            .count();
        if lingering == 0 {
            String::new()
        } else {
            format!(" ({lingering} lingering session(s) pending detach)")
        }
    }

    fn snapshot(&self) -> RuntimeTransportConcurrencySnapshot {
        RuntimeTransportConcurrencySnapshot {
            steady_session_limit: self.policy.steady_session_limit,
            recovery_session_limit: self.policy.recovery_session_limit,
            current_attached_sessions: self.active_sessions.len(),
            peak_attached_sessions: self.peak_attached_sessions,
            current_recovery_overlap_sessions: self.recovery_overlap_session_count(),
            peak_recovery_overlap_sessions: self.peak_recovery_overlap_sessions,
            current_lingering_sessions: self.lingering_session_count(),
            peak_lingering_sessions: self.peak_lingering_sessions,
            current_detach_requested_sessions: self.detach_requested_session_count(),
            current_detach_faulted_sessions: self.detach_faulted_session_count(),
            pending_cleanup_work_items: self.pending_cleanup_work.len(),
            pending_deferred_retry_work_items: self.pending_deferred_retry_work_count(),
            next_cleanup_epoch: self.next_cleanup_epoch,
            oldest_pending_cleanup_ready_epoch: self.oldest_pending_cleanup_ready_epoch(),
            pending_cleanup_waves: self.pending_cleanup_waves(),
            active_sessions: self
                .active_sessions
                .values()
                .map(Self::active_session_view)
                .collect(),
            last_admitted_sandbox_id: self.last_admitted_sandbox_id.clone(),
            last_rejected_sandbox_id: self.last_rejected_sandbox_id.clone(),
            last_rejection_reason: self.last_rejection_reason.clone(),
        }
    }

    fn begin_session(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
        intent: TransportAttachIntent,
        provenance: TransportSessionProvenance,
        attach_processing_epoch: Option<u64>,
        backing_path: Option<String>,
        total_bytes: Option<u32>,
    ) -> Result<RuntimeTransportConcurrencySnapshot, RuntimeError> {
        let key = (
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        );
        if self.active_sessions.contains_key(&key) {
            self.last_rejected_sandbox_id = Some(sandbox_id.to_string());
            self.last_rejection_reason = Some("transport session is already attached".to_string());
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "transport session is already attached",
            ));
        }

        let steady_sessions = self.steady_session_count();
        let recovery_sessions = self.recovery_overlap_session_count();

        if matches!(intent, TransportAttachIntent::SteadyState)
            && steady_sessions >= self.policy.steady_session_limit
        {
            let reason = format!(
                "steady-state transport session limit {} is already attached{}",
                self.policy.steady_session_limit,
                self.lingering_reason_suffix(TransportAttachIntent::SteadyState)
            );
            self.last_rejected_sandbox_id = Some(sandbox_id.to_string());
            self.last_rejection_reason = Some(reason.clone());
            return Err(RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                reason,
            ));
        }

        if matches!(intent, TransportAttachIntent::RecoveryOverlap)
            && recovery_sessions >= self.recovery_overlap_limit()
        {
            let reason = format!(
                "recovery overlap session limit {} is already attached{}",
                self.recovery_overlap_limit(),
                self.lingering_reason_suffix(TransportAttachIntent::RecoveryOverlap)
            );
            self.last_rejected_sandbox_id = Some(sandbox_id.to_string());
            self.last_rejection_reason = Some(reason.clone());
            return Err(RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                reason,
            ));
        }

        let limit = match intent {
            TransportAttachIntent::SteadyState => self.policy.steady_session_limit,
            TransportAttachIntent::RecoveryOverlap => self.policy.recovery_session_limit,
        };
        if self.active_sessions.len() >= limit {
            let reason = format!(
                "transport session admission exceeds {:?} limit {}",
                intent, limit
            );
            self.last_rejected_sandbox_id = Some(sandbox_id.to_string());
            self.last_rejection_reason = Some(reason.clone());
            return Err(RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                reason,
            ));
        }

        self.active_sessions.insert(
            key,
            RuntimeTransportConcurrencySession {
                sandbox_id: sandbox_id.to_string(),
                lease_id: lease_id.to_string(),
                region_id: region_id.to_string(),
                intent,
                provenance,
                attach_sequence: self.next_attach_sequence,
                attach_processing_epoch,
                state: TransportSessionState::AttachActive,
                backing_path,
                total_bytes,
                cleanup_attempt_count: 0,
                last_cleanup_mode: None,
                last_cleanup_wave: None,
                cleanup_in_progress: false,
                last_cleanup_epoch: None,
                last_cleanup_error: None,
            },
        );
        self.next_attach_sequence = self.next_attach_sequence.saturating_add(1);
        self.peak_attached_sessions = self.peak_attached_sessions.max(self.active_sessions.len());
        let recovery_sessions = self.recovery_overlap_session_count();
        self.peak_recovery_overlap_sessions =
            self.peak_recovery_overlap_sessions.max(recovery_sessions);
        let lingering_sessions = self.lingering_session_count();
        self.peak_lingering_sessions = self.peak_lingering_sessions.max(lingering_sessions);
        self.last_admitted_sandbox_id = Some(sandbox_id.to_string());
        self.last_rejected_sandbox_id = None;
        self.last_rejection_reason = None;
        Ok(self.snapshot())
    }

    fn mark_session_state(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
        state: TransportSessionState,
    ) -> RuntimeTransportConcurrencySnapshot {
        if let Some(session) = self.active_sessions.get_mut(&(
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        )) {
            session.state = state;
        }
        let lingering_sessions = self.lingering_session_count();
        self.peak_lingering_sessions = self.peak_lingering_sessions.max(lingering_sessions);
        self.snapshot()
    }

    fn promote_session_to_steady_state(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
    ) -> RuntimeTransportConcurrencySnapshot {
        if let Some(session) = self.active_sessions.get_mut(&(
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        )) {
            session.intent = TransportAttachIntent::SteadyState;
        }
        self.snapshot()
    }

    fn record_cleanup_failure(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
        mode: LingeringCleanupMode,
        processing_epoch: u64,
        error: &str,
    ) -> RuntimeTransportConcurrencySnapshot {
        if let Some(session) = self.active_sessions.get_mut(&(
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        )) {
            session.last_cleanup_mode = Some(mode);
            session.cleanup_in_progress = false;
            session.last_cleanup_epoch = Some(processing_epoch);
            session.last_cleanup_error = Some(error.to_string());
        }
        self.snapshot()
    }

    fn clear_cleanup_in_progress(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
    ) -> RuntimeTransportConcurrencySnapshot {
        if let Some(session) = self.active_sessions.get_mut(&(
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        )) {
            session.cleanup_in_progress = false;
            session.last_cleanup_error = None;
        }
        self.snapshot()
    }

    fn end_session(
        &mut self,
        sandbox_id: &str,
        lease_id: &str,
        region_id: &str,
    ) -> RuntimeTransportConcurrencySnapshot {
        self.active_sessions.remove(&(
            sandbox_id.to_string(),
            lease_id.to_string(),
            region_id.to_string(),
        ));
        self.snapshot()
    }

    fn reset(&mut self) {
        *self = Self::default();
    }
}

impl Default for RuntimeTransportConcurrencyState {
    fn default() -> Self {
        Self {
            policy: RuntimeTransportConcurrencyPolicy::default(),
            active_sessions: BTreeMap::new(),
            pending_cleanup_work: VecDeque::new(),
            peak_attached_sessions: 0,
            peak_recovery_overlap_sessions: 0,
            peak_lingering_sessions: 0,
            next_attach_sequence: 1,
            next_cleanup_work_id: 1,
            next_cleanup_epoch: 1,
            next_cleanup_wave_by_sandbox: BTreeMap::new(),
            last_admitted_sandbox_id: None,
            last_rejected_sandbox_id: None,
            last_rejection_reason: None,
        }
    }
}

fn transport_session_provenance(intent: TransportAttachIntent) -> TransportSessionProvenance {
    match intent {
        TransportAttachIntent::SteadyState => TransportSessionProvenance::SteadyOrigin,
        TransportAttachIntent::RecoveryOverlap => TransportSessionProvenance::RecoveryReplacement,
    }
}

fn hash_audio_buffer(buffer: &AudioBuffer) -> u64 {
    let mut hash = 1469598103934665603_u64;
    for sample in buffer.samples() {
        hash ^= u64::from(sample.to_bits());
        hash = hash.wrapping_mul(1099511628211);
    }
    hash ^= buffer.frames().0 as u64;
    hash = hash.wrapping_mul(1099511628211);
    hash ^= buffer.channel_count().0 as u64;
    hash
}

fn peak_abs(samples: &[f32]) -> f32 {
    samples
        .iter()
        .fold(0.0_f32, |peak, sample| peak.max(sample.abs()))
}

fn rms(samples: &[f32]) -> f32 {
    if samples.is_empty() {
        return 0.0;
    }
    let mean_square = samples
        .iter()
        .map(|sample| f64::from(*sample) * f64::from(*sample))
        .sum::<f64>()
        / samples.len() as f64;
    mean_square.sqrt() as f32
}

fn analyze_runtime_media_asset(
    cache_path: &Path,
    registration: &RuntimeMediaAssetRegistration,
) -> Result<RuntimeMediaAnalysisStateModel, String> {
    let decoded = if cache_path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("wav"))
    {
        decode_runtime_wav_asset(cache_path, &registration.asset_id)
            .map_err(|error| error.message)?
    } else {
        decode_runtime_media_asset_with_symphonia(cache_path, &registration.asset_id)
            .map_err(|error| error.message)?
    };
    let mut loudness_meter = LoudnessMeter::new(LoudnessMeterConfig::default());
    let mut character_analyzer = CharacterAnalyzer::new(CharacterAnalyzerConfig::default());
    let loudness = loudness_descriptor_from_result(loudness_meter.analyze(&decoded));
    let character = character_descriptor_from_result(character_analyzer.analyze(&decoded));
    Ok(RuntimeMediaAnalysisStateModel {
        descriptor_state: RuntimeMediaAnalysisDescriptorState::Ready,
        loudness: Some(loudness),
        character: Some(character),
        last_error: None,
    })
}

fn loudness_descriptor_from_result(
    result: signal_analysis_loudness::LoudnessAnalysisResult,
) -> RuntimeMediaLoudnessDescriptor {
    RuntimeMediaLoudnessDescriptor {
        integrated_lufs: result.integrated_lufs,
        loudness_range_lu: result.loudness_range_lu,
        true_peak_dbtp: result.true_peak_dbtp,
        target_offset_lu: result.dynamics.target_offset_lu,
        peak_to_loudness_lu: result.dynamics.peak_to_loudness_lu,
        confidence: result.confidence.0,
        summary: format!(
            "integrated_lufs={:.3} true_peak_dbtp={:.3} loudness_range_lu={:.3} target_offset_lu={:.3} peak_to_loudness_lu={:.3} confidence={:.3}",
            result.integrated_lufs,
            result.true_peak_dbtp,
            result.loudness_range_lu,
            result.dynamics.target_offset_lu,
            result.dynamics.peak_to_loudness_lu,
            result.confidence.0,
        ),
    }
}

fn character_descriptor_from_result(
    result: signal_analysis_character::CharacterAnalysisResult,
) -> RuntimeMediaCharacterDescriptor {
    RuntimeMediaCharacterDescriptor {
        centroid_hz: result.spectral_shape.centroid_hz,
        rolloff_95_hz: result.spectral_shape.rolloff_95_hz,
        flatness: result.spectral_shape.flatness,
        contrast_db: result.spectral_contrast.contrast_db,
        onset_density: result.temporal.onset_density,
        transient_density: result.temporal.transient_density,
        sustain_ratio: result.temporal.sustain_ratio,
        rms_energy: result.dynamics.rms_energy,
        dynamic_range: result.dynamics.dynamic_range,
        confidence: result.confidence.0,
        summary: format!(
            "centroid_hz={:.3} rolloff_95_hz={:.3} flatness={:.3} contrast_db={:.3} onset_density={:.3} transient_density={:.3} sustain_ratio={:.3} rms_energy={:.3} dynamic_range={:.3} confidence={:.3}",
            result.spectral_shape.centroid_hz,
            result.spectral_shape.rolloff_95_hz,
            result.spectral_shape.flatness,
            result.spectral_contrast.contrast_db,
            result.temporal.onset_density,
            result.temporal.transient_density,
            result.temporal.sustain_ratio,
            result.dynamics.rms_energy,
            result.dynamics.dynamic_range,
            result.confidence.0,
        ),
    }
}

fn adapt_audio_buffer_layout(input: &AudioBuffer, target_layout: ChannelLayout) -> AudioBuffer {
    if input.channels() == target_layout {
        return input.clone();
    }

    match (input.channels(), target_layout) {
        (ChannelLayout::Mono, ChannelLayout::Stereo) => {
            let mut samples = Vec::with_capacity(input.samples().len().saturating_mul(2));
            for sample in input.samples() {
                samples.push(*sample);
                samples.push(*sample);
            }
            AudioBuffer::from_interleaved(input.sample_rate(), target_layout, samples)
        }
        (ChannelLayout::Stereo, ChannelLayout::Mono) => {
            AudioBuffer::from_interleaved(input.sample_rate(), target_layout, input.to_mono())
        }
        _ => AudioBuffer::new(input.sample_rate(), target_layout, input.frames()),
    }
}

fn mix_audio_buffer(target: &mut AudioBuffer, source: &AudioBuffer) {
    let adapted = if target.channels() == source.channels() {
        source.clone()
    } else {
        adapt_audio_buffer_layout(source, target.channels())
    };
    for (dst, src) in target.samples_mut().iter_mut().zip(adapted.samples()) {
        *dst += *src;
    }
}

fn write_offline_render_block(
    target: &mut Option<AudioBuffer>,
    total_frames: usize,
    frame_offset: usize,
    block: &AudioBuffer,
) {
    let buffer = target.get_or_insert_with(|| {
        AudioBuffer::new(
            block.sample_rate(),
            block.channels(),
            FrameCount(total_frames),
        )
    });
    let channel_count = buffer.channel_count().0;
    let start = frame_offset.saturating_mul(channel_count);
    let end = start
        .saturating_add(block.samples().len())
        .min(buffer.samples().len());
    buffer.samples_mut()[start..end].copy_from_slice(&block.samples()[..end - start]);
}

fn resample_audio_buffer_linear(
    input: &AudioBuffer,
    target_sample_rate: SampleRate,
) -> AudioBuffer {
    if input.sample_rate() == target_sample_rate {
        return input.clone();
    }
    if input.frames().0 == 0 || input.sample_rate().0 == 0 || target_sample_rate.0 == 0 {
        return AudioBuffer::new(target_sample_rate, input.channels(), FrameCount(0));
    }
    let output_frames = ((input.frames().0 as u64)
        .saturating_mul(target_sample_rate.0 as u64)
        .saturating_add(input.sample_rate().0 as u64 / 2)
        / input.sample_rate().0 as u64) as usize;
    let mut output = AudioBuffer::new(
        target_sample_rate,
        input.channels(),
        FrameCount(output_frames),
    );
    let channel_count = output.channel_count().0;
    let source_frame_ratio = input.sample_rate().0 as f64 / target_sample_rate.0 as f64;
    for frame_index in 0..output_frames {
        let source_frame = frame_index as f64 * source_frame_ratio;
        for channel_index in 0..channel_count {
            output.samples_mut()[frame_index * channel_count + channel_index] =
                sample_audio_buffer_linear(input, source_frame, channel_index, input.frames().0);
        }
    }
    output
}

fn sample_audio_buffer_linear(
    buffer: &AudioBuffer,
    source_frame: f64,
    channel_index: usize,
    frame_count: usize,
) -> f32 {
    if frame_count == 0 || channel_index >= buffer.channel_count().0 || source_frame.is_nan() {
        return 0.0;
    }
    let max_frame = frame_count.saturating_sub(1);
    let base_frame = source_frame.floor().max(0.0) as usize;
    if base_frame > max_frame {
        return 0.0;
    }
    let next_frame = (base_frame + 1).min(max_frame);
    let frac = (source_frame - base_frame as f64).clamp(0.0, 1.0) as f32;
    let channel_count = buffer.channel_count().0;
    let base_index = base_frame * channel_count + channel_index;
    let next_index = next_frame * channel_count + channel_index;
    let base = buffer.samples().get(base_index).copied().unwrap_or(0.0);
    let next = buffer.samples().get(next_index).copied().unwrap_or(base);
    base + ((next - base) * frac)
}

fn decode_runtime_media_asset(
    media_pipeline: &RuntimeMediaPipelineStateModel,
    asset_id: &str,
    decoded_assets: &mut BTreeMap<String, AudioBuffer>,
) -> Result<AudioBuffer, RuntimeError> {
    if let Some(buffer) = decoded_assets.get(asset_id) {
        return Ok(buffer.clone());
    }
    let asset = media_pipeline.assets.get(asset_id).ok_or_else(|| {
        RuntimeError::new(
            RuntimeErrorKind::InvalidState,
            format!("offline render references unknown media asset `{asset_id}`"),
        )
    })?;
    if asset.state != RuntimeMediaAssetState::Ready {
        return Err(RuntimeError::new(
            RuntimeErrorKind::InvalidState,
            format!(
                "offline render media asset `{asset_id}` is not ready: {:?}",
                asset.state
            ),
        ));
    }
    let cache_path = asset.cache_path.as_deref().ok_or_else(|| {
        RuntimeError::new(
            RuntimeErrorKind::InvalidState,
            format!("offline render media asset `{asset_id}` has no cache path"),
        )
    })?;
    let path = Path::new(cache_path);
    let buffer = if path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("wav"))
    {
        decode_runtime_wav_asset(path, asset_id)?
    } else {
        decode_runtime_media_asset_with_symphonia(path, asset_id)?
    };
    decoded_assets.insert(asset_id.to_string(), buffer.clone());
    Ok(buffer)
}

fn decode_runtime_wav_asset(path: &Path, asset_id: &str) -> Result<AudioBuffer, RuntimeError> {
    let mut reader = hound::WavReader::open(path).map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to open cached wav media asset `{asset_id}` at {}: {error}",
                path.display()
            ),
        )
    })?;
    let spec = reader.spec();
    let samples = match spec.sample_format {
        HoundSampleFormat::Float => reader
            .samples::<f32>()
            .map(|sample| {
                sample.map_err(|error| {
                    RuntimeError::new(
                        RuntimeErrorKind::ResourceUnavailable,
                        format!("failed to decode float sample from `{asset_id}`: {error}"),
                    )
                })
            })
            .collect::<Result<Vec<_>, _>>()?,
        HoundSampleFormat::Int => {
            let scale = if spec.bits_per_sample == 0 {
                1.0
            } else {
                let magnitude = 1_i64
                    .checked_shl(spec.bits_per_sample.saturating_sub(1) as u32)
                    .unwrap_or(1) as f32;
                if magnitude == 0.0 {
                    1.0
                } else {
                    magnitude
                }
            };
            reader
                .samples::<i32>()
                .map(|sample| {
                    sample.map(|value| value as f32 / scale).map_err(|error| {
                        RuntimeError::new(
                            RuntimeErrorKind::ResourceUnavailable,
                            format!("failed to decode integer sample from `{asset_id}`: {error}"),
                        )
                    })
                })
                .collect::<Result<Vec<_>, _>>()?
        }
    };
    let channels = match spec.channels {
        1 => ChannelLayout::Mono,
        2 => ChannelLayout::Stereo,
        count => ChannelLayout::Count(signal_primitives::ChannelCount(count as usize)),
    };
    Ok(AudioBuffer::from_interleaved(
        SampleRate(spec.sample_rate),
        channels,
        samples,
    ))
}

fn decode_runtime_media_asset_with_symphonia(
    path: &Path,
    asset_id: &str,
) -> Result<AudioBuffer, RuntimeError> {
    let file = fs::File::open(path).map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to open cached media asset `{asset_id}` at {}: {error}",
                path.display()
            ),
        )
    })?;
    let media_stream = MediaSourceStream::new(Box::new(file), Default::default());
    let mut hint = SymphoniaHint::new();
    if let Some(extension) = path.extension().and_then(|extension| extension.to_str()) {
        hint.with_extension(extension);
    }

    let probed = symphonia::default::get_probe()
        .format(
            &hint,
            media_stream,
            &SymphoniaFormatOptions::default(),
            &SymphoniaMetadataOptions::default(),
        )
        .map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to probe cached media asset `{asset_id}` at {}: {error}",
                    path.display()
                ),
            )
        })?;

    let mut format = probed.format;
    let track = format
        .tracks()
        .iter()
        .find(|track| track.codec_params.codec != CODEC_TYPE_NULL)
        .ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::UnsupportedCapability,
                format!(
                    "cached media asset `{asset_id}` at {} has no supported audio track",
                    path.display()
                ),
            )
        })?;
    let track_id = track.id;
    let mut decoder = symphonia::default::get_codecs()
        .make(&track.codec_params, &SymphoniaDecoderOptions::default())
        .map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to create cached media decoder for `{asset_id}` at {}: {error}",
                    path.display()
                ),
            )
        })?;

    let mut sample_rate = None;
    let mut channel_count = None;
    let mut samples = Vec::new();
    loop {
        let packet = match format.next_packet() {
            Ok(packet) => packet,
            Err(SymphoniaError::IoError(error))
                if error.kind() == std::io::ErrorKind::UnexpectedEof =>
            {
                break;
            }
            Err(SymphoniaError::ResetRequired) => {
                decoder.reset();
                continue;
            }
            Err(error) => {
                return Err(RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to read cached media packet for `{asset_id}` at {}: {error}",
                        path.display()
                    ),
                ));
            }
        };
        if packet.track_id() != track_id {
            continue;
        }
        let decoded = match decoder.decode(&packet) {
            Ok(decoded) => decoded,
            Err(SymphoniaError::DecodeError(_)) => continue,
            Err(error) => {
                return Err(RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to decode cached media asset `{asset_id}` at {}: {error}",
                        path.display()
                    ),
                ));
            }
        };
        let spec = *decoded.spec();
        let actual_channels = spec.channels.count();
        let output_channels = actual_channels.clamp(1, 2);
        if sample_rate.is_none() {
            sample_rate = Some(spec.rate);
            channel_count = Some(output_channels);
        }

        let mut sample_buffer = SymphoniaSampleBuffer::<f32>::new(decoded.capacity() as u64, spec);
        sample_buffer.copy_interleaved_ref(decoded);
        let interleaved = sample_buffer.samples();
        if actual_channels <= output_channels {
            samples.extend_from_slice(interleaved);
        } else {
            for frame in interleaved.chunks(actual_channels) {
                for channel_index in 0..output_channels {
                    samples.push(frame[channel_index]);
                }
            }
        }
    }

    let sample_rate = sample_rate.ok_or_else(|| {
        RuntimeError::new(
            RuntimeErrorKind::UnsupportedCapability,
            format!(
                "cached media asset `{asset_id}` at {} produced no decodable audio frames",
                path.display()
            ),
        )
    })?;
    let channels = match channel_count.unwrap_or(1) {
        1 => ChannelLayout::Mono,
        2 => ChannelLayout::Stereo,
        count => ChannelLayout::Count(signal_primitives::ChannelCount(count)),
    };
    Ok(AudioBuffer::from_interleaved(
        SampleRate(sample_rate),
        channels,
        samples,
    ))
}

fn write_audio_buffer_wav(path: &Path, buffer: &AudioBuffer) -> Result<(), RuntimeError> {
    let spec = WavSpec {
        channels: buffer.channel_count().0 as u16,
        sample_rate: buffer.sample_rate().0,
        bits_per_sample: 32,
        sample_format: HoundSampleFormat::Float,
    };
    let mut writer = WavWriter::create(path, spec).map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to create offline render wav {}: {error}",
                path.display()
            ),
        )
    })?;
    for sample in buffer.samples() {
        writer.write_sample(*sample).map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to write offline render wav sample {}: {error}",
                    path.display()
                ),
            )
        })?;
    }
    writer.finalize().map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to finalize offline render wav {}: {error}",
                path.display()
            ),
        )
    })
}

fn render_artifact_receipt(
    artifact_id: String,
    artifact_kind: RuntimeOfflineRenderArtifactKind,
    output_path: String,
    byte_size: u64,
    buffer: &AudioBuffer,
) -> RuntimeOfflineRenderArtifactReceipt {
    let peak_level = peak_abs(buffer.samples());
    let rms_level = rms(buffer.samples());
    RuntimeOfflineRenderArtifactReceipt {
        artifact_id: artifact_id.clone(),
        artifact_kind,
        output_path: output_path.clone(),
        sample_rate_hz: buffer.sample_rate().0,
        channel_count: buffer.channel_count().0,
        frame_count: buffer.frames().0,
        byte_size,
        peak_level,
        rms_level,
        summary: format!(
            "artifact={} kind={:?} path={} sample_rate={} channels={} frames={} bytes={} peak={:.3} rms={:.3}",
            artifact_id,
            artifact_kind,
            output_path,
            buffer.sample_rate().0,
            buffer.channel_count().0,
            buffer.frames().0,
            byte_size,
            peak_level,
            rms_level,
        ),
    }
}

fn json_escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

fn offline_render_manifest(
    request_id: &str,
    artifact_root_path: Option<&str>,
    artifacts: Vec<RuntimeOfflineRenderArtifactReceipt>,
    report: Option<RuntimeOfflineRenderReportReceipt>,
    delegated_execution_request: RuntimeOfflinePluginDelegatedExecutionRequest,
    delegated_execution_receipt: Option<RuntimeOfflinePluginDelegatedExecutionReceipt>,
) -> RuntimeOfflineRenderManifest {
    let materialized = !artifacts.is_empty() || report.is_some();
    let artifact_count = artifacts.len();
    let mut manifest = RuntimeOfflineRenderManifest {
        request_id: request_id.to_string(),
        artifact_root_path: artifact_root_path.map(str::to_string),
        materialized,
        artifact_count,
        artifacts,
        report,
        delegated_execution_request,
        delegated_execution_receipt,
        summary: String::new(),
    };
    manifest.summary = format!(
        "request={} root={:?} materialized={} artifacts={} report={} delegated_request_stages={} delegated_receipt={}",
        manifest.request_id,
        manifest.artifact_root_path.as_deref(),
        manifest.materialized,
        manifest.artifact_count,
        manifest.report.is_some(),
        manifest.delegated_execution_request.stage_count,
        manifest.delegated_execution_receipt.is_some(),
    );
    manifest
}

fn offline_render_report_json(
    result: &RuntimeOfflineRenderResult,
    artifact_receipts: &[RuntimeOfflineRenderArtifactReceipt],
) -> String {
    let artifacts = artifact_receipts
        .iter()
        .map(|artifact| {
            format!(
                "{{\"artifact_id\":\"{}\",\"artifact_kind\":\"{:?}\",\"output_path\":\"{}\",\"sample_rate_hz\":{},\"channel_count\":{},\"frame_count\":{},\"byte_size\":{},\"peak_level\":{:.6},\"rms_level\":{:.6}}}",
                json_escape(&artifact.artifact_id),
                artifact.artifact_kind,
                json_escape(&artifact.output_path),
                artifact.sample_rate_hz,
                artifact.channel_count,
                artifact.frame_count,
                artifact.byte_size,
                artifact.peak_level,
                artifact.rms_level,
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let delegated_request_stages = result
        .manifest
        .delegated_execution_request
        .stages
        .iter()
        .map(|stage| {
            format!(
                "{{\"chain_id\":\"{}\",\"stage_index\":{},\"node_id\":\"{}\",\"sandbox_id\":{},\"plugin_type_id\":{},\"plugin_format\":{},\"recall_state\":\"{:?}\",\"override_state\":\"{:?}\"}}",
                json_escape(&stage.chain_id),
                stage.stage_index,
                json_escape(&stage.node_id),
                stage.sandbox_id.as_deref().map(|id| format!("\"{}\"", json_escape(id))).unwrap_or_else(|| "null".into()),
                stage.plugin_type_id.as_deref().map(|id| format!("\"{}\"", json_escape(id))).unwrap_or_else(|| "null".into()),
                stage.plugin_format.map(|format| format!("\"{format:?}\"")).unwrap_or_else(|| "null".into()),
                stage.recall_state,
                stage.override_state,
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let delegated_receipt = result
        .manifest
        .delegated_execution_receipt
        .as_ref()
        .map(|receipt| {
            let stages = receipt
                .stages
                .iter()
                .map(|stage| {
                    format!(
                        "{{\"chain_id\":\"{}\",\"stage_index\":{},\"node_id\":\"{}\",\"status\":\"{:?}\",\"delegate_label\":{},\"detail\":{}}}",
                        json_escape(&stage.chain_id),
                        stage.stage_index,
                        json_escape(&stage.node_id),
                        stage.status,
                        stage
                            .delegate_label
                            .as_deref()
                            .map(|label| format!("\"{}\"", json_escape(label)))
                            .unwrap_or_else(|| "null".into()),
                        stage
                            .detail
                            .as_deref()
                            .map(|detail| format!("\"{}\"", json_escape(detail)))
                            .unwrap_or_else(|| "null".into()),
                    )
                })
                .collect::<Vec<_>>()
                .join(",");
            format!(
                "{{\"stage_count\":{},\"completed_stage_count\":{},\"rejected_stage_count\":{},\"unavailable_stage_count\":{},\"stages\":[{}]}}",
                receipt.stage_count,
                receipt.completed_stage_count,
                receipt.rejected_stage_count,
                receipt.unavailable_stage_count,
                stages,
            )
        })
        .unwrap_or_else(|| "null".into());
    format!(
        "{{\"request_id\":\"{}\",\"runtime_frame_count\":{},\"rendered_frame_count\":{},\"block_count\":{},\"export_sample_rate_hz\":{},\"artifact_count\":{},\"delegated_stage_count\":{},\"delegated_receipt_stage_count\":{},\"delegated_execution_request\":{{\"stage_count\":{},\"stages\":[{}]}},\"delegated_execution_receipt\":{},\"summary\":\"{}\",\"artifacts\":[{}]}}",
        json_escape(&result.request_id),
        result.runtime_frame_count,
        result.rendered_frame_count,
        result.block_count,
        result.export_sample_rate_hz,
        artifact_receipts.len(),
        result.manifest.delegated_execution_request.stage_count,
        result
            .manifest
            .delegated_execution_receipt
            .as_ref()
            .map_or(0, |receipt| receipt.stage_count),
        result.manifest.delegated_execution_request.stage_count,
        delegated_request_stages,
        delegated_receipt,
        json_escape(&result.summary),
        artifacts,
    )
}

fn write_offline_render_report(
    path: &Path,
    result: &RuntimeOfflineRenderResult,
) -> Result<u64, RuntimeError> {
    let report_body = offline_render_report_json(result, &result.manifest.artifacts);
    fs::write(path, report_body.as_bytes()).map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to write offline render report {}: {error}",
                path.display()
            ),
        )
    })?;
    fs::metadata(path)
        .map(|metadata| metadata.len())
        .map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to inspect offline render report {}: {error}",
                    path.display()
                ),
            )
        })
}

fn offline_plugin_delegated_execution_request(
    boundary: &RuntimeOfflinePluginExecutionBoundary,
) -> RuntimeOfflinePluginDelegatedExecutionRequest {
    boundary.delegated_execution_request()
}

fn offline_render_report_receipt(
    request_id: &str,
    report_path: &Path,
    artifact_count: usize,
) -> Result<RuntimeOfflineRenderReportReceipt, RuntimeError> {
    let report_size = fs::metadata(report_path)
        .map(|metadata| metadata.len())
        .map_err(|error| {
            RuntimeError::new(
                RuntimeErrorKind::ResourceUnavailable,
                format!(
                    "failed to inspect offline render report {}: {error}",
                    report_path.display()
                ),
            )
        })?;
    Ok(RuntimeOfflineRenderReportReceipt {
        request_id: request_id.to_string(),
        report_path: report_path.display().to_string(),
        artifact_count,
        byte_size: report_size,
        summary: format!(
            "request={} report_path={} artifacts={} bytes={}",
            request_id,
            report_path.display(),
            artifact_count,
            report_size,
        ),
    })
}

fn materialize_offline_render_delivery(
    result: &RuntimeOfflineRenderResult,
) -> Result<RuntimeOfflineRenderManifest, RuntimeError> {
    let delegated_execution_request = result.manifest.delegated_execution_request.clone();
    let delegated_execution_receipt = result.manifest.delegated_execution_receipt.clone();
    let Some(root_path) = result.manifest.artifact_root_path.as_deref() else {
        return Ok(offline_render_manifest(
            &result.request_id,
            None,
            Vec::new(),
            None,
            delegated_execution_request,
            delegated_execution_receipt,
        ));
    };

    let root = Path::new(root_path);
    fs::create_dir_all(root).map_err(|error| {
        RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!("failed to create offline render artifact directory: {error}"),
        )
    })?;
    let request_slug = sanitize_asset_id(&result.request_id);
    let mut artifact_receipts = Vec::new();
    if let Some(main_mix) = result.main_mix.as_ref() {
        let path = root.join(format!("{request_slug}-main-mix.wav"));
        write_audio_buffer_wav(&path, main_mix)?;
        let byte_size = fs::metadata(&path)
            .map(|metadata| metadata.len())
            .map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact {}: {error}",
                        path.display()
                    ),
                )
            })?;
        artifact_receipts.push(render_artifact_receipt(
            "main_mix".into(),
            RuntimeOfflineRenderArtifactKind::MainMix,
            path.display().to_string(),
            byte_size,
            main_mix,
        ));
    }
    for stem in &result.stems {
        let path = root.join(format!(
            "{request_slug}-stem-{}.wav",
            sanitize_asset_id(&stem.stem_id)
        ));
        write_audio_buffer_wav(&path, &stem.output)?;
        let byte_size = fs::metadata(&path)
            .map(|metadata| metadata.len())
            .map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact {}: {error}",
                        path.display()
                    ),
                )
            })?;
        artifact_receipts.push(render_artifact_receipt(
            stem.stem_id.clone(),
            RuntimeOfflineRenderArtifactKind::Stem,
            path.display().to_string(),
            byte_size,
            &stem.output,
        ));
    }
    for artifact in &result.freeze_artifacts {
        let path = root.join(format!(
            "{request_slug}-freeze-{}.wav",
            sanitize_asset_id(&artifact.artifact_id)
        ));
        write_audio_buffer_wav(&path, &artifact.output)?;
        let byte_size = fs::metadata(&path)
            .map(|metadata| metadata.len())
            .map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact {}: {error}",
                        path.display()
                    ),
                )
            })?;
        artifact_receipts.push(render_artifact_receipt(
            artifact.artifact_id.clone(),
            RuntimeOfflineRenderArtifactKind::FreezeArtifact,
            path.display().to_string(),
            byte_size,
            &artifact.output,
        ));
    }

    let report_path = root.join(format!("{request_slug}-report.json"));
    let result_for_report = RuntimeOfflineRenderResult {
        manifest: offline_render_manifest(
            &result.request_id,
            Some(root_path),
            artifact_receipts.clone(),
            None,
            delegated_execution_request.clone(),
            delegated_execution_receipt.clone(),
        ),
        ..result.clone()
    };
    write_offline_render_report(&report_path, &result_for_report)?;
    let report_receipt =
        offline_render_report_receipt(&result.request_id, &report_path, artifact_receipts.len())?;

    Ok(offline_render_manifest(
        &result.request_id,
        Some(root_path),
        artifact_receipts,
        Some(report_receipt),
        delegated_execution_request,
        delegated_execution_receipt,
    ))
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct OfflineRenderPurgeOutcome {
    removed: bool,
    file_count: usize,
    byte_count: u64,
}

fn offline_render_file_size(path: &Path) -> Result<Option<u64>, RuntimeError> {
    match fs::metadata(path) {
        Ok(metadata) => Ok(Some(metadata.len())),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to inspect offline render file {}: {error}",
                path.display()
            ),
        )),
    }
}

fn offline_render_directory_stats(path: &Path) -> Result<Option<(usize, u64)>, RuntimeError> {
    let mut file_count = 0usize;
    let mut byte_count = 0u64;
    let mut directories = VecDeque::from([path.to_path_buf()]);
    while let Some(directory) = directories.pop_front() {
        let entries = match fs::read_dir(&directory) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return if directory == path {
                    Ok(None)
                } else {
                    Err(RuntimeError::new(
                        RuntimeErrorKind::ResourceUnavailable,
                        format!(
                            "offline render artifact root changed while purging {}",
                            path.display()
                        ),
                    ))
                };
            }
            Err(error) => {
                return Err(RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact root {}: {error}",
                        directory.display()
                    ),
                ));
            }
        };
        for entry in entries {
            let entry = entry.map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact entry under {}: {error}",
                        path.display()
                    ),
                )
            })?;
            let entry_path = entry.path();
            let metadata = entry.metadata().map_err(|error| {
                RuntimeError::new(
                    RuntimeErrorKind::ResourceUnavailable,
                    format!(
                        "failed to inspect offline render artifact metadata for {}: {error}",
                        entry_path.display()
                    ),
                )
            })?;
            if metadata.is_dir() {
                directories.push_back(entry_path);
            } else {
                file_count = file_count.saturating_add(1);
                byte_count = byte_count.saturating_add(metadata.len());
            }
        }
    }
    Ok(Some((file_count, byte_count)))
}

fn summarize_deferred_service_receipt(receipt: &RuntimeDeferredServiceReceipt) -> String {
    format!(
        "class={:?} decision={:?} reason={:?} priority={:?} blocking={:?} backpressure={:?} starvation={}/{} cancellation={:?}/{} interruption={:?}/rebindable={} queued={} admitted={} completed={} deferred={} running={} safe_mode={} degraded={} cleanup_pending={} deferred_retries={} recovery_overlap={}",
        receipt.work_class,
        receipt.decision,
        receipt.reason,
        receipt.priority_band,
        receipt.blocking_priority_band,
        receipt.backpressure_source,
        receipt.starvation_risk,
        receipt.starved_work_item_count,
        receipt.cancellation_cause,
        receipt.cancelled_work_item_count,
        receipt.interruption_class,
        receipt.interruption_rebindable,
        receipt.queued_work_item_count,
        receipt.admitted_work_item_count,
        receipt.completed_work_item_count,
        receipt.deferred_work_item_count,
        receipt.runtime_running,
        receipt.safe_mode_enabled,
        receipt.readiness_degraded,
        receipt.pending_cleanup_work_items,
        receipt.pending_deferred_retry_work_items,
        receipt.recovery_overlap_session_count,
    )
}

fn deferred_service_interruption_class(
    decision: RuntimeDeferredServiceDecision,
) -> RuntimeInterruptionClass {
    match decision {
        RuntimeDeferredServiceDecision::Run => RuntimeInterruptionClass::Steady,
        RuntimeDeferredServiceDecision::Defer | RuntimeDeferredServiceDecision::Throttle => {
            RuntimeInterruptionClass::Resumable
        }
        RuntimeDeferredServiceDecision::Abort => RuntimeInterruptionClass::Terminal,
    }
}

fn deferred_service_receipt(
    work_class: RuntimeDeferredServiceClass,
    decision: RuntimeDeferredServiceDecision,
    reason: RuntimeDeferredServiceReason,
    queued_work_item_count: usize,
    admitted_work_item_count: usize,
    runtime_running: bool,
    safe_mode_enabled: bool,
    readiness_degraded: bool,
    pending_cleanup_work_items: usize,
    pending_deferred_retry_work_items: usize,
    recovery_overlap_session_count: usize,
) -> RuntimeDeferredServiceReceipt {
    let priority_band = deferred_service_priority_band(work_class);
    let deferred_work_item_count = queued_work_item_count.saturating_sub(admitted_work_item_count);
    let starved_work_item_count = match decision {
        RuntimeDeferredServiceDecision::Defer | RuntimeDeferredServiceDecision::Throttle => {
            deferred_work_item_count
        }
        RuntimeDeferredServiceDecision::Run | RuntimeDeferredServiceDecision::Abort => 0,
    };
    let cancelled_work_item_count = match decision {
        RuntimeDeferredServiceDecision::Abort => queued_work_item_count,
        RuntimeDeferredServiceDecision::Run
        | RuntimeDeferredServiceDecision::Defer
        | RuntimeDeferredServiceDecision::Throttle => 0,
    };
    let mut receipt = RuntimeDeferredServiceReceipt {
        work_class,
        decision,
        reason,
        priority_band,
        blocking_priority_band: deferred_service_blocking_priority_band(reason),
        backpressure_source: deferred_service_backpressure_source(reason),
        starvation_risk: starved_work_item_count > 0,
        starved_work_item_count,
        cancellation_cause: deferred_service_cancellation_cause(decision, reason),
        cancelled_work_item_count,
        interruption_class: deferred_service_interruption_class(decision),
        interruption_rebindable: false,
        queued_work_item_count,
        admitted_work_item_count,
        completed_work_item_count: 0,
        deferred_work_item_count,
        runtime_running,
        safe_mode_enabled,
        readiness_degraded,
        pending_cleanup_work_items,
        pending_deferred_retry_work_items,
        recovery_overlap_session_count,
        summary: String::new(),
    };
    receipt.summary = summarize_deferred_service_receipt(&receipt);
    receipt
}

fn deferred_service_priority_band(
    work_class: RuntimeDeferredServiceClass,
) -> RuntimeDeferredServicePriorityBand {
    match work_class {
        RuntimeDeferredServiceClass::OfflineRenderQueue => {
            RuntimeDeferredServicePriorityBand::UserVisible
        }
        RuntimeDeferredServiceClass::OfflineRenderPurge => {
            RuntimeDeferredServicePriorityBand::Maintenance
        }
    }
}

fn deferred_service_blocking_priority_band(
    reason: RuntimeDeferredServiceReason,
) -> Option<RuntimeDeferredServicePriorityBand> {
    match reason {
        RuntimeDeferredServiceReason::RealtimeActive => {
            Some(RuntimeDeferredServicePriorityBand::RealtimeCritical)
        }
        RuntimeDeferredServiceReason::PendingCleanup
        | RuntimeDeferredServiceReason::RecoveryDegraded
        | RuntimeDeferredServiceReason::SafeMode => {
            Some(RuntimeDeferredServicePriorityBand::RecoveryCritical)
        }
        RuntimeDeferredServiceReason::Ready | RuntimeDeferredServiceReason::InvalidRequest => None,
    }
}

fn deferred_service_backpressure_source(
    reason: RuntimeDeferredServiceReason,
) -> Option<RuntimeDeferredServiceBackpressureSource> {
    match reason {
        RuntimeDeferredServiceReason::RealtimeActive => {
            Some(RuntimeDeferredServiceBackpressureSource::RealtimeAudio)
        }
        RuntimeDeferredServiceReason::PendingCleanup => {
            Some(RuntimeDeferredServiceBackpressureSource::CleanupBacklog)
        }
        RuntimeDeferredServiceReason::RecoveryDegraded => {
            Some(RuntimeDeferredServiceBackpressureSource::RecoveryOverlap)
        }
        RuntimeDeferredServiceReason::SafeMode => {
            Some(RuntimeDeferredServiceBackpressureSource::SafeMode)
        }
        RuntimeDeferredServiceReason::Ready | RuntimeDeferredServiceReason::InvalidRequest => None,
    }
}

fn deferred_service_cancellation_cause(
    decision: RuntimeDeferredServiceDecision,
    reason: RuntimeDeferredServiceReason,
) -> Option<RuntimeDeferredServiceCancellationCause> {
    match (decision, reason) {
        (RuntimeDeferredServiceDecision::Abort, RuntimeDeferredServiceReason::InvalidRequest) => {
            Some(RuntimeDeferredServiceCancellationCause::InvalidRequest)
        }
        _ => None,
    }
}

fn offline_render_execution_interruption_class(
    state: RuntimeOfflineRenderExecutionState,
) -> RuntimeInterruptionClass {
    match state {
        RuntimeOfflineRenderExecutionState::Running
        | RuntimeOfflineRenderExecutionState::Completed => RuntimeInterruptionClass::Steady,
        RuntimeOfflineRenderExecutionState::Paused
        | RuntimeOfflineRenderExecutionState::Recoverable => RuntimeInterruptionClass::Resumable,
        RuntimeOfflineRenderExecutionState::Cancelled
        | RuntimeOfflineRenderExecutionState::Failed => RuntimeInterruptionClass::Terminal,
    }
}

fn offline_render_execution_observed_interruption_class(
    session: &RuntimeOfflineRenderExecutionSession,
) -> RuntimeInterruptionClass {
    session
        .interruption_class_override
        .unwrap_or_else(|| offline_render_execution_interruption_class(session.state))
}

fn offline_render_execution_interruption_rebindable(
    session: &RuntimeOfflineRenderExecutionSession,
) -> bool {
    session.delegated_execution_request.stage_count > 0
        && matches!(
            session.state,
            RuntimeOfflineRenderExecutionState::Paused
                | RuntimeOfflineRenderExecutionState::Recoverable
        )
}

fn purge_offline_render_file(path: &Path) -> Result<OfflineRenderPurgeOutcome, RuntimeError> {
    let byte_count = offline_render_file_size(path)?.unwrap_or(0);
    match fs::remove_file(path) {
        Ok(()) => Ok(OfflineRenderPurgeOutcome {
            removed: true,
            file_count: 1,
            byte_count,
        }),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Ok(OfflineRenderPurgeOutcome::default())
        }
        Err(error) => Err(RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to remove offline render file {}: {error}",
                path.display()
            ),
        )),
    }
}

fn purge_offline_render_directory(path: &Path) -> Result<OfflineRenderPurgeOutcome, RuntimeError> {
    let (file_count, byte_count) = offline_render_directory_stats(path)?.unwrap_or((0, 0));
    match fs::remove_dir_all(path) {
        Ok(()) => Ok(OfflineRenderPurgeOutcome {
            removed: true,
            file_count,
            byte_count,
        }),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Ok(OfflineRenderPurgeOutcome::default())
        }
        Err(error) => Err(RuntimeError::new(
            RuntimeErrorKind::ResourceUnavailable,
            format!(
                "failed to remove offline render artifact root {}: {error}",
                path.display()
            ),
        )),
    }
}

fn ensure_offline_buffer_compatible(
    label: &str,
    expected: &AudioBuffer,
    actual: &AudioBuffer,
) -> Result<(), RuntimeError> {
    if expected.sample_rate() != actual.sample_rate() {
        return Err(RuntimeError::new(
            RuntimeErrorKind::InvalidRequest,
            format!(
                "delegated offline merge `{label}` sample rate does not match runtime result (expected={} actual={})",
                expected.sample_rate().0,
                actual.sample_rate().0,
            ),
        ));
    }
    if expected.channel_count() != actual.channel_count() {
        return Err(RuntimeError::new(
            RuntimeErrorKind::InvalidRequest,
            format!(
                "delegated offline merge `{label}` channel count does not match runtime result (expected={} actual={})",
                expected.channel_count().0,
                actual.channel_count().0,
            ),
        ));
    }
    if expected.frames() != actual.frames() {
        return Err(RuntimeError::new(
            RuntimeErrorKind::InvalidRequest,
            format!(
                "delegated offline merge `{label}` frame count does not match runtime result (expected={} actual={})",
                expected.frames().0,
                actual.frames().0,
            ),
        ));
    }
    Ok(())
}

fn refresh_offline_render_stem_result(stem: &mut RuntimeOfflineRenderStemResult) {
    stem.peak_level = peak_abs(stem.output.samples());
    stem.rms_level = rms(stem.output.samples());
    stem.summary = format!(
        "stem={} target={:?}/{:?} frames={} peak={:.3} rms={:.3}",
        stem.stem_id,
        stem.target_kind,
        stem.target_id,
        stem.output.frames().0,
        stem.peak_level,
        stem.rms_level,
    );
}

fn refresh_offline_freeze_artifact_result(artifact: &mut RuntimeOfflineFreezeArtifactResult) {
    artifact.peak_level = peak_abs(artifact.output.samples());
    artifact.rms_level = rms(artifact.output.samples());
    artifact.summary = format!(
        "artifact={} source_stem={} recall_stages={} frames={} peak={:.3} rms={:.3}",
        artifact.artifact_id,
        artifact.source_stem_id,
        artifact.recall_stage_count,
        artifact.output.frames().0,
        artifact.peak_level,
        artifact.rms_level,
    );
}

fn refresh_offline_render_result(result: &mut RuntimeOfflineRenderResult) {
    if let Some(main_mix) = result.main_mix.as_ref() {
        result.main_mix_peak_level = Some(peak_abs(main_mix.samples()));
        result.main_mix_rms_level = Some(rms(main_mix.samples()));
    } else {
        result.main_mix_peak_level = None;
        result.main_mix_rms_level = None;
    }
    for stem in &mut result.stems {
        refresh_offline_render_stem_result(stem);
    }
    for artifact in &mut result.freeze_artifacts {
        refresh_offline_freeze_artifact_result(artifact);
    }
    result.rendered_frame_count = result
        .main_mix
        .as_ref()
        .map(|buffer| buffer.frames().0)
        .or_else(|| result.stems.first().map(|stem| stem.output.frames().0))
        .or_else(|| {
            result
                .freeze_artifacts
                .first()
                .map(|artifact| artifact.output.frames().0)
        })
        .unwrap_or(0);
    result.summary = format!(
        "request={} runtime_frames={} rendered_frames={} blocks={} main_mix={} stems={} freeze_artifacts={}",
        result.request_id,
        result.runtime_frame_count,
        result.rendered_frame_count,
        result.block_count,
        result.main_mix.is_some(),
        result.stems.len(),
        result.freeze_artifacts.len(),
    );
}

fn apply_delegated_execution_merge(
    result: &mut RuntimeOfflineRenderResult,
    merge: &RuntimeOfflinePluginDelegatedExecutionMerge,
) -> Result<(), RuntimeError> {
    if merge.request_id != result.request_id {
        return Err(RuntimeError::new(
            RuntimeErrorKind::InvalidRequest,
            format!(
                "delegated offline merge request `{}` does not match runtime result request `{}`",
                merge.request_id, result.request_id
            ),
        ));
    }
    if let Some(main_mix) = merge.main_mix.as_ref() {
        let expected = result.main_mix.as_ref().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "delegated offline merge provided a main mix override for a render result without main mix output",
            )
        })?;
        ensure_offline_buffer_compatible("main_mix", expected, main_mix)?;
        result.main_mix = Some(main_mix.clone());
    }

    let mut seen_stems = BTreeSet::new();
    for stem_merge in &merge.stems {
        if !seen_stems.insert(stem_merge.stem_id.as_str()) {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!(
                    "delegated offline merge stem `{}` is duplicated",
                    stem_merge.stem_id
                ),
            ));
        }
        let stem = result
            .stems
            .iter_mut()
            .find(|stem| stem.stem_id == stem_merge.stem_id)
            .ok_or_else(|| {
                RuntimeError::new(
                    RuntimeErrorKind::InvalidRequest,
                    format!(
                        "delegated offline merge references unknown stem `{}`",
                        stem_merge.stem_id
                    ),
                )
            })?;
        ensure_offline_buffer_compatible(
            &format!("stem:{}", stem_merge.stem_id),
            &stem.output,
            &stem_merge.output,
        )?;
        stem.output = stem_merge.output.clone();
    }

    let mut seen_artifacts = BTreeSet::new();
    for artifact_merge in &merge.freeze_artifacts {
        if !seen_artifacts.insert(artifact_merge.artifact_id.as_str()) {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!(
                    "delegated offline merge freeze artifact `{}` is duplicated",
                    artifact_merge.artifact_id
                ),
            ));
        }
        let artifact = result
            .freeze_artifacts
            .iter_mut()
            .find(|artifact| artifact.artifact_id == artifact_merge.artifact_id)
            .ok_or_else(|| {
                RuntimeError::new(
                    RuntimeErrorKind::InvalidRequest,
                    format!(
                        "delegated offline merge references unknown freeze artifact `{}`",
                        artifact_merge.artifact_id
                    ),
                )
            })?;
        ensure_offline_buffer_compatible(
            &format!("freeze:{}", artifact_merge.artifact_id),
            &artifact.output,
            &artifact_merge.output,
        )?;
        artifact.output = artifact_merge.output.clone();
    }

    refresh_offline_render_result(result);
    Ok(())
}

fn offline_render_plugin_override_status<'a>(
    latest: Option<&'a RuntimePluginRenderedNodeState>,
    bound_sandbox_id: Option<&String>,
    sandboxes: &BTreeMap<String, RuntimePluginSandboxSnapshot>,
    last_processing_epoch: Option<u64>,
    last_block_sequence: Option<u64>,
) -> (
    RuntimeOfflinePluginOverrideState,
    Option<&'a RuntimePluginRenderedNodeState>,
) {
    let Some(latest) = latest else {
        return (RuntimeOfflinePluginOverrideState::NotAvailable, None);
    };
    let fresh = Some(latest.processing_epoch) == last_processing_epoch
        && Some(latest.block_sequence) == last_block_sequence
        && bound_sandbox_id.is_none_or(|sandbox_id| sandbox_id == &latest.sandbox_id)
        && bound_sandbox_id
            .and_then(|sandbox_id| sandboxes.get(sandbox_id))
            .is_none_or(|sandbox| sandbox.state == RuntimePluginLifecycleState::Ready);
    if fresh {
        (
            RuntimeOfflinePluginOverrideState::FreshLatestBlock,
            Some(latest),
        )
    } else {
        (RuntimeOfflinePluginOverrideState::StaleLatestBlock, None)
    }
}

fn runtime_meter_source_role(role: GraphNodeTopologyRole) -> RuntimeMeterSourceRole {
    match role {
        GraphNodeTopologyRole::Utility => RuntimeMeterSourceRole::Utility,
        GraphNodeTopologyRole::TrackLane => RuntimeMeterSourceRole::TrackLane,
        GraphNodeTopologyRole::Bus => RuntimeMeterSourceRole::Bus,
        GraphNodeTopologyRole::Send => RuntimeMeterSourceRole::Send,
        GraphNodeTopologyRole::Return => RuntimeMeterSourceRole::Return,
        GraphNodeTopologyRole::ConsoleNode => RuntimeMeterSourceRole::ConsoleNode,
    }
}

fn unique_string<'a>(values: impl Iterator<Item = &'a String>) -> Option<String> {
    let mut values = values.cloned().collect::<BTreeSet<_>>().into_iter();
    let first = values.next()?;
    if values.next().is_none() {
        Some(first)
    } else {
        None
    }
}

fn classify_transport_transition(
    previous: Option<TransportProjection>,
    next: TransportProjection,
) -> Option<RuntimeTransportTransitionKind> {
    let Some(previous) = previous else {
        return Some(if next.playing {
            RuntimeTransportTransitionKind::Started
        } else {
            RuntimeTransportTransitionKind::Initial
        });
    };
    if previous.playing != next.playing {
        return Some(if next.playing {
            RuntimeTransportTransitionKind::Started
        } else {
            RuntimeTransportTransitionKind::Stopped
        });
    }
    if previous.timeline_position_samples != next.timeline_position_samples {
        return Some(RuntimeTransportTransitionKind::Seeked);
    }
    if previous.tempo_bpm != next.tempo_bpm {
        return Some(RuntimeTransportTransitionKind::TempoChanged);
    }
    if previous.loop_state != next.loop_state {
        return Some(RuntimeTransportTransitionKind::LoopStateChanged);
    }
    None
}

fn classify_transport_invalidation_reason(
    previous: Option<TransportProjection>,
    next: TransportProjection,
) -> RuntimePreworkInvalidationReason {
    match classify_transport_transition(previous, next) {
        Some(RuntimeTransportTransitionKind::Started)
        | Some(RuntimeTransportTransitionKind::Initial) => {
            RuntimePreworkInvalidationReason::TransportStarted
        }
        Some(RuntimeTransportTransitionKind::Stopped) => {
            RuntimePreworkInvalidationReason::TransportStopped
        }
        Some(RuntimeTransportTransitionKind::Seeked) => {
            RuntimePreworkInvalidationReason::TransportSeeked
        }
        Some(RuntimeTransportTransitionKind::TempoChanged) => {
            RuntimePreworkInvalidationReason::TransportTempoChanged
        }
        Some(RuntimeTransportTransitionKind::LoopStateChanged) => {
            RuntimePreworkInvalidationReason::TransportLoopStateChanged
        }
        Some(RuntimeTransportTransitionKind::LoopWrapped) => {
            RuntimePreworkInvalidationReason::TransportLoopWrapped
        }
        None => RuntimePreworkInvalidationReason::TransportSeeked,
    }
}

fn transport_projection_from_context(context: &GraphExecutionContext) -> TransportProjection {
    TransportProjection {
        playing: context.transport_playing,
        timeline_position_samples: context.timeline_position_samples,
        tempo_bpm: context.transport_tempo_bpm,
        loop_state: None,
    }
}

const PREWORK_CACHE_BLOCK_FRESHNESS_WINDOW: u64 = 2;
const PREWORK_QUEUE_CAPACITY: usize = 3;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RuntimePendingTransportTransition {
    kind: RuntimeTransportTransitionKind,
    effective_block_sequence: Option<u64>,
    transport_epoch: u64,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct RuntimeEngineTransportAdvance {
    start_samples: Option<i64>,
    end_samples: Option<i64>,
    loop_wrapped: bool,
}

#[derive(Clone, Debug, Default, PartialEq)]
struct RuntimeTimelineState {
    next_block_sequence: u64,
    continuity: BlockSequenceContinuityReport,
    transport_epoch: u64,
    last_transport_transition: Option<RuntimeTransportTransitionKind>,
    last_transport_transition_processing_epoch: Option<u64>,
    last_transport_transition_block_sequence: Option<u64>,
    pending_transport_transition: Option<RuntimePendingTransportTransition>,
    last_transport_playing: Option<bool>,
    last_transport_tempo_bpm: Option<f64>,
    last_transport_timeline_position_samples: Option<i64>,
    last_transport_loop_start_samples: Option<i64>,
    last_transport_loop_end_samples: Option<i64>,
    last_engine_block_start_samples: Option<i64>,
    last_engine_block_end_samples: Option<i64>,
    loop_wrap_count: u64,
}

impl RuntimeTimelineState {
    fn allocate_block_sequence(&mut self) -> u64 {
        let block_sequence = self.next_block_sequence;
        self.next_block_sequence = self.next_block_sequence.saturating_add(1);
        block_sequence
    }

    fn record_block_sequence(
        &mut self,
        sandbox_id: &str,
        processing_epoch: u64,
        lease_id: impl Into<String>,
        block_sequence: u64,
    ) -> Option<LeaseRolloverRecord> {
        let lease_id = lease_id.into();
        let previous = self.continuity.segments.last().cloned();
        self.continuity
            .record(processing_epoch, lease_id.clone(), block_sequence);
        previous.and_then(|segment| {
            (segment.lease_id != lease_id).then(|| LeaseRolloverRecord {
                sandbox_id: sandbox_id.to_string(),
                previous_lease_id: segment.lease_id,
                lease_id,
                processing_epoch,
                first_block_sequence: block_sequence,
            })
        })
    }

    fn reset(&mut self) {
        *self = Self::default();
    }

    fn record_transport_projection(
        &mut self,
        kind: RuntimeTransportTransitionKind,
        effective_block_sequence: Option<u64>,
        processing_epoch: Option<u64>,
        projection: TransportProjection,
    ) -> u64 {
        self.transport_epoch = self.transport_epoch.saturating_add(1);
        self.last_transport_transition = Some(kind);
        self.last_transport_transition_processing_epoch = processing_epoch;
        self.last_transport_transition_block_sequence = effective_block_sequence;
        self.pending_transport_transition = Some(RuntimePendingTransportTransition {
            kind,
            effective_block_sequence,
            transport_epoch: self.transport_epoch,
        });
        self.update_transport_state(projection);
        self.transport_epoch
    }

    fn consume_pending_transport_transition(
        &mut self,
        block_sequence: u64,
    ) -> Option<RuntimePendingTransportTransition> {
        match self.pending_transport_transition {
            Some(pending)
                if pending
                    .effective_block_sequence
                    .map_or(true, |effective| effective == block_sequence) =>
            {
                self.pending_transport_transition = None;
                Some(pending)
            }
            _ => None,
        }
    }

    fn record_loop_wrap(
        &mut self,
        processing_epoch: u64,
        block_sequence: u64,
        projection: TransportProjection,
    ) -> u64 {
        self.transport_epoch = self.transport_epoch.saturating_add(1);
        self.loop_wrap_count = self.loop_wrap_count.saturating_add(1);
        self.last_transport_transition = Some(RuntimeTransportTransitionKind::LoopWrapped);
        self.last_transport_transition_processing_epoch = Some(processing_epoch);
        self.last_transport_transition_block_sequence = Some(block_sequence);
        self.update_transport_state(projection);
        self.transport_epoch
    }

    fn record_engine_block_window(&mut self, start_samples: Option<i64>, end_samples: Option<i64>) {
        self.last_engine_block_start_samples = start_samples;
        self.last_engine_block_end_samples = end_samples;
    }

    fn update_transport_state(&mut self, projection: TransportProjection) {
        self.last_transport_playing = Some(projection.playing);
        self.last_transport_tempo_bpm = Some(projection.tempo_bpm);
        self.last_transport_timeline_position_samples = Some(projection.timeline_position_samples);
        self.last_transport_loop_start_samples = projection
            .loop_state
            .map(|loop_region| loop_region.start_samples);
        self.last_transport_loop_end_samples = projection
            .loop_state
            .map(|loop_region| loop_region.end_samples);
    }

    fn snapshot(&self) -> RuntimeTimelineSnapshot {
        RuntimeTimelineSnapshot {
            next_block_sequence: self.next_block_sequence,
            block_sequence_continuity: self.continuity.clone(),
            transport_epoch: self.transport_epoch,
            last_transport_transition: self.last_transport_transition,
            last_transport_transition_processing_epoch: self
                .last_transport_transition_processing_epoch,
            last_transport_transition_block_sequence: self.last_transport_transition_block_sequence,
            last_transport_playing: self.last_transport_playing,
            last_transport_tempo_bpm: self.last_transport_tempo_bpm,
            last_transport_timeline_position_samples: self.last_transport_timeline_position_samples,
            last_transport_loop_start_samples: self.last_transport_loop_start_samples,
            last_transport_loop_end_samples: self.last_transport_loop_end_samples,
            last_engine_block_start_samples: self.last_engine_block_start_samples,
            last_engine_block_end_samples: self.last_engine_block_end_samples,
            loop_wrap_count: self.loop_wrap_count,
        }
    }
}

fn sanitize_asset_id(asset_id: &str) -> String {
    asset_id
        .chars()
        .map(|character| match character {
            'a'..='z' | 'A'..='Z' | '0'..='9' | '-' | '_' => character,
            _ => '_',
        })
        .collect()
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct RuntimeAutomationBatchMetrics {
    projected_segment_count: usize,
    mapped_lane_count: usize,
    unmapped_lane_count: usize,
    hold_lane_count: usize,
    linear_lane_count: usize,
    strategy_max_sub_blocks: usize,
    min_ramp_step_samples: Option<usize>,
    max_sample_offset: Option<usize>,
}

#[derive(Clone, Debug, Default, PartialEq)]
struct RuntimeAutomationState {
    continuity: AutomationContinuityReport,
    projection: Option<RuntimeAutomationProjection>,
    projected_segment_count: usize,
    mapped_lane_count: usize,
    unmapped_lane_count: usize,
    hold_lane_count: usize,
    linear_lane_count: usize,
    last_batch_epoch: Option<u64>,
    last_batch_event_count: usize,
    last_batch_ignored_event_count: usize,
    last_batch_sub_block_count: usize,
    last_batch_coalesced_event_count: usize,
    last_batch_strategy_max_sub_blocks: usize,
    last_batch_min_ramp_step_samples: Option<usize>,
    last_batch_max_sample_offset: Option<usize>,
    last_block_sequence: Option<u64>,
    last_timeline_position_samples: Option<i64>,
    transport_playing: Option<bool>,
}

impl RuntimeAutomationState {
    fn record_summary(
        &mut self,
        processing_epoch: u64,
        lease_id: impl Into<String>,
        summary: ParameterAutomationSummary,
    ) {
        self.continuity.record(processing_epoch, lease_id, summary);
    }

    fn apply_projection(&mut self, mut projection: RuntimeAutomationProjection) {
        projection.lane_count = projection.lanes.len();
        projection.point_count = projection
            .lanes
            .iter()
            .map(|lane| lane.points.len())
            .sum::<usize>();
        for lane in &mut projection.lanes {
            lane.point_count = lane.points.len();
        }
        self.projection = Some(projection);
    }

    fn graph_parameter_batch(
        &self,
        graph: &GraphProjection,
        transport: Option<TransportProjection>,
        frame_count: usize,
        epoch: u64,
    ) -> (
        Option<GraphParameterBatch>,
        HashSet<String>,
        RuntimeAutomationBatchMetrics,
    ) {
        let Some(projection) = self.projection.as_ref() else {
            return (
                None,
                HashSet::new(),
                RuntimeAutomationBatchMetrics::default(),
            );
        };
        let Some(transport) = transport else {
            return (
                None,
                HashSet::new(),
                RuntimeAutomationBatchMetrics::default(),
            );
        };

        let mut metrics = RuntimeAutomationBatchMetrics::default();
        let mut events = Vec::new();
        let mut mapped_targets = HashSet::new();

        for lane in &projection.lanes {
            metrics.projected_segment_count = metrics
                .projected_segment_count
                .saturating_add(lane.points.len().saturating_sub(1));
            metrics.strategy_max_sub_blocks = metrics
                .strategy_max_sub_blocks
                .max(lane.resolution.max_sub_blocks.max(1));
            match lane.interpolation {
                RuntimeAutomationInterpolation::Hold => {
                    metrics.hold_lane_count = metrics.hold_lane_count.saturating_add(1);
                }
                RuntimeAutomationInterpolation::Linear => {
                    metrics.linear_lane_count = metrics.linear_lane_count.saturating_add(1);
                    metrics.min_ramp_step_samples = Some(
                        metrics
                            .min_ramp_step_samples
                            .map_or(lane.resolution.ramp_step_samples.max(1), |current| {
                                current.min(lane.resolution.ramp_step_samples.max(1))
                            }),
                    );
                }
            }

            let Some(target) =
                graph_parameter_target_from_runtime_automation_target(graph, &lane.target)
            else {
                metrics.unmapped_lane_count = metrics.unmapped_lane_count.saturating_add(1);
                continue;
            };
            metrics.mapped_lane_count = metrics.mapped_lane_count.saturating_add(1);
            mapped_targets.insert(lane.target.parameter_path());

            let mut block_events = BTreeMap::new();
            let sorted_points = sorted_runtime_automation_points(&lane.points);
            block_events.insert(
                0usize,
                automation_value_at_time(
                    lane.base_normalized_value,
                    &sorted_points,
                    lane.interpolation,
                    transport.timeline_position_samples,
                ),
            );
            for point in &sorted_points {
                if let Some(sample_offset) = automation_sample_offset_for_block(
                    transport.timeline_position_samples,
                    frame_count,
                    transport.loop_state,
                    point.time_samples,
                ) {
                    block_events.insert(sample_offset, point.normalized_value);
                }
            }
            if lane.interpolation == RuntimeAutomationInterpolation::Linear {
                for window in sorted_points.windows(2) {
                    let segment_start = &window[0];
                    let segment_end = &window[1];
                    if segment_end.time_samples <= segment_start.time_samples {
                        continue;
                    }
                    for sample_time in automation_linear_segment_sample_times_for_block(
                        transport.timeline_position_samples,
                        frame_count,
                        transport.loop_state,
                        segment_start.time_samples,
                        segment_end.time_samples,
                        lane.resolution.ramp_step_samples.max(1),
                    ) {
                        if let Some(sample_offset) = automation_sample_offset_for_block(
                            transport.timeline_position_samples,
                            frame_count,
                            transport.loop_state,
                            sample_time,
                        ) {
                            block_events.insert(
                                sample_offset,
                                automation_linear_value_at_time(
                                    segment_start.time_samples,
                                    segment_start.normalized_value,
                                    segment_end.time_samples,
                                    segment_end.normalized_value,
                                    sample_time,
                                ),
                            );
                        }
                    }
                }
            }

            for (sample_offset, value) in block_events {
                metrics.max_sample_offset = Some(
                    metrics
                        .max_sample_offset
                        .map_or(sample_offset, |last| last.max(sample_offset)),
                );
                events.push(GraphParameterEvent {
                    sample_offset,
                    target: target.clone(),
                    value,
                });
            }
        }

        if events.is_empty() {
            return (None, mapped_targets, metrics);
        }

        events.sort_by(|left, right| {
            left.target
                .node_id
                .cmp(&right.target.node_id)
                .then(left.target.stage_index.cmp(&right.target.stage_index))
                .then(
                    graph_stage_parameter_sort_key(left.target.parameter)
                        .cmp(&graph_stage_parameter_sort_key(right.target.parameter)),
                )
                .then(left.sample_offset.cmp(&right.sample_offset))
        });

        (
            Some(GraphParameterBatch {
                epoch,
                strategy: GraphParameterApplicationStrategy::SplitAtEvents {
                    max_sub_blocks: metrics.strategy_max_sub_blocks.max(1),
                },
                events,
            }),
            mapped_targets,
            metrics,
        )
    }

    fn record_execution(
        &mut self,
        block_sequence: u64,
        timeline_position_samples: Option<i64>,
        transport_playing: Option<bool>,
        parameter_epoch: Option<u64>,
        parameter_event_count: usize,
        parameter_ignored_event_count: usize,
        parameter_sub_block_count: usize,
        parameter_coalesced_event_count: usize,
        metrics: RuntimeAutomationBatchMetrics,
    ) {
        self.projected_segment_count = metrics.projected_segment_count;
        self.mapped_lane_count = metrics.mapped_lane_count;
        self.unmapped_lane_count = metrics.unmapped_lane_count;
        self.hold_lane_count = metrics.hold_lane_count;
        self.linear_lane_count = metrics.linear_lane_count;
        self.last_batch_epoch = parameter_epoch;
        self.last_batch_event_count = parameter_event_count;
        self.last_batch_ignored_event_count = parameter_ignored_event_count;
        self.last_batch_sub_block_count = parameter_sub_block_count;
        self.last_batch_coalesced_event_count = parameter_coalesced_event_count;
        self.last_batch_strategy_max_sub_blocks = metrics.strategy_max_sub_blocks;
        self.last_batch_min_ramp_step_samples = metrics.min_ramp_step_samples;
        self.last_batch_max_sample_offset = metrics.max_sample_offset;
        self.last_block_sequence = Some(block_sequence);
        self.last_timeline_position_samples = timeline_position_samples;
        self.transport_playing = transport_playing;
    }

    fn reset(&mut self) {
        *self = Self::default();
    }

    fn snapshot(&self) -> RuntimeAutomationSnapshot {
        let aggregate = self.continuity.aggregate();
        let lane_count = self
            .projection
            .as_ref()
            .map_or(0, |projection| projection.lane_count);
        let point_count = self
            .projection
            .as_ref()
            .map_or(0, |projection| projection.point_count);
        RuntimeAutomationSnapshot {
            lane_count,
            point_count,
            projected_segment_count: self.projected_segment_count,
            mapped_lane_count: self.mapped_lane_count,
            unmapped_lane_count: self.unmapped_lane_count,
            hold_lane_count: self.hold_lane_count,
            linear_lane_count: self.linear_lane_count,
            last_batch_epoch: self.last_batch_epoch,
            last_batch_event_count: self.last_batch_event_count,
            last_batch_ignored_event_count: self.last_batch_ignored_event_count,
            last_batch_sub_block_count: self.last_batch_sub_block_count,
            last_batch_coalesced_event_count: self.last_batch_coalesced_event_count,
            last_batch_strategy_max_sub_blocks: self.last_batch_strategy_max_sub_blocks,
            last_batch_min_ramp_step_samples: self.last_batch_min_ramp_step_samples,
            last_batch_max_sample_offset: self.last_batch_max_sample_offset,
            last_block_sequence: self.last_block_sequence,
            last_timeline_position_samples: self.last_timeline_position_samples,
            transport_playing: self.transport_playing,
            parameter_id: aggregate.parameter_id,
            value_events: aggregate.value_events,
            modulation_events: aggregate.modulation_events,
            gesture_begin_events: aggregate.gesture_begin_events,
            gesture_end_events: aggregate.gesture_end_events,
            first_value: aggregate.first_value,
            last_value: aggregate.last_value,
            last_modulation: aggregate.last_modulation,
            first_epoch: self.continuity.first_epoch(),
            last_epoch: self.continuity.last_epoch(),
            segment_count: self.continuity.segment_count(),
            segment_epochs: self.continuity.segment_epochs(),
            lease_rollovers: self.continuity.lease_rollovers,
        }
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RuntimePluginEventState {
    continuity: EventPacketContinuityReport,
    last_processing_epoch: Option<u64>,
    last_block_sequence: Option<u64>,
    last_generated_event_bytes: u32,
    last_batch_summary: EventPacketSummary,
}

impl RuntimePluginEventState {
    fn record_summary(
        &mut self,
        processing_epoch: u64,
        lease_id: impl Into<String>,
        block_sequence: u64,
        generated_event_bytes: u32,
        summary: EventPacketSummary,
    ) {
        self.continuity.record(processing_epoch, lease_id, summary);
        self.last_processing_epoch = Some(processing_epoch);
        self.last_block_sequence = Some(block_sequence);
        self.last_generated_event_bytes = generated_event_bytes;
        self.last_batch_summary = summary;
    }

    fn reset(&mut self) {
        *self = Self::default();
    }

    fn snapshot(&self) -> RuntimePluginEventSnapshot {
        let aggregate = self.continuity.aggregate();
        RuntimePluginEventSnapshot {
            last_processing_epoch: self.last_processing_epoch,
            last_block_sequence: self.last_block_sequence,
            last_generated_event_bytes: self.last_generated_event_bytes,
            last_batch_total_events: self.last_batch_summary.total_events,
            last_batch_parameter_value_events: self.last_batch_summary.parameter_value_events,
            last_batch_parameter_modulation_events: self
                .last_batch_summary
                .parameter_modulation_events,
            last_batch_parameter_gesture_events: self.last_batch_summary.parameter_gesture_events,
            last_batch_note_events: self.last_batch_summary.note_events,
            last_batch_note_expression_events: self.last_batch_summary.note_expression_events,
            last_batch_note_expression_pressure_events: self
                .last_batch_summary
                .note_expression_pressure_events,
            last_batch_note_expression_timbre_events: self
                .last_batch_summary
                .note_expression_timbre_events,
            last_batch_note_expression_tuning_events: self
                .last_batch_summary
                .note_expression_tuning_events,
            last_batch_midi_events: self.last_batch_summary.midi_events,
            total_events: aggregate.total_events,
            parameter_value_events: aggregate.parameter_value_events,
            parameter_modulation_events: aggregate.parameter_modulation_events,
            parameter_gesture_events: aggregate.parameter_gesture_events,
            note_events: aggregate.note_events,
            note_expression_events: aggregate.note_expression_events,
            note_expression_pressure_events: aggregate.note_expression_pressure_events,
            note_expression_timbre_events: aggregate.note_expression_timbre_events,
            note_expression_tuning_events: aggregate.note_expression_tuning_events,
            midi_events: aggregate.midi_events,
            mpe_posture: if aggregate.note_expression_events > 0 {
                RuntimeControllerExpressionMpePosture::Guarded
            } else {
                RuntimeControllerExpressionMpePosture::Unsupported
            },
            midi2_posture: if aggregate.note_expression_tuning_events > 0 {
                RuntimeControllerExpressionMidi2Posture::Guarded
            } else {
                RuntimeControllerExpressionMidi2Posture::Unsupported
            },
            first_epoch: self.continuity.first_epoch(),
            last_epoch: self.continuity.last_epoch(),
            segment_count: self.continuity.segment_count(),
            segment_epochs: self.continuity.segment_epochs(),
            lease_rollovers: self.continuity.lease_rollovers,
        }
    }
}

fn sorted_runtime_automation_points(
    points: &[crate::interfaces::RuntimeAutomationPointProjection],
) -> Vec<crate::interfaces::RuntimeAutomationPointProjection> {
    let mut points = points.to_vec();
    points.sort_by_key(|point| point.time_samples);
    points
}

fn automation_value_at_time(
    base_normalized_value: f32,
    points: &[crate::interfaces::RuntimeAutomationPointProjection],
    interpolation: RuntimeAutomationInterpolation,
    time_samples: i64,
) -> f32 {
    let mut previous_time = None;
    let mut previous_value = base_normalized_value;

    for point in points {
        if point.time_samples > time_samples {
            return match (interpolation, previous_time) {
                (RuntimeAutomationInterpolation::Linear, Some(previous_time))
                    if point.time_samples > previous_time =>
                {
                    automation_linear_value_at_time(
                        previous_time,
                        previous_value,
                        point.time_samples,
                        point.normalized_value,
                        time_samples,
                    )
                }
                _ => previous_value,
            };
        }
        previous_time = Some(point.time_samples);
        previous_value = point.normalized_value;
    }

    previous_value
}

fn automation_linear_value_at_time(
    start_time_samples: i64,
    start_value: f32,
    end_time_samples: i64,
    end_value: f32,
    time_samples: i64,
) -> f32 {
    if end_time_samples <= start_time_samples {
        return end_value;
    }
    let span = (end_time_samples - start_time_samples) as f32;
    let offset =
        (time_samples - start_time_samples).clamp(0, end_time_samples - start_time_samples) as f32;
    start_value + ((end_value - start_value) * (offset / span))
}

fn automation_linear_segment_sample_times_for_block(
    block_start_samples: i64,
    frame_count: usize,
    loop_state: Option<crate::interfaces::LoopRegion>,
    segment_start_samples: i64,
    segment_end_samples: i64,
    ramp_step_samples: usize,
) -> Vec<i64> {
    if segment_end_samples <= segment_start_samples {
        return Vec::new();
    }

    let mut sample_times = Vec::new();
    let step = ramp_step_samples.max(1) as i64;
    let block_end_samples = block_start_samples.saturating_add(frame_count as i64);
    let first_sample = if block_start_samples < segment_start_samples {
        segment_start_samples.saturating_add(step)
    } else {
        let delta = block_start_samples.saturating_sub(segment_start_samples);
        let steps = delta.div_euclid(step).saturating_add(1);
        segment_start_samples.saturating_add(steps.saturating_mul(step))
    };

    let mut sample_time = first_sample;
    while sample_time < segment_end_samples && sample_time < block_end_samples {
        if automation_sample_offset_for_block(
            block_start_samples,
            frame_count,
            loop_state,
            sample_time,
        )
        .is_some()
        {
            sample_times.push(sample_time);
        }
        sample_time = sample_time.saturating_add(step);
    }
    sample_times
}

fn automation_sample_offset_for_block(
    block_start_samples: i64,
    frame_count: usize,
    loop_state: Option<crate::interfaces::LoopRegion>,
    point_time_samples: i64,
) -> Option<usize> {
    let block_end_samples = block_start_samples.saturating_add(frame_count as i64);
    if point_time_samples >= block_start_samples && point_time_samples < block_end_samples {
        return usize::try_from(point_time_samples.saturating_sub(block_start_samples)).ok();
    }

    let Some(loop_state) = loop_state else {
        return None;
    };
    if loop_state.end_samples <= loop_state.start_samples
        || block_end_samples <= loop_state.end_samples
    {
        return None;
    }

    let wrapped_span = block_end_samples.saturating_sub(loop_state.end_samples);
    if point_time_samples < loop_state.start_samples
        || point_time_samples >= loop_state.start_samples.saturating_add(wrapped_span)
    {
        return None;
    }

    usize::try_from(
        loop_state
            .end_samples
            .saturating_sub(block_start_samples)
            .saturating_add(point_time_samples.saturating_sub(loop_state.start_samples)),
    )
    .ok()
}

fn graph_parameter_target_from_runtime_automation_target(
    graph: &GraphProjection,
    target: &RuntimeAutomationTargetProjection,
) -> Option<GraphParameterTarget> {
    graph_parameter_target_from_runtime_parameter_path(graph, &target.node_id, &target.parameter_id)
}

fn graph_parameter_target_from_runtime_target(
    graph: &GraphProjection,
    target: &str,
) -> Option<GraphParameterTarget> {
    let (node_id, parameter_id) = target.rsplit_once('.')?;
    graph_parameter_target_from_runtime_parameter_path(graph, node_id, parameter_id)
}

fn graph_parameter_target_from_runtime_parameter_path(
    graph: &GraphProjection,
    node_id: &str,
    parameter_id: &str,
) -> Option<GraphParameterTarget> {
    let parameter = graph_stage_parameter_from_runtime_parameter_id(parameter_id)?;
    let stage_index = graph
        .nodes
        .iter()
        .find(|node| node.node_id == node_id)
        .and_then(|node| {
            node.stages
                .iter()
                .position(|stage| graph_stage_parameter_applies_to(parameter, stage))
        })?;
    Some(GraphParameterTarget {
        node_id: node_id.to_string(),
        stage_index,
        parameter,
    })
}

fn graph_stage_parameter_from_runtime_parameter_id(
    parameter_id: &str,
) -> Option<GraphStageParameter> {
    match parameter_id {
        "gain" => Some(GraphStageParameter::GainLinear),
        "bias" => Some(GraphStageParameter::BiasAmount),
        "drive" => Some(GraphStageParameter::TanhDrive),
        "balance" => Some(GraphStageParameter::StereoBalance),
        "threshold" => Some(GraphStageParameter::HardClipThreshold),
        "cutoff_hz" => Some(GraphStageParameter::LowPassCutoffHz),
        "feedback" => Some(GraphStageParameter::DelayFeedback),
        _ => None,
    }
}

fn graph_stage_parameter_applies_to(
    parameter: GraphStageParameter,
    stage: &signal_graph::GraphStageSpec,
) -> bool {
    matches!(
        (parameter, stage),
        (
            GraphStageParameter::GainLinear,
            signal_graph::GraphStageSpec::Gain { .. }
        ) | (
            GraphStageParameter::BiasAmount,
            signal_graph::GraphStageSpec::Bias { .. }
        ) | (
            GraphStageParameter::TanhDrive,
            signal_graph::GraphStageSpec::TanhDrive { .. }
        ) | (
            GraphStageParameter::StereoBalance,
            signal_graph::GraphStageSpec::StereoBalance { .. }
        ) | (
            GraphStageParameter::HardClipThreshold,
            signal_graph::GraphStageSpec::HardClip { .. }
        ) | (
            GraphStageParameter::LowPassCutoffHz,
            signal_graph::GraphStageSpec::LowPass { .. }
        ) | (
            GraphStageParameter::DelayFeedback,
            signal_graph::GraphStageSpec::Delay { .. }
        )
    )
}

fn graph_stage_parameter_sort_key(parameter: GraphStageParameter) -> usize {
    match parameter {
        GraphStageParameter::GainLinear => 0,
        GraphStageParameter::BiasAmount => 1,
        GraphStageParameter::TanhDrive => 2,
        GraphStageParameter::StereoBalance => 3,
        GraphStageParameter::HardClipThreshold => 4,
        GraphStageParameter::LowPassCutoffHz => 5,
        GraphStageParameter::DelayFeedback => 6,
    }
}

