    pub fn process_engine_block(
        &mut self,
        processing_epoch: u64,
        block_sequence: u64,
        buffer: AudioBuffer,
    ) -> Result<RuntimeEngineBlockResult, RuntimeError> {
        if !self.control.configured {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime must be configured before processing engine blocks",
            ));
        }
        let block_start = Instant::now();
        let transport = self.applied_transport;
        let context = self.build_engine_execution_context(processing_epoch, block_sequence);
        let (parameter_batch, automation_metrics) =
            self.current_graph_parameter_batch(&context, buffer.frames().0);
        let pending_transition = self
            .timeline
            .consume_pending_transport_transition(block_sequence);
        let mut result = self
            .engine
            .process_block(context, transport, buffer, parameter_batch)?;
        let transport_advance = self.advance_engine_transport(result.output.frames().0 as i64);
        self.timeline.record_engine_block_window(
            transport_advance.start_samples,
            transport_advance.end_samples,
        );
        if let Some(transport) = self.applied_transport {
            self.timeline.update_transport_state(transport);
            if transport_advance.loop_wrapped {
                self.timeline
                    .record_loop_wrap(processing_epoch, block_sequence, transport);
            }
        }
        result.snapshot.transport_epoch = self.timeline.transport_epoch;
        result.snapshot.transport_transition = pending_transition
            .map(|transition| transition.kind)
            .or(transport_advance
                .loop_wrapped
                .then_some(RuntimeTransportTransitionKind::LoopWrapped));
        result.snapshot.transport_block_start_samples = transport_advance.start_samples;
        result.snapshot.transport_block_end_samples = transport_advance.end_samples;
        result.snapshot.transport_loop_wrapped = transport_advance.loop_wrapped;
        self.engine.snapshot.transport_epoch = result.snapshot.transport_epoch;
        self.engine.snapshot.transport_transition = result.snapshot.transport_transition;
        self.engine.snapshot.transport_block_start_samples =
            result.snapshot.transport_block_start_samples;
        self.engine.snapshot.transport_block_end_samples =
            result.snapshot.transport_block_end_samples;
        self.engine.snapshot.transport_loop_wrapped = result.snapshot.transport_loop_wrapped;
        self.metering.capture(
            self.config.sample_rate.0,
            &result.output,
            result.meter_sources.clone(),
        );
        self.automation.record_execution(
            block_sequence,
            result.snapshot.transport_block_start_samples,
            result
                .snapshot
                .last_execution_context
                .map(|context| context.transport_playing),
            result.snapshot.parameter_epoch,
            result.snapshot.parameter_event_count,
            result.snapshot.parameter_ignored_event_count,
            result.snapshot.parameter_sub_block_count,
            result.snapshot.parameter_coalesced_event_count,
            automation_metrics,
        );
        self.recording_capture.record_output_block(&result.output);
        let _ = self.enforce_scheduler_after_engine_block(processing_epoch, block_sequence)?;
        self.refresh_scheduler_topology_summary();
        let execution_time_ns = block_start.elapsed().as_nanos().min(u64::MAX as u128) as u64;
        self.record_block_execution_timing_ns(result.output.frames().0, execution_time_ns);
        result.snapshot = self.engine.snapshot.clone();
        Ok(result)
    }

    pub fn render_clip_processing_buffer(
        &self,
        request: RuntimeClipRenderRequest,
    ) -> Result<RuntimeClipRenderResult, RuntimeError> {
        if request.clip_id.is_empty() {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "clip processing render requests require a non-empty clip id",
            ));
        }
        if request.buffer.sample_rate() != self.config.sample_rate {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!(
                    "clip processing render buffer sample rate {} does not match runtime sample rate {}",
                    request.buffer.sample_rate().0,
                    self.config.sample_rate.0,
                ),
            ));
        }
        self.render_clip_processing_buffer_with_resolved_tempo(
            request,
            &self.current_resolved_tempo(),
        )
    }

    fn should_emit_offline_render_checkpoint(
        rendered_block_count: usize,
        total_block_count: usize,
    ) -> bool {
        if total_block_count == 0 || rendered_block_count == 0 {
            return false;
        }
        if rendered_block_count >= total_block_count {
            return true;
        }
        let stride = total_block_count
            .div_ceil(OFFLINE_RENDER_PROGRESS_CHECKPOINT_TARGET_COUNT)
            .max(1);
        rendered_block_count % stride == 0
    }

    fn offline_render_checkpoint_count(total_block_count: usize) -> usize {
        let rendering_checkpoint_count = (1..=total_block_count)
            .filter(|rendered_block_count| {
                Self::should_emit_offline_render_checkpoint(
                    *rendered_block_count,
                    total_block_count,
                )
            })
            .count();
        1usize
            .saturating_add(rendering_checkpoint_count)
            .saturating_add(2)
    }

    fn offline_render_checkpoint_progress(
        rendered_frame_count: usize,
        total_frame_count: usize,
    ) -> u8 {
        if total_frame_count == 0 {
            return 90;
        }
        let scaled = 10usize
            .saturating_add((rendered_frame_count.saturating_mul(80)) / total_frame_count.max(1));
        scaled.clamp(10, 90) as u8
    }

    fn finalize_offline_render_checkpoints(
        request_id: &str,
        drafts: Vec<OfflineRenderCheckpointDraft>,
    ) -> Vec<RuntimeOfflineRenderCheckpointReceipt> {
        let checkpoint_count = drafts.len();
        drafts
            .into_iter()
            .enumerate()
            .map(
                |(checkpoint_index, draft)| RuntimeOfflineRenderCheckpointReceipt {
                    request_id: request_id.to_string(),
                    stage: draft.stage,
                    checkpoint_index,
                    checkpoint_count,
                    rendered_frame_count: draft.rendered_frame_count,
                    total_frame_count: draft.total_frame_count,
                    rendered_block_count: draft.rendered_block_count,
                    total_block_count: draft.total_block_count,
                    progress_percent: draft.progress_percent,
                    summary: draft.summary,
                },
            )
            .collect()
    }

    fn build_offline_render_execution_session(
        &self,
        request: RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflineRenderExecutionSession, RuntimeError> {
        let preview = RuntimeOfflineRenderContractPreview::from_runtime_state(
            &request,
            &self.execution_topology_summary(),
            &self.clip_processing_pipeline_snapshot(),
            &self.media_pipeline_snapshot(),
            &self.tempo_map_snapshot(),
            &self.marker_analysis_snapshot(),
            &self.plugin_recall_handoff_snapshot(),
        )?;
        let plugin_execution_boundary =
            self.offline_plugin_execution_boundary_from_preview(&request, &preview);
        let delegated_execution_request =
            offline_plugin_delegated_execution_request(&plugin_execution_boundary);
        let input_layout = self.offline_render_input_layout()?;
        let plugin_overrides = self.offline_render_plugin_node_overrides()?;
        let captured_bus_ids = preview
            .stem_targets
            .iter()
            .flat_map(|stem| stem.resolved_output_bus_ids.iter().cloned())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let total_frames = request.duration_samples as usize;
        let total_block_count = total_frames.div_ceil(self.config.graph.block_size.max(1));
        let stem_outputs = preview
            .stem_targets
            .iter()
            .map(|stem| (stem.stem_id.clone(), None))
            .collect::<BTreeMap<String, Option<AudioBuffer>>>();

        Ok(RuntimeOfflineRenderExecutionSession {
            request,
            state: RuntimeOfflineRenderExecutionState::Running,
            preview,
            plugin_execution_boundary,
            delegated_execution_request,
            input_layout,
            plugin_overrides,
            captured_bus_ids,
            decoded_media_assets: BTreeMap::new(),
            main_mix: None,
            stem_outputs,
            total_frames,
            total_block_count,
            rendered_frames: 0,
            block_count: 0,
            checkpoint_count: Self::offline_render_checkpoint_count(total_block_count),
            emitted_checkpoint_count: 0,
            interruption_count: 0,
            interruption_class_override: None,
            last_checkpoint: None,
            last_state_summary: "state=running checkpoints=0".to_string(),
            materialized_result: None,
            finalizing_checkpoint_emitted: false,
        })
    }

    fn emit_offline_render_session_checkpoint(
        session: &mut RuntimeOfflineRenderExecutionSession,
        stage: RuntimeOfflineRenderCheckpointStage,
        rendered_frame_count: usize,
        rendered_block_count: usize,
        progress_percent: u8,
        summary: String,
    ) -> RuntimeOfflineRenderCheckpointReceipt {
        let checkpoint = RuntimeOfflineRenderCheckpointReceipt {
            request_id: session.request.request_id.clone(),
            stage,
            checkpoint_index: session.emitted_checkpoint_count,
            checkpoint_count: session.checkpoint_count,
            rendered_frame_count,
            total_frame_count: session.total_frames,
            rendered_block_count,
            total_block_count: session.total_block_count,
            progress_percent,
            summary,
        };
        session.emitted_checkpoint_count = session.emitted_checkpoint_count.saturating_add(1);
        session.last_checkpoint = Some(checkpoint.clone());
        checkpoint
    }

    fn offline_render_session_state_snapshot(
        session: &RuntimeOfflineRenderExecutionSession,
    ) -> crate::interfaces::RuntimeOfflineRenderSessionStateSnapshot {
        let (report_path, artifact_count, report_materialized) = session
            .materialized_result
            .as_ref()
            .map(|result| {
                (
                    result
                        .manifest
                        .report
                        .as_ref()
                        .map(|receipt| receipt.report_path.clone()),
                    result.manifest.artifact_count,
                    result.manifest.report.is_some(),
                )
            })
            .unwrap_or((None, 0, false));
        crate::interfaces::RuntimeOfflineRenderSessionStateSnapshot {
            request_id: session.request.request_id.clone(),
            state: session.state,
            interruption_class: offline_render_execution_observed_interruption_class(session),
            interruption_rebindable: offline_render_execution_interruption_rebindable(session),
            interruption_count: session.interruption_count,
            emitted_checkpoint_count: session.emitted_checkpoint_count,
            checkpoint_count: session.checkpoint_count,
            rendered_frame_count: session.rendered_frames,
            total_frame_count: session.total_frames,
            rendered_block_count: session.block_count,
            total_block_count: session.total_block_count,
            artifact_root_path: session.request.artifact_root_path.clone(),
            report_path,
            materialized: session.materialized_result.is_some(),
            artifact_count,
            report_materialized,
            active_checkpoint: (session.state != RuntimeOfflineRenderExecutionState::Completed
                && session.state != RuntimeOfflineRenderExecutionState::Cancelled
                && session.state != RuntimeOfflineRenderExecutionState::Failed)
                .then(|| session.last_checkpoint.clone())
                .flatten(),
            last_checkpoint: session.last_checkpoint.clone(),
            summary: session.last_state_summary.clone(),
        }
    }

    fn offline_render_session_snapshot(
        &self,
    ) -> crate::interfaces::RuntimeOfflineRenderSessionSnapshot {
        let active_sessions = self
            .offline_render_executions
            .values()
            .map(Self::offline_render_session_state_snapshot)
            .collect::<Vec<_>>();
        let active_session_count = active_sessions.len();
        let paused_session_count = active_sessions
            .iter()
            .filter(|session| session.state == RuntimeOfflineRenderExecutionState::Paused)
            .count();
        let recoverable_session_count = active_sessions
            .iter()
            .filter(|session| session.state == RuntimeOfflineRenderExecutionState::Recoverable)
            .count();
        let last_session = self.last_offline_render_session_snapshot.borrow().clone();
        let last_cancellation = self
            .last_offline_render_cancellation_receipt
            .borrow()
            .clone();
        let last_purge = self.last_offline_render_purge_receipt.borrow().clone();
        let last_session_present = last_session.is_some();
        let last_cancellation_present = last_cancellation.is_some();
        let last_purge_present = last_purge.is_some();
        crate::interfaces::RuntimeOfflineRenderSessionSnapshot {
            active_session_count,
            paused_session_count,
            recoverable_session_count,
            active_sessions,
            last_session,
            last_cancellation,
            last_purge,
            summary: format!(
                "active_sessions={} paused_sessions={} recoverable_sessions={} last_session={} last_cancellation={} last_purge={}",
                active_session_count,
                paused_session_count,
                recoverable_session_count,
                last_session_present,
                last_cancellation_present,
                last_purge_present,
            ),
        }
    }

    fn record_last_offline_render_session_snapshot(
        &self,
        snapshot: crate::interfaces::RuntimeOfflineRenderSessionStateSnapshot,
    ) {
        self.last_offline_render_session_snapshot
            .replace(Some(snapshot));
    }

    fn mark_offline_render_sessions_restartable(&mut self, reason: &str) {
        let summary_snapshot = self
            .offline_render_executions
            .values_mut()
            .map(|session| {
                session.state = RuntimeOfflineRenderExecutionState::Recoverable;
                session.interruption_count = session.interruption_count.saturating_add(1);
                session.interruption_class_override = Some(RuntimeInterruptionClass::Restartable);
                session.last_state_summary = format!(
                    "request={} state=recoverable interruption=restartable checkpoints={}/{} interruptions={} reason={}",
                    session.request.request_id,
                    session.emitted_checkpoint_count,
                    session.checkpoint_count,
                    session.interruption_count,
                    reason,
                );
                Self::offline_render_session_state_snapshot(session)
            })
            .last();
        if let Some(snapshot) = summary_snapshot {
            self.record_last_offline_render_session_snapshot(snapshot);
        }
    }

    fn record_terminal_offline_render_session_failure(
        &self,
        session: &mut RuntimeOfflineRenderExecutionSession,
        stage: RuntimeOfflineRenderCheckpointStage,
        error: &RuntimeError,
    ) {
        session.state = RuntimeOfflineRenderExecutionState::Failed;
        session.interruption_count = session.interruption_count.saturating_add(1);
        session.interruption_class_override = Some(RuntimeInterruptionClass::Terminal);
        session.last_state_summary = format!(
            "request={} state=failed stage={:?} checkpoints={}/{} interruptions={} error={:?}",
            session.request.request_id,
            stage,
            session.emitted_checkpoint_count,
            session.checkpoint_count,
            session.interruption_count,
            error,
        );
        self.record_last_offline_render_session_snapshot(
            Self::offline_render_session_state_snapshot(session),
        );
    }

    fn offline_render_execution_status_receipt(
        session: &RuntimeOfflineRenderExecutionSession,
    ) -> RuntimeOfflineRenderExecutionProgressReceipt {
        RuntimeOfflineRenderExecutionProgressReceipt {
            request_id: session.request.request_id.clone(),
            state: session.state,
            interruption_class: offline_render_execution_observed_interruption_class(session),
            interruption_rebindable: offline_render_execution_interruption_rebindable(session),
            emitted_checkpoint_count: session.emitted_checkpoint_count,
            checkpoint_count: session.checkpoint_count,
            checkpoint: None,
            result: None,
            summary: session.last_state_summary.clone(),
        }
    }

    fn materialize_offline_render_session_outputs(
        &self,
        session: &mut RuntimeOfflineRenderExecutionSession,
    ) -> Result<RuntimeOfflineRenderResult, RuntimeError> {
        let request = &session.request;
        let preview = &session.preview;
        let total_frames = session.total_frames;
        let stems = preview
            .stem_targets
            .iter()
            .map(|stem_preview| {
                let output = session
                    .stem_outputs
                    .remove(&stem_preview.stem_id)
                    .and_then(|buffer| buffer)
                    .unwrap_or_else(|| {
                        AudioBuffer::new(
                            self.config.sample_rate,
                            ChannelLayout::Stereo,
                            FrameCount(total_frames),
                        )
                    });
                RuntimeOfflineRenderStemResult {
                    stem_id: stem_preview.stem_id.clone(),
                    target_kind: stem_preview.target_kind,
                    target_id: stem_preview.target_id.clone(),
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "stem={} target={:?}/{:?} frames={} peak={:.3} rms={:.3}",
                        stem_preview.stem_id,
                        stem_preview.target_kind,
                        stem_preview.target_id,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                }
            })
            .collect::<Vec<_>>();

        let freeze_artifacts = preview
            .freeze_artifacts
            .iter()
            .map(|artifact_preview| {
                let source_output = stems
                    .iter()
                    .find(|stem| stem.stem_id == artifact_preview.source_stem_id)
                    .map(|stem| stem.output.clone())
                    .or_else(|| session.main_mix.clone())
                    .ok_or_else(|| {
                        RuntimeError::new(
                            RuntimeErrorKind::InvalidState,
                            format!(
                                "offline freeze artifact `{}` has no rendered source output",
                                artifact_preview.artifact_id
                            ),
                        )
                    })?;
                Ok(RuntimeOfflineFreezeArtifactResult {
                    artifact_id: artifact_preview.artifact_id.clone(),
                    source_stem_id: artifact_preview.source_stem_id.clone(),
                    recall_stage_count: artifact_preview.recall_stage_count,
                    recall_stage_ids: artifact_preview.recall_stage_ids.clone(),
                    recall_states: artifact_preview.recall_states.clone(),
                    peak_level: peak_abs(source_output.samples()),
                    rms_level: rms(source_output.samples()),
                    summary: format!(
                        "artifact={} source_stem={} recall_stages={} frames={} peak={:.3} rms={:.3}",
                        artifact_preview.artifact_id,
                        artifact_preview.source_stem_id,
                        artifact_preview.recall_stage_count,
                        source_output.frames().0,
                        peak_abs(source_output.samples()),
                        rms(source_output.samples()),
                    ),
                    output: source_output,
                })
            })
            .collect::<Result<Vec<_>, RuntimeError>>()?;

        let export_sample_rate = SampleRate(request.export_sample_rate_hz);
        let main_mix = session
            .main_mix
            .take()
            .map(|buffer| resample_audio_buffer_linear(&buffer, export_sample_rate));
        let stems = stems
            .into_iter()
            .map(|stem| {
                let output = resample_audio_buffer_linear(&stem.output, export_sample_rate);
                RuntimeOfflineRenderStemResult {
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "stem={} target={:?}/{:?} frames={} peak={:.3} rms={:.3}",
                        stem.stem_id,
                        stem.target_kind,
                        stem.target_id,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                    ..stem
                }
            })
            .collect::<Vec<_>>();
        let freeze_artifacts = freeze_artifacts
            .into_iter()
            .map(|artifact| {
                let output = resample_audio_buffer_linear(&artifact.output, export_sample_rate);
                RuntimeOfflineFreezeArtifactResult {
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "artifact={} source_stem={} recall_stages={} frames={} peak={:.3} rms={:.3}",
                        artifact.artifact_id,
                        artifact.source_stem_id,
                        artifact.recall_stage_count,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                    ..artifact
                }
            })
            .collect::<Vec<_>>();

        let main_mix_peak_level = main_mix.as_ref().map(|buffer| peak_abs(buffer.samples()));
        let main_mix_rms_level = main_mix.as_ref().map(|buffer| rms(buffer.samples()));
        let rendered_frame_count = main_mix
            .as_ref()
            .map(|buffer| buffer.frames().0)
            .or_else(|| stems.first().map(|stem| stem.output.frames().0))
            .or_else(|| {
                freeze_artifacts
                    .first()
                    .map(|artifact| artifact.output.frames().0)
            })
            .unwrap_or(0);

        Ok(RuntimeOfflineRenderResult {
            request_id: request.request_id.clone(),
            runtime_frame_count: session.rendered_frames,
            rendered_frame_count,
            block_count: session.block_count,
            export_sample_rate_hz: request.export_sample_rate_hz,
            main_mix,
            main_mix_peak_level,
            main_mix_rms_level,
            stems,
            freeze_artifacts,
            manifest: offline_render_manifest(
                &request.request_id,
                request.artifact_root_path.as_deref(),
                Vec::new(),
                None,
                session.delegated_execution_request.clone(),
                None,
            ),
            plugin_execution_boundary: session.plugin_execution_boundary.clone(),
            contract_preview: preview.clone(),
            summary: format!(
                "request={} runtime_frames={} rendered_frames={} blocks={} main_mix={} stems={} freeze_artifacts={}",
                request.request_id,
                session.rendered_frames,
                rendered_frame_count,
                session.block_count,
                request.include_main_mix,
                preview.stem_count,
                preview.freeze_artifact_count,
            ),
        })
    }

    fn render_offline_internal(
        &self,
        request: RuntimeOfflineRenderRequest,
        collect_checkpoints: bool,
    ) -> Result<RuntimeOfflineRenderExecutionReceipt, RuntimeError> {
        let preview = RuntimeOfflineRenderContractPreview::from_runtime_state(
            &request,
            &self.execution_topology_summary(),
            &self.clip_processing_pipeline_snapshot(),
            &self.media_pipeline_snapshot(),
            &self.tempo_map_snapshot(),
            &self.marker_analysis_snapshot(),
            &self.plugin_recall_handoff_snapshot(),
        )?;
        let plugin_execution_boundary =
            self.offline_plugin_execution_boundary_from_preview(&request, &preview);
        let delegated_execution_request =
            offline_plugin_delegated_execution_request(&plugin_execution_boundary);
        let input_layout = self.offline_render_input_layout()?;
        let plugin_overrides = self.offline_render_plugin_node_overrides()?;
        let captured_bus_ids = preview
            .stem_targets
            .iter()
            .flat_map(|stem| stem.resolved_output_bus_ids.iter().cloned())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let mut decoded_media_assets = BTreeMap::new();
        let mut main_mix = None;
        let mut stem_outputs = preview
            .stem_targets
            .iter()
            .map(|stem| (stem.stem_id.clone(), None))
            .collect::<BTreeMap<String, Option<AudioBuffer>>>();
        let total_frames = request.duration_samples as usize;
        let block_size = self.config.graph.block_size.max(1);
        let total_block_count = total_frames.div_ceil(block_size);
        let mut rendered_frames = 0usize;
        let mut block_count = 0usize;
        let mut checkpoint_drafts = Vec::new();

        if collect_checkpoints {
            checkpoint_drafts.push(OfflineRenderCheckpointDraft {
                stage: RuntimeOfflineRenderCheckpointStage::PreparingInput,
                rendered_frame_count: 0,
                total_frame_count: total_frames,
                rendered_block_count: 0,
                total_block_count,
                progress_percent: 5,
                summary: format!(
                    "request={} stage=preparing-input total_frames={} blocks={} stems={} freeze_artifacts={}",
                    request.request_id, total_frames, total_block_count, preview.stem_count, preview.freeze_artifact_count
                ),
            });
        }

        while rendered_frames < total_frames {
            let block_frames = (total_frames - rendered_frames).min(block_size);
            let block_start_samples = request
                .timeline_start_samples
                .saturating_add(rendered_frames as i64);
            let resolved_tempo = self.resolved_tempo_for_timeline_position(block_start_samples);
            let context =
                self.offline_render_context((block_count + 1) as u64, block_start_samples);
            let (parameter_batch, _) = self.graph_parameter_batch_for_transport(
                &context,
                block_frames,
                Some(transport_projection_from_context(&context)),
            );
            let input = self.offline_render_input_block(
                block_start_samples,
                block_frames,
                input_layout,
                &resolved_tempo,
                &mut decoded_media_assets,
            )?;
            let (output, captured_buses) = self.engine.render_offline_block(
                context,
                input,
                parameter_batch,
                &plugin_overrides,
                &captured_bus_ids,
            )?;
            if request.include_main_mix {
                write_offline_render_block(&mut main_mix, total_frames, rendered_frames, &output);
            }

            for stem_preview in &preview.stem_targets {
                let block_output =
                    self.offline_render_stem_block(stem_preview, &output, &captured_buses)?;
                let stem_buffer = stem_outputs
                    .get_mut(&stem_preview.stem_id)
                    .expect("stem output slot should exist");
                write_offline_render_block(
                    stem_buffer,
                    total_frames,
                    rendered_frames,
                    &block_output,
                );
            }

            rendered_frames = rendered_frames.saturating_add(block_frames);
            block_count = block_count.saturating_add(1);
            if collect_checkpoints
                && Self::should_emit_offline_render_checkpoint(block_count, total_block_count)
            {
                checkpoint_drafts.push(OfflineRenderCheckpointDraft {
                    stage: RuntimeOfflineRenderCheckpointStage::RenderingGraph,
                    rendered_frame_count: rendered_frames,
                    total_frame_count: total_frames,
                    rendered_block_count: block_count,
                    total_block_count,
                    progress_percent: Self::offline_render_checkpoint_progress(
                        rendered_frames,
                        total_frames,
                    ),
                    summary: format!(
                        "request={} stage=rendering-graph blocks={}/{} frames={}/{}",
                        request.request_id,
                        block_count,
                        total_block_count,
                        rendered_frames,
                        total_frames,
                    ),
                });
            }
        }

        let stems = preview
            .stem_targets
            .iter()
            .map(|stem_preview| {
                let output = stem_outputs
                    .remove(&stem_preview.stem_id)
                    .and_then(|buffer| buffer)
                    .unwrap_or_else(|| {
                        AudioBuffer::new(
                            self.config.sample_rate,
                            ChannelLayout::Stereo,
                            FrameCount(total_frames),
                        )
                    });
                RuntimeOfflineRenderStemResult {
                    stem_id: stem_preview.stem_id.clone(),
                    target_kind: stem_preview.target_kind,
                    target_id: stem_preview.target_id.clone(),
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "stem={} target={:?}/{:?} frames={} peak={:.3} rms={:.3}",
                        stem_preview.stem_id,
                        stem_preview.target_kind,
                        stem_preview.target_id,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                }
            })
            .collect::<Vec<_>>();

        let freeze_artifacts = preview
            .freeze_artifacts
            .iter()
            .map(|artifact_preview| {
                let source_output = stems
                    .iter()
                    .find(|stem| stem.stem_id == artifact_preview.source_stem_id)
                    .map(|stem| stem.output.clone())
                    .or_else(|| main_mix.clone())
                    .ok_or_else(|| {
                        RuntimeError::new(
                            RuntimeErrorKind::InvalidState,
                            format!(
                                "offline freeze artifact `{}` has no rendered source output",
                                artifact_preview.artifact_id
                            ),
                        )
                    })?;
                Ok(RuntimeOfflineFreezeArtifactResult {
                    artifact_id: artifact_preview.artifact_id.clone(),
                    source_stem_id: artifact_preview.source_stem_id.clone(),
                    recall_stage_count: artifact_preview.recall_stage_count,
                    recall_stage_ids: artifact_preview.recall_stage_ids.clone(),
                    recall_states: artifact_preview.recall_states.clone(),
                    peak_level: peak_abs(source_output.samples()),
                    rms_level: rms(source_output.samples()),
                    summary: format!(
                        "artifact={} source_stem={} recall_stages={} frames={} peak={:.3} rms={:.3}",
                        artifact_preview.artifact_id,
                        artifact_preview.source_stem_id,
                        artifact_preview.recall_stage_count,
                        source_output.frames().0,
                        peak_abs(source_output.samples()),
                        rms(source_output.samples()),
                    ),
                    output: source_output,
                })
            })
            .collect::<Result<Vec<_>, RuntimeError>>()?;

        let export_sample_rate = SampleRate(request.export_sample_rate_hz);
        let main_mix =
            main_mix.map(|buffer| resample_audio_buffer_linear(&buffer, export_sample_rate));
        let stems = stems
            .into_iter()
            .map(|stem| {
                let output = resample_audio_buffer_linear(&stem.output, export_sample_rate);
                RuntimeOfflineRenderStemResult {
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "stem={} target={:?}/{:?} frames={} peak={:.3} rms={:.3}",
                        stem.stem_id,
                        stem.target_kind,
                        stem.target_id,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                    ..stem
                }
            })
            .collect::<Vec<_>>();
        let freeze_artifacts = freeze_artifacts
            .into_iter()
            .map(|artifact| {
                let output = resample_audio_buffer_linear(&artifact.output, export_sample_rate);
                RuntimeOfflineFreezeArtifactResult {
                    peak_level: peak_abs(output.samples()),
                    rms_level: rms(output.samples()),
                    summary: format!(
                        "artifact={} source_stem={} recall_stages={} frames={} peak={:.3} rms={:.3}",
                        artifact.artifact_id,
                        artifact.source_stem_id,
                        artifact.recall_stage_count,
                        output.frames().0,
                        peak_abs(output.samples()),
                        rms(output.samples()),
                    ),
                    output,
                    ..artifact
                }
            })
            .collect::<Vec<_>>();

        let main_mix_peak_level = main_mix.as_ref().map(|buffer| peak_abs(buffer.samples()));
        let main_mix_rms_level = main_mix.as_ref().map(|buffer| rms(buffer.samples()));
        let rendered_frame_count = main_mix
            .as_ref()
            .map(|buffer| buffer.frames().0)
            .or_else(|| stems.first().map(|stem| stem.output.frames().0))
            .or_else(|| {
                freeze_artifacts
                    .first()
                    .map(|artifact| artifact.output.frames().0)
            })
            .unwrap_or(0);
        if collect_checkpoints {
            checkpoint_drafts.push(OfflineRenderCheckpointDraft {
                stage: RuntimeOfflineRenderCheckpointStage::MaterializingOutputs,
                rendered_frame_count,
                total_frame_count: total_frames,
                rendered_block_count: block_count,
                total_block_count,
                progress_percent: 95,
                summary: format!(
                    "request={} stage=materializing-outputs main_mix={} stems={} freeze_artifacts={}",
                    request.request_id,
                    request.include_main_mix,
                    preview.stem_count,
                    preview.freeze_artifact_count,
                ),
            });
        }
        let mut result = RuntimeOfflineRenderResult {
            request_id: request.request_id.clone(),
            runtime_frame_count: rendered_frames,
            rendered_frame_count,
            block_count,
            export_sample_rate_hz: request.export_sample_rate_hz,
            main_mix,
            main_mix_peak_level,
            main_mix_rms_level,
            stems,
            freeze_artifacts,
            manifest: offline_render_manifest(
                &request.request_id,
                request.artifact_root_path.as_deref(),
                Vec::new(),
                None,
                delegated_execution_request.clone(),
                None,
            ),
            plugin_execution_boundary,
            contract_preview: preview.clone(),
            summary: format!(
                "request={} runtime_frames={} rendered_frames={} blocks={} main_mix={} stems={} freeze_artifacts={}",
                request.request_id,
                rendered_frames,
                rendered_frame_count,
                block_count,
                request.include_main_mix,
                preview.stem_count,
                preview.freeze_artifact_count,
            ),
        };
        result.manifest = materialize_offline_render_delivery(&result)?;
        if collect_checkpoints {
            checkpoint_drafts.push(OfflineRenderCheckpointDraft {
                stage: RuntimeOfflineRenderCheckpointStage::FinalizingArtifacts,
                rendered_frame_count,
                total_frame_count: total_frames,
                rendered_block_count: block_count,
                total_block_count,
                progress_percent: 99,
                summary: format!(
                    "request={} stage=finalizing-artifacts artifacts={} report={}",
                    request.request_id,
                    result.manifest.artifact_count,
                    result
                        .manifest
                        .report
                        .as_ref()
                        .map(|report| report.report_path.as_str())
                        .unwrap_or("none"),
                ),
            });
        }
        let checkpoints = if collect_checkpoints {
            Self::finalize_offline_render_checkpoints(&request.request_id, checkpoint_drafts)
        } else {
            Vec::new()
        };
        let checkpoint_count = checkpoints.len();
        Ok(RuntimeOfflineRenderExecutionReceipt {
            request_id: request.request_id.clone(),
            checkpoint_count,
            checkpoints,
            result,
            summary: format!(
                "request={} checkpoints={} runtime_frames={} rendered_frames={} blocks={}",
                request.request_id,
                checkpoint_count,
                rendered_frames,
                rendered_frame_count,
                block_count,
            ),
        })
    }

    pub fn render_offline(
        &self,
        request: RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflineRenderResult, RuntimeError> {
        self.render_offline_internal(request, false)
            .map(|execution| execution.result)
    }

    pub fn render_offline_with_checkpoints(
        &self,
        request: RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflineRenderExecutionReceipt, RuntimeError> {
        self.render_offline_internal(request, true)
    }

    pub fn begin_offline_render_execution(
        &mut self,
        request: RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflineRenderExecutionProgressReceipt, RuntimeError> {
        if self
            .offline_render_executions
            .contains_key(request.request_id.as_str())
        {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                format!(
                    "offline render execution `{}` is already active",
                    request.request_id
                ),
            ));
        }
        let mut session = self.build_offline_render_execution_session(request)?;
        let preparing_summary = format!(
            "request={} stage=preparing-input total_frames={} blocks={} stems={} freeze_artifacts={}",
            session.request.request_id,
            session.total_frames,
            session.total_block_count,
            session.preview.stem_count,
            session.preview.freeze_artifact_count,
        );
        let checkpoint = Self::emit_offline_render_session_checkpoint(
            &mut session,
            RuntimeOfflineRenderCheckpointStage::PreparingInput,
            0,
            0,
            5,
            preparing_summary,
        );
        let request_id = session.request.request_id.clone();
        let checkpoint_count = session.checkpoint_count;
        let emitted_checkpoint_count = session.emitted_checkpoint_count;
        session.last_state_summary = format!(
            "request={} state=running checkpoints={}/{} stage=preparing-input",
            request_id, emitted_checkpoint_count, checkpoint_count
        );
        self.offline_render_executions
            .insert(request_id.clone(), session);
        let (interruption_rebindable, session_snapshot) = self
            .offline_render_executions
            .get(request_id.as_str())
            .map(|session| {
                (
                    offline_render_execution_interruption_rebindable(session),
                    Self::offline_render_session_state_snapshot(session),
                )
            })
            .unwrap_or((
                false,
                crate::interfaces::RuntimeOfflineRenderSessionStateSnapshot {
                    request_id: request_id.clone(),
                    state: RuntimeOfflineRenderExecutionState::Running,
                    interruption_class: RuntimeInterruptionClass::Steady,
                    interruption_rebindable: false,
                    interruption_count: 0,
                    emitted_checkpoint_count,
                    checkpoint_count,
                    rendered_frame_count: 0,
                    total_frame_count: 0,
                    rendered_block_count: 0,
                    total_block_count: 0,
                    artifact_root_path: None,
                    report_path: None,
                    materialized: false,
                    artifact_count: 0,
                    report_materialized: false,
                    active_checkpoint: None,
                    last_checkpoint: None,
                    summary: "state=running".into(),
                },
            ));
        self.record_last_offline_render_session_snapshot(session_snapshot);
        Ok(RuntimeOfflineRenderExecutionProgressReceipt {
            request_id: request_id.clone(),
            state: RuntimeOfflineRenderExecutionState::Running,
            interruption_class: offline_render_execution_interruption_class(
                RuntimeOfflineRenderExecutionState::Running,
            ),
            interruption_rebindable,
            emitted_checkpoint_count,
            checkpoint_count,
            checkpoint: Some(checkpoint),
            result: None,
            summary: format!(
                "request={} state=running checkpoints={}/{} stage=preparing-input",
                request_id, emitted_checkpoint_count, checkpoint_count
            ),
        })
    }

    pub fn pause_offline_render_execution(
        &mut self,
        request_id: &str,
    ) -> Result<RuntimeOfflineRenderExecutionProgressReceipt, RuntimeError> {
        let (snapshot, receipt) = {
            let session = self
                .offline_render_executions
                .get_mut(request_id)
                .ok_or_else(|| {
                    RuntimeError::new(
                        RuntimeErrorKind::InvalidRequest,
                        format!("offline render execution `{request_id}` is not active"),
                    )
                })?;
            session.state = RuntimeOfflineRenderExecutionState::Paused;
            session.interruption_class_override = None;
            session.last_state_summary = format!(
                "request={} state=paused checkpoints={}/{} rendered_frames={} rendered_blocks={}",
                request_id,
                session.emitted_checkpoint_count,
                session.checkpoint_count,
                session.rendered_frames,
                session.block_count
            );
            (
                Self::offline_render_session_state_snapshot(session),
                Self::offline_render_execution_status_receipt(session),
            )
        };
        self.record_last_offline_render_session_snapshot(snapshot);
        Ok(receipt)
    }

    pub fn resume_offline_render_execution(
        &mut self,
        request_id: &str,
    ) -> Result<RuntimeOfflineRenderExecutionProgressReceipt, RuntimeError> {
        let (snapshot, receipt) = {
            let session = self
                .offline_render_executions
                .get_mut(request_id)
                .ok_or_else(|| {
                    RuntimeError::new(
                        RuntimeErrorKind::InvalidRequest,
                        format!("offline render execution `{request_id}` is not active"),
                    )
                })?;
            session.state = RuntimeOfflineRenderExecutionState::Running;
            session.interruption_class_override = None;
            session.last_state_summary = format!(
                "request={} state=running checkpoints={}/{} interruption_count={}",
                request_id,
                session.emitted_checkpoint_count,
                session.checkpoint_count,
                session.interruption_count
            );
            (
                Self::offline_render_session_state_snapshot(session),
                Self::offline_render_execution_status_receipt(session),
            )
        };
        self.record_last_offline_render_session_snapshot(snapshot);
        Ok(receipt)
    }

    pub fn interrupt_offline_render_execution(
        &mut self,
        request_id: &str,
        reason: String,
    ) -> Result<RuntimeOfflineRenderExecutionProgressReceipt, RuntimeError> {
        let reason = reason.trim().to_string();
        if reason.is_empty() {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "offline render execution interruption reason cannot be empty",
            ));
        }
        let (snapshot, receipt) = {
            let session = self
                .offline_render_executions
                .get_mut(request_id)
                .ok_or_else(|| {
                    RuntimeError::new(
                        RuntimeErrorKind::InvalidRequest,
                        format!("offline render execution `{request_id}` is not active"),
                    )
                })?;
            session.state = RuntimeOfflineRenderExecutionState::Recoverable;
            session.interruption_count = session.interruption_count.saturating_add(1);
            session.interruption_class_override = None;
            session.last_state_summary = format!(
                "request={} state=recoverable checkpoints={}/{} interruptions={} reason={}",
                request_id,
                session.emitted_checkpoint_count,
                session.checkpoint_count,
                session.interruption_count,
                reason
            );
            (
                Self::offline_render_session_state_snapshot(session),
                Self::offline_render_execution_status_receipt(session),
            )
        };
        self.record_last_offline_render_session_snapshot(snapshot);
        Ok(receipt)
    }

    pub fn advance_offline_render_execution(
        &mut self,
        request_id: &str,
    ) -> Result<RuntimeOfflineRenderExecutionProgressReceipt, RuntimeError> {
        let mut session = self
            .offline_render_executions
            .remove(request_id)
            .ok_or_else(|| {
                RuntimeError::new(
                    RuntimeErrorKind::InvalidRequest,
                    format!("offline render execution `{request_id}` is not active"),
                )
            })?;

        if session.state != RuntimeOfflineRenderExecutionState::Running {
            let receipt = Self::offline_render_execution_status_receipt(&session);
            self.record_last_offline_render_session_snapshot(
                Self::offline_render_session_state_snapshot(&session),
            );
            self.offline_render_executions
                .insert(request_id.to_string(), session);
            return Ok(receipt);
        }

        if session.rendered_frames < session.total_frames {
            while session.rendered_frames < session.total_frames {
                let block_frames = (session.total_frames - session.rendered_frames)
                    .min(self.config.graph.block_size.max(1));
                let block_start_samples = session
                    .request
                    .timeline_start_samples
                    .saturating_add(session.rendered_frames as i64);
                let resolved_tempo = self.resolved_tempo_for_timeline_position(block_start_samples);
                let context = self
                    .offline_render_context((session.block_count + 1) as u64, block_start_samples);
                let (parameter_batch, _) = self.graph_parameter_batch_for_transport(
                    &context,
                    block_frames,
                    Some(transport_projection_from_context(&context)),
                );
                let input = self.offline_render_input_block(
                    block_start_samples,
                    block_frames,
                    session.input_layout,
                    &resolved_tempo,
                    &mut session.decoded_media_assets,
                )?;
                let (output, captured_buses) = self.engine.render_offline_block(
                    context,
                    input,
                    parameter_batch,
                    &session.plugin_overrides,
                    &session.captured_bus_ids,
                )?;
                if session.request.include_main_mix {
                    write_offline_render_block(
                        &mut session.main_mix,
                        session.total_frames,
                        session.rendered_frames,
                        &output,
                    );
                }

                for stem_preview in &session.preview.stem_targets {
                    let block_output =
                        self.offline_render_stem_block(stem_preview, &output, &captured_buses)?;
                    let stem_buffer = session
                        .stem_outputs
                        .get_mut(&stem_preview.stem_id)
                        .expect("stem output slot should exist");
                    write_offline_render_block(
                        stem_buffer,
                        session.total_frames,
                        session.rendered_frames,
                        &block_output,
                    );
                }

                session.rendered_frames = session.rendered_frames.saturating_add(block_frames);
                session.block_count = session.block_count.saturating_add(1);
                if Self::should_emit_offline_render_checkpoint(
                    session.block_count,
                    session.total_block_count,
                ) {
                    let progress_percent = Self::offline_render_checkpoint_progress(
                        session.rendered_frames,
                        session.total_frames,
                    );
                    let rendered_frames = session.rendered_frames;
                    let block_count = session.block_count;
                    let total_block_count = session.total_block_count;
                    let total_frames = session.total_frames;
                    let rendering_summary = format!(
                        "request={} stage=rendering-graph blocks={}/{} frames={}/{}",
                        session.request.request_id,
                        block_count,
                        total_block_count,
                        rendered_frames,
                        total_frames,
                    );
                    let checkpoint = Self::emit_offline_render_session_checkpoint(
                        &mut session,
                        RuntimeOfflineRenderCheckpointStage::RenderingGraph,
                        rendered_frames,
                        block_count,
                        progress_percent,
                        rendering_summary,
                    );
                    let emitted_checkpoint_count = session.emitted_checkpoint_count;
                    let checkpoint_count = session.checkpoint_count;
                    let summary = format!(
                        "request={} state=running checkpoints={}/{} stage=rendering-graph",
                        session.request.request_id, emitted_checkpoint_count, checkpoint_count
                    );
                    session.last_state_summary = summary.clone();
                    self.record_last_offline_render_session_snapshot(
                        Self::offline_render_session_state_snapshot(&session),
                    );
                    self.offline_render_executions
                        .insert(request_id.to_string(), session);
                    return Ok(RuntimeOfflineRenderExecutionProgressReceipt {
                        request_id: request_id.to_string(),
                        state: RuntimeOfflineRenderExecutionState::Running,
                        interruption_class: offline_render_execution_interruption_class(
                            RuntimeOfflineRenderExecutionState::Running,
                        ),
                        interruption_rebindable: false,
                        emitted_checkpoint_count,
                        checkpoint_count,
                        checkpoint: Some(checkpoint),
                        result: None,
                        summary,
                    });
                }
            }
        }

        if session.materialized_result.is_none() {
            let result = match self.materialize_offline_render_session_outputs(&mut session) {
                Ok(result) => result,
                Err(error) => {
                    self.record_terminal_offline_render_session_failure(
                        &mut session,
                        RuntimeOfflineRenderCheckpointStage::MaterializingOutputs,
                        &error,
                    );
                    return Err(error);
                }
            };
            session.materialized_result = Some(result);
            let rendered_frames = session.rendered_frames;
            let block_count = session.block_count;
            let materializing_summary = format!(
                "request={} stage=materializing-outputs main_mix={} stems={} freeze_artifacts={}",
                session.request.request_id,
                session.request.include_main_mix,
                session.preview.stem_count,
                session.preview.freeze_artifact_count,
            );
            let checkpoint = Self::emit_offline_render_session_checkpoint(
                &mut session,
                RuntimeOfflineRenderCheckpointStage::MaterializingOutputs,
                rendered_frames,
                block_count,
                95,
                materializing_summary,
            );
            let emitted_checkpoint_count = session.emitted_checkpoint_count;
            let checkpoint_count = session.checkpoint_count;
            let summary = format!(
                "request={} state=running checkpoints={}/{} stage=materializing-outputs",
                request_id, emitted_checkpoint_count, checkpoint_count
            );
            session.last_state_summary = summary.clone();
            self.record_last_offline_render_session_snapshot(
                Self::offline_render_session_state_snapshot(&session),
            );
            self.offline_render_executions
                .insert(request_id.to_string(), session);
            return Ok(RuntimeOfflineRenderExecutionProgressReceipt {
                request_id: request_id.to_string(),
                state: RuntimeOfflineRenderExecutionState::Running,
                interruption_class: offline_render_execution_interruption_class(
                    RuntimeOfflineRenderExecutionState::Running,
                ),
                interruption_rebindable: false,
                emitted_checkpoint_count,
                checkpoint_count,
                checkpoint: Some(checkpoint),
                result: None,
                summary,
            });
        }

        if !session.finalizing_checkpoint_emitted {
            session.finalizing_checkpoint_emitted = true;
            let rendered_frames = session.rendered_frames;
            let block_count = session.block_count;
            let finalizing_summary = format!(
                "request={} stage=finalizing-artifacts artifact_root={} pending_delivery=true",
                session.request.request_id,
                session
                    .request
                    .artifact_root_path
                    .as_deref()
                    .unwrap_or("none"),
            );
            let checkpoint = Self::emit_offline_render_session_checkpoint(
                &mut session,
                RuntimeOfflineRenderCheckpointStage::FinalizingArtifacts,
                rendered_frames,
                block_count,
                99,
                finalizing_summary,
            );
            let emitted_checkpoint_count = session.emitted_checkpoint_count;
            let checkpoint_count = session.checkpoint_count;
            let summary = format!(
                "request={} state=running checkpoints={}/{} stage=finalizing-artifacts",
                request_id, emitted_checkpoint_count, checkpoint_count
            );
            session.last_state_summary = summary.clone();
            self.record_last_offline_render_session_snapshot(
                Self::offline_render_session_state_snapshot(&session),
            );
            self.offline_render_executions
                .insert(request_id.to_string(), session);
            return Ok(RuntimeOfflineRenderExecutionProgressReceipt {
                request_id: request_id.to_string(),
                state: RuntimeOfflineRenderExecutionState::Running,
                interruption_class: offline_render_execution_interruption_class(
                    RuntimeOfflineRenderExecutionState::Running,
                ),
                interruption_rebindable: false,
                emitted_checkpoint_count,
                checkpoint_count,
                checkpoint: Some(checkpoint),
                result: None,
                summary,
            });
        }

        let mut result = session.materialized_result.take().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                format!(
                    "offline render execution `{request_id}` has no materialized result to finalize"
                ),
            )
        })?;
        result.manifest = match materialize_offline_render_delivery(&result) {
            Ok(manifest) => manifest,
            Err(error) => {
                self.record_terminal_offline_render_session_failure(
                    &mut session,
                    RuntimeOfflineRenderCheckpointStage::FinalizingArtifacts,
                    &error,
                );
                return Err(error);
            }
        };
        session.state = RuntimeOfflineRenderExecutionState::Completed;
        session.interruption_class_override = None;
        session.last_state_summary = format!(
            "request={} state=completed checkpoints={}/{} artifacts={} report={}",
            request_id,
            session.emitted_checkpoint_count,
            session.checkpoint_count,
            result.manifest.artifact_count,
            result.manifest.report.is_some(),
        );
        session.materialized_result = Some(result.clone());
        self.record_last_offline_render_session_snapshot(
            Self::offline_render_session_state_snapshot(&session),
        );
        Ok(RuntimeOfflineRenderExecutionProgressReceipt {
            request_id: request_id.to_string(),
            state: RuntimeOfflineRenderExecutionState::Completed,
            interruption_class: offline_render_execution_interruption_class(
                RuntimeOfflineRenderExecutionState::Completed,
            ),
            interruption_rebindable: false,
            emitted_checkpoint_count: session.emitted_checkpoint_count,
            checkpoint_count: session.checkpoint_count,
            checkpoint: None,
            result: Some(result),
            summary: format!(
                "request={} state=completed checkpoints={}/{}",
                request_id, session.emitted_checkpoint_count, session.checkpoint_count
            ),
        })
    }

    pub fn cancel_offline_render_execution(
        &mut self,
        request_id: &str,
    ) -> Result<RuntimeOfflineRenderExecutionCancellationReceipt, RuntimeError> {
        let session = self
            .offline_render_executions
            .remove(request_id)
            .ok_or_else(|| {
                RuntimeError::new(
                    RuntimeErrorKind::InvalidRequest,
                    format!("offline render execution `{request_id}` is not active"),
                )
            })?;
        let receipt = RuntimeOfflineRenderExecutionCancellationReceipt {
            request_id: request_id.to_string(),
            cancelled_after_checkpoint_count: session.emitted_checkpoint_count,
            checkpoint_count: session.checkpoint_count,
            rendered_frame_count: session.rendered_frames,
            rendered_block_count: session.block_count,
            summary: format!(
                "request={} state=cancelled checkpoints={}/{} rendered_frames={} rendered_blocks={}",
                request_id,
                session.emitted_checkpoint_count,
                session.checkpoint_count,
                session.rendered_frames,
                session.block_count
            ),
        };
        self.last_offline_render_cancellation_receipt
            .replace(Some(receipt.clone()));
        let mut cancelled_session = session;
        cancelled_session.state = RuntimeOfflineRenderExecutionState::Cancelled;
        cancelled_session.interruption_class_override = None;
        cancelled_session.last_state_summary = receipt.summary.clone();
        self.record_last_offline_render_session_snapshot(
            Self::offline_render_session_state_snapshot(&cancelled_session),
        );
        Ok(receipt)
    }

    pub fn render_offline_queue(
        &self,
        requests: Vec<RuntimeOfflineRenderRequest>,
    ) -> Result<RuntimeOfflineRenderQueueResult, RuntimeError> {
        if requests.is_empty() {
            self.record_deferred_service_receipt(deferred_service_receipt(
                RuntimeDeferredServiceClass::OfflineRenderQueue,
                RuntimeDeferredServiceDecision::Abort,
                RuntimeDeferredServiceReason::InvalidRequest,
                0,
                0,
                self.control.running,
                self.safe_mode_enabled,
                matches!(self.readiness, RuntimeReadiness::Degraded { .. }),
                self.transport_concurrency.pending_work_item_count(),
                self.transport_concurrency
                    .pending_deferred_retry_work_count(),
                self.transport_concurrency.recovery_overlap_session_count(),
            ));
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "offline render queue requires at least one request",
            ));
        }
        let queue_count = requests.len();
        let mut orchestration = self.offline_render_queue_receipt(queue_count);
        let mut progress = Vec::with_capacity(orchestration.admitted_work_item_count);
        let mut results = Vec::with_capacity(orchestration.admitted_work_item_count);
        let mut deferred_requests = Vec::with_capacity(orchestration.deferred_work_item_count);
        for (queue_index, request) in requests.into_iter().enumerate() {
            if queue_index >= orchestration.admitted_work_item_count {
                deferred_requests.push(request);
                continue;
            }
            let result = self.render_offline(request)?;
            let completed_job_count = queue_index.saturating_add(1);
            let progress_percent = ((completed_job_count * 100) / queue_count).clamp(0, 100) as u8;
            progress.push(RuntimeOfflineRenderQueueProgressReceipt {
                request_id: result.request_id.clone(),
                queue_index,
                queue_count,
                completed_job_count,
                progress_percent,
                summary: format!(
                    "request={} queue={}/{} progress={}% blocks={} rendered_frames={}",
                    result.request_id,
                    completed_job_count,
                    queue_count,
                    progress_percent,
                    result.block_count,
                    result.rendered_frame_count,
                ),
            });
            results.push(result);
        }
        orchestration.completed_work_item_count = results.len();
        orchestration.deferred_work_item_count = deferred_requests.len();
        orchestration.summary = summarize_deferred_service_receipt(&orchestration);
        let completed_job_count = progress.len();
        let deferred_job_count = deferred_requests.len();
        let decision = orchestration.decision;
        let summary = format!(
            "queue_count={} completed_job_count={} deferred_job_count={} decision={:?}",
            queue_count, completed_job_count, deferred_job_count, decision
        );
        if let Some(last_result) = results.last() {
            self.record_last_offline_render_session_snapshot(
                crate::interfaces::RuntimeOfflineRenderSessionStateSnapshot {
                    request_id: last_result.request_id.clone(),
                    state: RuntimeOfflineRenderExecutionState::Completed,
                    interruption_class: RuntimeInterruptionClass::Steady,
                    interruption_rebindable: false,
                    interruption_count: 0,
                    emitted_checkpoint_count: 0,
                    checkpoint_count: 0,
                    rendered_frame_count: last_result.runtime_frame_count,
                    total_frame_count: last_result.runtime_frame_count,
                    rendered_block_count: last_result.block_count,
                    total_block_count: last_result.block_count,
                    artifact_root_path: last_result.manifest.artifact_root_path.clone(),
                    report_path: last_result
                        .manifest
                        .report
                        .as_ref()
                        .map(|report| report.report_path.clone()),
                    materialized: true,
                    artifact_count: last_result.manifest.artifact_count,
                    report_materialized: last_result.manifest.report.is_some(),
                    active_checkpoint: None,
                    last_checkpoint: None,
                    summary: format!(
                        "request={} state=completed queue_result=true artifacts={} report={}",
                        last_result.request_id,
                        last_result.manifest.artifact_count,
                        last_result.manifest.report.is_some(),
                    ),
                },
            );
        }
        self.record_deferred_service_receipt(orchestration.clone());
        Ok(RuntimeOfflineRenderQueueResult {
            queue_count,
            completed_job_count,
            orchestration,
            progress,
            results,
            deferred_requests,
            summary,
        })
    }

    pub fn purge_offline_render_artifacts(
        &self,
        request: RuntimeOfflineRenderPurgeRequest,
    ) -> Result<RuntimeOfflineRenderPurgeReceipt, RuntimeError> {
        let request_id = request.request_id.trim().to_string();
        if request_id.is_empty() {
            self.record_deferred_service_receipt(deferred_service_receipt(
                RuntimeDeferredServiceClass::OfflineRenderPurge,
                RuntimeDeferredServiceDecision::Abort,
                RuntimeDeferredServiceReason::InvalidRequest,
                1,
                0,
                self.control.running,
                self.safe_mode_enabled,
                matches!(self.readiness, RuntimeReadiness::Degraded { .. }),
                self.transport_concurrency.pending_work_item_count(),
                self.transport_concurrency
                    .pending_deferred_retry_work_count(),
                self.transport_concurrency.recovery_overlap_session_count(),
            ));
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "offline render artifact purge requires a request id",
            ));
        }
        let mut orchestration = self.offline_render_purge_receipt();
        if orchestration.decision != RuntimeDeferredServiceDecision::Run {
            self.record_deferred_service_receipt(orchestration.clone());
            let decision = orchestration.decision;
            let reason = orchestration.reason;
            let summary = format!(
                "request={} deferred decision={:?} reason={:?}",
                request_id, decision, reason
            );
            let receipt = RuntimeOfflineRenderPurgeReceipt {
                request_id,
                orchestration,
                artifact_root_path: request.artifact_root_path,
                report_path: request.report_path,
                purged_artifact_root: false,
                purged_artifact_file_count: 0,
                purged_artifact_byte_count: 0,
                purged_report: false,
                purged_report_byte_count: 0,
                summary,
            };
            self.last_offline_render_purge_receipt
                .replace(Some(receipt.clone()));
            return Ok(receipt);
        }
        let purged_report = request
            .report_path
            .as_deref()
            .map(Path::new)
            .map(purge_offline_render_file)
            .transpose()?
            .unwrap_or_default();
        let purged_artifact_root = request
            .artifact_root_path
            .as_deref()
            .map(Path::new)
            .map(purge_offline_render_directory)
            .transpose()?
            .unwrap_or_default();
        orchestration.completed_work_item_count = 1;
        orchestration.deferred_work_item_count = 0;
        orchestration.summary = summarize_deferred_service_receipt(&orchestration);
        self.record_deferred_service_receipt(orchestration.clone());
        let receipt = RuntimeOfflineRenderPurgeReceipt {
            request_id: request_id.clone(),
            orchestration,
            artifact_root_path: request.artifact_root_path,
            report_path: request.report_path,
            purged_artifact_root: purged_artifact_root.removed,
            purged_artifact_file_count: purged_artifact_root.file_count,
            purged_artifact_byte_count: purged_artifact_root.byte_count,
            purged_report: purged_report.removed,
            purged_report_byte_count: purged_report.byte_count,
            summary: format!(
                "request={} purged_report={} report_bytes={} purged_artifact_root={} artifact_files={} artifact_bytes={}",
                request_id,
                purged_report.removed,
                purged_report.byte_count,
                purged_artifact_root.removed,
                purged_artifact_root.file_count,
                purged_artifact_root.byte_count
            ),
        };
        self.last_offline_render_purge_receipt
            .replace(Some(receipt.clone()));
        Ok(receipt)
    }

    pub fn prepare_offline_plugin_execution_boundary(
        &self,
        request: &RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflinePluginExecutionBoundary, RuntimeError> {
        let preview = RuntimeOfflineRenderContractPreview::from_runtime_state(
            request,
            &self.execution_topology_summary(),
            &self.clip_processing_pipeline_snapshot(),
            &self.media_pipeline_snapshot(),
            &self.tempo_map_snapshot(),
            &self.marker_analysis_snapshot(),
            &self.plugin_recall_handoff_snapshot(),
        )?;
        Ok(self.offline_plugin_execution_boundary_from_preview(request, &preview))
    }

    pub fn prepare_offline_plugin_delegated_execution_request(
        &self,
        request: &RuntimeOfflineRenderRequest,
    ) -> Result<RuntimeOfflinePluginDelegatedExecutionRequest, RuntimeError> {
        let boundary = self.prepare_offline_plugin_execution_boundary(request)?;
        Ok(offline_plugin_delegated_execution_request(&boundary))
    }

    pub fn apply_offline_plugin_delegated_execution_receipt(
        &self,
        result: &RuntimeOfflineRenderResult,
        receipt: RuntimeOfflinePluginDelegatedExecutionReceipt,
    ) -> Result<RuntimeOfflineRenderResult, RuntimeError> {
        let expected_request =
            offline_plugin_delegated_execution_request(&result.plugin_execution_boundary);
        let mut updated = result.clone();
        updated.manifest.delegated_execution_request = expected_request;
        updated
            .manifest
            .apply_delegated_execution_receipt(receipt)?;
        updated.manifest = materialize_offline_render_delivery(&updated)?;
        Ok(updated)
    }

    pub fn apply_offline_plugin_delegated_execution_outcome(
        &self,
        result: &RuntimeOfflineRenderResult,
        outcome: RuntimeOfflinePluginDelegatedExecutionOutcome,
    ) -> Result<RuntimeOfflineRenderResult, RuntimeError> {
        let expected_request =
            offline_plugin_delegated_execution_request(&result.plugin_execution_boundary);
        let mut updated = result.clone();
        updated.manifest.delegated_execution_request = expected_request;
        updated
            .manifest
            .apply_delegated_execution_receipt(outcome.receipt)?;
        apply_delegated_execution_merge(&mut updated, &outcome.merge)?;
        updated.manifest = materialize_offline_render_delivery(&updated)?;
        Ok(updated)
    }

    fn render_clip_processing_buffer_with_resolved_tempo(
        &self,
        request: RuntimeClipRenderRequest,
        resolved_tempo: &RuntimeResolvedTempo,
    ) -> Result<RuntimeClipRenderResult, RuntimeError> {
        let preview_transform_snapshot = self.preview_transform_snapshot();
        let transform_artifact_snapshot = self.transform_artifact_snapshot();
        let transform_artifact_clip = transform_artifact_snapshot
            .clips
            .iter()
            .find(|clip| clip.clip_id == request.clip_id)
            .cloned()
            .unwrap_or_else(|| RuntimeTransformArtifactClipSnapshot {
                clip_id: request.clip_id.clone(),
                media_asset_id: None,
                artifact_identity: format!("artifact:missing:{}", request.clip_id),
                readiness: RuntimeTransformArtifactReadiness::Unsupported,
                invalidation_state: RuntimeTransformArtifactInvalidationState::None,
                reuse_state: RuntimeTransformArtifactReuseState::Unavailable,
                cached_media_ready: false,
                stretch_engine_class: RuntimeStretchEngineClass::Disabled,
                stretch_readiness: RuntimeStretchReadiness::Disabled,
                marker_analysis_readiness: RuntimeMarkerAnalysisReadiness::Unsupported,
                summary: format!(
                    "clip={} readiness=Unsupported invalidation=None reuse=Unavailable cached_media_ready=false stretch=Disabled/Disabled analysis=Unsupported",
                    request.clip_id
                ),
            });
        let preview_transform_clip = preview_transform_snapshot
            .clips
            .iter()
            .find(|clip| clip.clip_id == request.clip_id)
            .cloned()
            .unwrap_or_else(|| RuntimePreviewTransformClipSnapshot {
                clip_id: request.clip_id.clone(),
                media_asset_id: None,
                service_class: RuntimePreviewTransformServiceClass::Unavailable,
                readiness: RuntimePreviewTransformReadiness::Unsupported,
                degraded_state: RuntimePreviewTransformDegradedState::UnsupportedScope,
                fallback_kind: RuntimePreviewTransformFallbackKind::OfflineOnly,
                artifact_reuse_state: RuntimeTransformArtifactReuseState::Unavailable,
                audition_active: false,
                scrub_supported: false,
                summary: format!(
                    "clip={} class=Unavailable readiness=Unsupported degraded=UnsupportedScope fallback=OfflineOnly artifact_reuse=Unavailable audition_active=false scrub_supported=false",
                    request.clip_id
                ),
            });
        self.clip_processing_pipeline.render_clip(
            request,
            &self.media_pipeline,
            &self.warp_pipeline,
            resolved_tempo,
            transform_artifact_clip,
            preview_transform_clip,
        )
    }

    fn offline_render_input_layout(&self) -> Result<ChannelLayout, RuntimeError> {
        let graph = self.engine.graph.as_ref().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "offline render requires an applied executable graph",
            )
        })?;
        let contract = graph.contract_summary();
        let mut layout = None;
        for node in contract
            .node_contracts
            .iter()
            .filter(|node| node.input_bus_id == "main:in")
        {
            match layout {
                Some(existing) if existing != node.input_channels => {
                    return Err(RuntimeError::new(
                        RuntimeErrorKind::UnsupportedCapability,
                        "offline render requires a consistent main:in channel layout",
                    ));
                }
                None => layout = Some(node.input_channels),
                _ => {}
            }
        }
        Ok(layout.unwrap_or(ChannelLayout::Stereo))
    }

    fn offline_plugin_execution_boundary_from_preview(
        &self,
        request: &RuntimeOfflineRenderRequest,
        _preview: &RuntimeOfflineRenderContractPreview,
    ) -> RuntimeOfflinePluginExecutionBoundary {
        let boundary_counts = runtime_plugin_boundary_counts(&self.engine.snapshot.planned_nodes);
        let sandboxes = self
            .plugin_lifecycle
            .snapshot(
                &self.plugin_placement_policy,
                &boundary_counts.sandbox_stage_counts,
                &self.plugin_discovery.discovered_types,
                &self.plugin_discovery.platform_coverage,
            )
            .sandboxes
            .into_iter()
            .map(|sandbox| (sandbox.sandbox_id.clone(), sandbox))
            .collect::<BTreeMap<_, _>>();
        let node_by_id = self
            .applied_graph
            .as_ref()
            .map(|graph| {
                graph
                    .nodes
                    .iter()
                    .map(|node| (node.node_id.as_str(), node))
                    .collect::<BTreeMap<_, _>>()
            })
            .unwrap_or_default();
        let handoff = self.plugin_recall_handoff_snapshot();
        let last_processing_epoch = self.engine.snapshot.last_processing_epoch;
        let last_block_sequence = self.engine.snapshot.last_block_sequence;
        let block_size = self.config.graph.block_size.max(1);
        let block_count = (request.duration_samples as usize)
            .saturating_add(block_size.saturating_sub(1))
            / block_size;

        let stages = handoff
            .stages
            .iter()
            .map(|stage| {
                let execution_owner = match node_by_id.get(stage.node_id.as_str()) {
                    Some(node) if node.stages.is_empty() => {
                        RuntimeOfflinePluginExecutionOwner::HostDelegated
                    }
                    _ => RuntimeOfflinePluginExecutionOwner::SignalStageModel,
                };
                let (override_state, _) = offline_render_plugin_override_status(
                    self.engine.latest_plugin_node_renders.get(&stage.node_id),
                    stage.recall_payload.sandbox_id.as_ref(),
                    &sandboxes,
                    last_processing_epoch,
                    last_block_sequence,
                );
                let latest_override = self.engine.latest_plugin_node_renders.get(&stage.node_id);
                let host_delegate_required =
                    execution_owner == RuntimeOfflinePluginExecutionOwner::HostDelegated;
                let mut boundary = RuntimeOfflinePluginExecutionStageBoundary {
                    stage_id: stage.stage_id.clone(),
                    node_id: stage.node_id.clone(),
                    chain_id: stage.chain_id.clone(),
                    stage_index: stage.stage_index,
                    sandbox_id: stage.recall_payload.sandbox_id.clone(),
                    plugin_type_id: stage.recall_payload.plugin_type_id.clone(),
                    plugin_format: stage.recall_payload.plugin_format,
                    track_lane_id: stage.track_lane_id.clone(),
                    bus_group_id: stage.bus_group_id.clone(),
                    console_group_id: stage.console_group_id.clone(),
                    send_return_id: stage.send_return_id.clone(),
                    recall_state: stage.recall_state,
                    recall_payload: stage.recall_payload.clone(),
                    execution_owner,
                    host_delegate_required,
                    override_state,
                    latest_override_processing_epoch: latest_override
                        .map(|latest| latest.processing_epoch),
                    latest_override_block_sequence: latest_override.map(|latest| latest.block_sequence),
                    summary: String::new(),
                };
                boundary.summary = format!(
                    "stage={}:{} owner={:?} host_delegate={} override={:?} sandbox={:?} recall={:?}",
                    boundary.chain_id,
                    boundary.stage_index,
                    boundary.execution_owner,
                    boundary.host_delegate_required,
                    boundary.override_state,
                    boundary.sandbox_id.as_deref(),
                    boundary.recall_state,
                );
                boundary
            })
            .collect::<Vec<_>>();

        let mut boundary = RuntimeOfflinePluginExecutionBoundary {
            request_id: request.request_id.clone(),
            timeline_start_samples: request.timeline_start_samples,
            duration_samples: request.duration_samples,
            runtime_sample_rate_hz: self.config.sample_rate.0,
            export_sample_rate_hz: request.export_sample_rate_hz,
            block_size,
            block_count,
            stage_count: stages.len(),
            signal_stage_model_stage_count: stages
                .iter()
                .filter(|stage| {
                    stage.execution_owner == RuntimeOfflinePluginExecutionOwner::SignalStageModel
                })
                .count(),
            host_delegate_stage_count: stages
                .iter()
                .filter(|stage| stage.host_delegate_required)
                .count(),
            fresh_override_stage_count: stages
                .iter()
                .filter(|stage| {
                    stage.override_state == RuntimeOfflinePluginOverrideState::FreshLatestBlock
                })
                .count(),
            stale_override_stage_count: stages
                .iter()
                .filter(|stage| {
                    stage.override_state == RuntimeOfflinePluginOverrideState::StaleLatestBlock
                })
                .count(),
            stages,
            summary: String::new(),
        };
        boundary.summary = format!(
            "request={} stages={} signal_stage_model={} host_delegate={} fresh_overrides={} stale_overrides={} blocks={} runtime_rate={} export_rate={}",
            boundary.request_id,
            boundary.stage_count,
            boundary.signal_stage_model_stage_count,
            boundary.host_delegate_stage_count,
            boundary.fresh_override_stage_count,
            boundary.stale_override_stage_count,
            boundary.block_count,
            boundary.runtime_sample_rate_hz,
            boundary.export_sample_rate_hz,
        );
        boundary
    }

    fn offline_render_plugin_node_overrides(
        &self,
    ) -> Result<Vec<GraphNodeRenderOverride>, RuntimeError> {
        let Some(graph) = self.applied_graph.as_ref() else {
            return Ok(Vec::new());
        };
        let last_processing_epoch = self.engine.snapshot.last_processing_epoch;
        let last_block_sequence = self.engine.snapshot.last_block_sequence;
        let boundary_counts = runtime_plugin_boundary_counts(&self.engine.snapshot.planned_nodes);
        let sandboxes = self
            .plugin_lifecycle
            .snapshot(
                &self.plugin_placement_policy,
                &boundary_counts.sandbox_stage_counts,
                &self.plugin_discovery.discovered_types,
                &self.plugin_discovery.platform_coverage,
            )
            .sandboxes
            .into_iter()
            .map(|sandbox| (sandbox.sandbox_id.clone(), sandbox))
            .collect::<BTreeMap<_, _>>();

        graph
            .nodes
            .iter()
            .filter(|node| node.execution_class == GraphNodeExecutionClass::PluginBacked)
            .filter_map(|node| {
                let bound_sandbox_id = self.engine.plugin_node_bindings.get(&node.node_id);
                let (_, fresh_override) = offline_render_plugin_override_status(
                    self.engine.latest_plugin_node_renders.get(&node.node_id),
                    bound_sandbox_id,
                    &sandboxes,
                    last_processing_epoch,
                    last_block_sequence,
                );
                fresh_override.map(|render| {
                    Ok(GraphNodeRenderOverride {
                        node_id: node.node_id.clone(),
                        buffer: render.output.clone(),
                        latency_samples: render.latency_samples,
                        tail_samples: render.tail_samples,
                        bypassed: render.bypassed,
                    })
                })
            })
            .collect()
    }

    fn offline_render_context(
        &self,
        block_sequence: u64,
        timeline_position_samples: i64,
    ) -> GraphExecutionContext {
        let transport = self.offline_render_transport(timeline_position_samples);
        GraphExecutionContext {
            processing_epoch: 1,
            block_sequence,
            projection_epoch: self.projection_epoch,
            parameter_epoch: self.latest_parameter_epoch,
            configured_block_size: self.config.graph.block_size,
            anticipative_enabled: false,
            transport_playing: transport.playing,
            transport_tempo_bpm: transport.tempo_bpm,
            timeline_position_samples: transport.timeline_position_samples,
        }
    }

    fn offline_render_transport(&self, timeline_position_samples: i64) -> TransportProjection {
        let resolved_tempo = self.resolved_tempo_for_timeline_position(timeline_position_samples);
        TransportProjection {
            playing: true,
            timeline_position_samples,
            tempo_bpm: resolved_tempo.tempo_bpm,
            loop_state: None,
        }
    }

    fn resolved_tempo_for_timeline_position(
        &self,
        timeline_position_samples: i64,
    ) -> RuntimeResolvedTempo {
        let projected_transport = Some(TransportProjection {
            playing: true,
            timeline_position_samples,
            tempo_bpm: self
                .applied_transport
                .map(|transport| transport.tempo_bpm)
                .unwrap_or(120.0),
            loop_state: None,
        });
        self.tempo_map.resolve(
            Some(timeline_position_samples),
            projected_transport,
            self.timeline.last_transport_tempo_bpm,
        )
    }

    fn offline_render_input_block(
        &self,
        timeline_start_samples: i64,
        frame_count: usize,
        input_layout: ChannelLayout,
        resolved_tempo: &RuntimeResolvedTempo,
        decoded_media_assets: &mut BTreeMap<String, AudioBuffer>,
    ) -> Result<AudioBuffer, RuntimeError> {
        let clip_processing = self.clip_processing_pipeline.snapshot(
            &self.media_pipeline,
            &self.warp_pipeline,
            resolved_tempo,
        );
        let mut input = AudioBuffer::new(
            self.config.sample_rate,
            input_layout,
            FrameCount(frame_count),
        );
        for clip in clip_processing
            .clips
            .iter()
            .filter(|clip| clip.readiness == RuntimeClipProcessingReadiness::Ready)
        {
            let registration = self
                .clip_processing_pipeline
                .clips
                .get(&clip.clip_id)
                .ok_or_else(|| {
                    RuntimeError::new(
                        RuntimeErrorKind::InvalidState,
                        format!(
                            "offline render clip `{}` is missing registration state",
                            clip.clip_id
                        ),
                    )
                })?;
            let source = self.offline_render_clip_source_block(
                registration,
                clip,
                timeline_start_samples,
                frame_count,
                decoded_media_assets,
            )?;
            let rendered = self.render_clip_processing_buffer_with_resolved_tempo(
                RuntimeClipRenderRequest {
                    clip_id: clip.clip_id.clone(),
                    timeline_start_samples,
                    input_stage: RuntimeClipRenderInputStage::PostWarp,
                    buffer: source,
                },
                resolved_tempo,
            )?;
            let adapted = adapt_audio_buffer_layout(&rendered.output, input_layout);
            mix_audio_buffer(&mut input, &adapted);
        }
        Ok(input)
    }

    fn offline_render_clip_source_block(
        &self,
        registration: &RuntimeClipProcessingRegistration,
        clip: &RuntimeClipProcessingSnapshot,
        timeline_start_samples: i64,
        frame_count: usize,
        decoded_media_assets: &mut BTreeMap<String, AudioBuffer>,
    ) -> Result<AudioBuffer, RuntimeError> {
        let media_asset_id = registration.media_asset_id.as_deref().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::UnsupportedCapability,
                format!(
                    "offline render clip `{}` requires a runtime-owned media asset",
                    registration.clip_id
                ),
            )
        })?;
        let asset =
            decode_runtime_media_asset(&self.media_pipeline, media_asset_id, decoded_media_assets)?;
        let ratio = clip.realized_warp_ratio.unwrap_or(1.0);
        let asset_frame_ratio = asset.sample_rate().0 as f64 / self.config.sample_rate.0 as f64;
        let mut output = AudioBuffer::new(
            asset.sample_rate(),
            asset.channels(),
            FrameCount(frame_count),
        );
        let channel_count = output.channel_count().0;
        let asset_frames = asset.frames().0;
        for frame_index in 0..frame_count {
            let timeline_position_samples =
                timeline_start_samples.saturating_add(frame_index as i64);
            let clip_offset_samples =
                timeline_position_samples.saturating_sub(registration.start_samples);
            if clip_offset_samples < 0
                || clip_offset_samples >= i64::from(registration.duration_samples)
            {
                continue;
            }
            let source_frame = (clip_offset_samples as f64 * ratio * asset_frame_ratio).max(0.0);
            for channel_index in 0..channel_count {
                output.samples_mut()[frame_index * channel_count + channel_index] =
                    sample_audio_buffer_linear(&asset, source_frame, channel_index, asset_frames);
            }
        }
        Ok(output)
    }

    fn offline_render_stem_block(
        &self,
        stem: &RuntimeOfflineRenderStemPreview,
        main_output: &AudioBuffer,
        captured_buses: &[GraphCapturedBusOutput],
    ) -> Result<AudioBuffer, RuntimeError> {
        if stem.target_kind == crate::interfaces::RuntimeOfflineRenderTargetKind::MainMix {
            return Ok(main_output.clone());
        }
        if stem.resolved_output_bus_ids.is_empty() {
            return Ok(main_output.clone());
        }
        let mut mixed: Option<AudioBuffer> = None;
        for bus_id in &stem.resolved_output_bus_ids {
            let Some(captured) = captured_buses.iter().find(|bus| &bus.bus_id == bus_id) else {
                continue;
            };
            if let Some(buffer) = mixed.as_mut() {
                let adapted = adapt_audio_buffer_layout(&captured.buffer, buffer.channels());
                mix_audio_buffer(buffer, &adapted);
            } else {
                mixed = Some(captured.buffer.clone());
            }
        }
        Ok(mixed.unwrap_or_else(|| {
            AudioBuffer::new(
                self.config.sample_rate,
                main_output.channels(),
                main_output.frames(),
            )
        }))
    }

    pub fn prepare_engine_prework_for_block(
        &mut self,
        processing_epoch: u64,
        target_block_sequence: u64,
        admitted_from_block_sequence: u64,
        buffer: AudioBuffer,
    ) -> Result<bool, RuntimeError> {
        self.prepare_engine_prework_for_block_with_future_state(
            processing_epoch,
            target_block_sequence,
            admitted_from_block_sequence,
            buffer,
            None,
            None,
        )
    }

    pub fn prepare_engine_prework_for_block_with_future_state(
        &mut self,
        processing_epoch: u64,
        target_block_sequence: u64,
        admitted_from_block_sequence: u64,
        buffer: AudioBuffer,
        parameter_epoch_override: Option<u64>,
        transport_override: Option<TransportProjection>,
    ) -> Result<bool, RuntimeError> {
        if !self.control.configured {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime must be configured before preparing engine prework",
            ));
        }
        let context = self.build_engine_execution_context_with_overrides(
            processing_epoch,
            target_block_sequence,
            parameter_epoch_override,
            transport_override,
        );
        let transport = self.resolve_transport(transport_override);
        self.engine.admit_prework_for_block(
            context,
            transport,
            admitted_from_block_sequence,
            buffer,
        )
    }

    pub fn prepare_engine_prework_window(
        &mut self,
        processing_epoch: u64,
        targets: Vec<RuntimePreworkWindowTarget>,
    ) -> Result<usize, RuntimeError> {
        if !self.control.configured {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime must be configured before preparing engine prework",
            ));
        }
        if targets.is_empty() {
            return Ok(0);
        }

        let mut sorted_targets = targets;
        sorted_targets.sort_by_key(|target| target.target_block_sequence);
        let current_block_sequence = sorted_targets
            .iter()
            .map(|target| target.admitted_from_block_sequence)
            .min()
            .unwrap_or(0);

        let planned_sequences: Vec<u64> = sorted_targets
            .iter()
            .map(|target| target.target_block_sequence)
            .collect();
        self.engine.retire_prework_entries_matching(
            |cache| {
                cache.source_block_sequence >= current_block_sequence
                    && !planned_sequences.contains(&cache.source_block_sequence)
            },
            RuntimePreworkInvalidationReason::PlanningWindowRevised,
        );
        self.engine.pending_prework_targets.clear();

        let mut admitted = 0usize;
        for target in sorted_targets {
            let context = self.build_engine_execution_context_with_overrides(
                processing_epoch,
                target.target_block_sequence,
                target.parameter_epoch_override,
                target.transport_override,
            );
            let transport = self.resolve_transport(target.transport_override);
            if self.engine.admit_prework_for_block(
                context,
                transport,
                target.admitted_from_block_sequence,
                target.buffer,
            )? {
                admitted = admitted.saturating_add(1);
            }
        }
        self.engine.update_prework_queue_snapshot(
            Some(current_block_sequence),
            self.engine.snapshot.prework_cache_state == RuntimePreworkCacheState::Invalidated,
        );
        Ok(admitted)
    }

    fn service_pending_prework_cycle(
        &mut self,
        processing_epoch: u64,
        budget: usize,
        max_backlog_class: RuntimePreworkBacklogClass,
    ) -> Result<usize, RuntimeError> {
        if budget == 0 || !self.control.configured {
            return Ok(0);
        }
        let targets = self
            .engine
            .take_pending_prework_targets(budget, max_backlog_class);
        if targets.is_empty() {
            return Ok(0);
        }

        let mut admitted = 0usize;
        for target in targets {
            self.engine.record_last_serviced_pending_target(&target);
            if self.prepare_engine_prework_for_block_with_future_state(
                processing_epoch,
                target.target_block_sequence,
                target.admitted_from_block_sequence,
                target.buffer,
                target.parameter_epoch_override,
                target.transport_override,
            )? {
                admitted = admitted.saturating_add(1);
            }
        }
        Ok(admitted)
    }

    pub fn prime_engine_prework_window_with_forecast(
        &mut self,
        processing_epoch: u64,
        current_block_sequence: u64,
        policy: &RuntimePreworkForecastPolicy,
    ) -> Result<usize, RuntimeError> {
        self.reconcile_prework_window_with_forecast(current_block_sequence, policy);
        let admitted = if self.control.running {
            let requested_cycles = self.multicore_prework_requested_cycles(1);
            self.service_prework_lane_with_policy(
                processing_epoch,
                requested_cycles,
                policy.prepare_budget_per_cycle,
            )?
        } else {
            self.prime_pending_prework_targets(
                processing_epoch,
                policy.prepare_budget_per_cycle,
                RuntimePreworkBacklogClass::Deferred,
            )?
        };
        self.reconcile_prework_service_state(Some(processing_epoch));
        Ok(admitted)
    }

    fn enforce_scheduler_after_engine_block(
        &mut self,
        processing_epoch: u64,
        current_block_sequence: u64,
    ) -> Result<usize, RuntimeError> {
        if !self.control.configured {
            return Ok(0);
        }
        if self.prework_forecast_mode == RuntimePreworkForecastMode::Disabled
            || !self.engine.snapshot.prework_cache_enabled
        {
            self.reconcile_prework_service_state(Some(processing_epoch));
            return Ok(0);
        }
        let Some(policy) = self.prework_forecast_policy.clone() else {
            self.reconcile_prework_service_state(Some(processing_epoch));
            return Ok(0);
        };

        self.reconcile_prework_window_with_forecast(current_block_sequence, &policy);
        if self.control.running {
            let requested_cycles = self.multicore_prework_requested_cycles(1);
            self.service_prework_lane_with_policy(
                processing_epoch,
                requested_cycles,
                policy.prepare_budget_per_cycle,
            )
        } else {
            let prepared = self.prime_pending_prework_targets(
                processing_epoch,
                policy.prepare_budget_per_cycle,
                RuntimePreworkBacklogClass::Deferred,
            )?;
            self.reconcile_prework_service_state(Some(processing_epoch));
            Ok(prepared)
        }
    }

    fn reconcile_prework_window_with_forecast(
        &mut self,
        current_block_sequence: u64,
        policy: &RuntimePreworkForecastPolicy,
    ) -> usize {
        let desired_count = policy.target_window_blocks;
        let target_block_sequences =
            self.plan_prework_window_block_sequences(current_block_sequence, desired_count);
        if target_block_sequences.is_empty() {
            self.engine.update_prework_queue_snapshot(
                Some(current_block_sequence),
                self.engine.snapshot.prework_cache_state == RuntimePreworkCacheState::Invalidated,
            );
            return 0;
        }

        let targets = target_block_sequences
            .into_iter()
            .map(|target_block_sequence| RuntimePreworkWindowTarget {
                target_block_sequence,
                admitted_from_block_sequence: current_block_sequence,
                buffer: synthetic_stereo_block(
                    self.config.sample_rate,
                    FrameCount(self.config.graph.block_size),
                    target_block_sequence.saturating_add(policy.buffer_seed_offset),
                ),
                parameter_epoch_override: Some(
                    self.forecast_parameter_batch_for_block(target_block_sequence, policy)
                        .epoch,
                ),
                transport_override: Some(
                    self.forecast_transport_projection_for_block(target_block_sequence, policy),
                ),
            })
            .collect::<Vec<_>>();
        let graph_id = self
            .engine
            .graph
            .as_ref()
            .map(|graph| graph.graph_id().to_string());
        self.engine.reconcile_pending_prework_targets(
            &targets,
            graph_id.as_deref(),
            self.projection_epoch,
            self.latest_parameter_epoch,
            self.applied_transport,
            self.config.graph.block_size,
        );
        targets.len()
    }

    fn service_prework_lane_with_policy(
        &mut self,
        processing_epoch: u64,
        cycles: usize,
        budget_per_cycle: usize,
    ) -> Result<usize, RuntimeError> {
        if !self.control.configured {
            return Ok(0);
        }
        if self.prework_forecast_mode == RuntimePreworkForecastMode::Disabled
            || !self.engine.snapshot.prework_cache_enabled
        {
            self.reconcile_prework_service_state(Some(processing_epoch));
            return Ok(0);
        }
        if !self.control.running {
            self.reconcile_prework_service_state(Some(processing_epoch));
            return Ok(0);
        }
        if self.engine.pending_prework_targets.is_empty() {
            self.reconcile_prework_service_state(Some(processing_epoch));
            return Ok(0);
        }
        self.recompute_prework_service_policy_snapshot();
        let pressure = self.engine.snapshot.prework_service_pressure;
        let semantic_policy = self.engine.snapshot.prework_service_semantic_policy;
        let transport_condition = self.current_prework_transport_condition();
        let widened_budget_per_cycle =
            budget_per_cycle.saturating_mul(self.multicore_prework_budget_scale().max(1));
        if self.engine.snapshot.prework_service_plugin_gate_active
            || self.engine.snapshot.prework_service_transport_gate_active
        {
            self.engine
                .record_prework_service_yield(processing_epoch, cycles, budget_per_cycle);
            self.engine.transition_prework_service_state(
                RuntimePreworkServiceState::Yielding,
                Some(processing_epoch),
            );
            return Ok(0);
        }
        let (effective_cycles, effective_budget_per_cycle, max_backlog_class) = match pressure {
            RuntimePreworkServicePressure::Normal => (
                cycles,
                widened_budget_per_cycle,
                RuntimePreworkBacklogClass::Deferred,
            ),
            RuntimePreworkServicePressure::Elevated => match semantic_policy {
                RuntimePreworkServiceSemanticPolicy::Balanced => (
                    cycles.min(1),
                    widened_budget_per_cycle.min(1),
                    RuntimePreworkBacklogClass::NearTerm,
                ),
                RuntimePreworkServiceSemanticPolicy::PluginConstrained => (
                    cycles.min(1),
                    widened_budget_per_cycle.min(1),
                    RuntimePreworkBacklogClass::Immediate,
                ),
                RuntimePreworkServiceSemanticPolicy::LatencyFocused => (
                    cycles.min(1),
                    widened_budget_per_cycle.min(2),
                    RuntimePreworkBacklogClass::Deferred,
                ),
            },
            RuntimePreworkServicePressure::Critical => {
                (0, 0, RuntimePreworkBacklogClass::Immediate)
            }
        };
        let (effective_cycles, effective_budget_per_cycle, max_backlog_class) = transport_condition
            .reduce_service_scope(
                effective_cycles,
                effective_budget_per_cycle,
                max_backlog_class,
            );
        if pressure == RuntimePreworkServicePressure::Critical {
            self.engine
                .record_prework_service_yield(processing_epoch, cycles, budget_per_cycle);
            self.engine.transition_prework_service_state(
                RuntimePreworkServiceState::Yielding,
                Some(processing_epoch),
            );
            return Ok(0);
        }
        self.engine.record_prework_service_request(
            cycles,
            effective_cycles,
            budget_per_cycle,
            effective_budget_per_cycle,
        );
        if effective_cycles == 0 || effective_budget_per_cycle == 0 {
            self.engine.transition_prework_service_state(
                RuntimePreworkServiceState::Starved,
                Some(processing_epoch),
            );
            return Ok(0);
        }

        self.engine.transition_prework_service_state(
            RuntimePreworkServiceState::Servicing,
            Some(processing_epoch),
        );
        let mut total_prepared = 0usize;
        let mut executed_cycles = 0usize;
        for _ in 0..effective_cycles {
            executed_cycles = executed_cycles.saturating_add(1);
            total_prepared = total_prepared.saturating_add(self.service_pending_prework_cycle(
                processing_epoch,
                effective_budget_per_cycle,
                max_backlog_class,
            )?);
            if self.engine.pending_prework_targets.is_empty() {
                break;
            }
        }
        self.engine.record_prework_service_cycle(
            processing_epoch,
            executed_cycles,
            budget_per_cycle,
            total_prepared,
        );
        if !self.engine.pending_prework_targets.is_empty() && total_prepared == 0 {
            if pressure == RuntimePreworkServicePressure::Elevated {
                self.engine.record_prework_service_yield(
                    processing_epoch,
                    cycles,
                    budget_per_cycle,
                );
                self.engine.transition_prework_service_state(
                    RuntimePreworkServiceState::Yielding,
                    Some(processing_epoch),
                );
            } else {
                self.engine.transition_prework_service_state(
                    RuntimePreworkServiceState::Starved,
                    Some(processing_epoch),
                );
            }
        } else {
            self.reconcile_prework_service_state(Some(processing_epoch));
        }
        Ok(total_prepared)
    }

    pub fn forecast_transport_projection_for_block(
        &self,
        block_sequence: u64,
        policy: &RuntimePreworkForecastPolicy,
    ) -> TransportProjection {
        let loop_length_blocks = policy.transport_loop_length_blocks.max(1);
        let loop_end_samples = (self
            .config
            .graph
            .block_size
            .saturating_mul(loop_length_blocks)) as i64;
        let timeline_position_samples = ((block_sequence as i64)
            .saturating_mul(self.config.graph.block_size as i64))
        .rem_euclid(loop_end_samples);
        TransportProjection {
            playing: policy.transport_playing,
            timeline_position_samples,
            tempo_bpm: policy.transport_tempo_bpm,
            loop_state: Some(crate::interfaces::LoopRegion {
                start_samples: 0,
                end_samples: loop_end_samples,
            }),
        }
    }

    pub fn forecast_parameter_batch_for_block(
        &self,
        block_sequence: u64,
        policy: &RuntimePreworkForecastPolicy,
    ) -> ParameterBatch {
        let cycle_length = policy.parameter_cycle_length.max(1);
        let denominator = cycle_length.saturating_sub(1).max(1) as f32;
        ParameterBatch {
            epoch: self
                .projection_epoch
                .saturating_add(block_sequence)
                .saturating_add(1),
            events: vec![crate::interfaces::ParameterEvent {
                target: policy.parameter_target.clone(),
                sample_offset: 0,
                normalized_value: ((block_sequence % cycle_length) as f32) / denominator,
            }],
        }
    }

    pub fn apply_forecast_state_for_block(
        &mut self,
        processing_epoch: u64,
        block_sequence: u64,
    ) -> Result<usize, RuntimeError> {
        let policy = self.prework_forecast_policy.clone().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime prework forecast policy must be set before applying forecast state",
            )
        })?;
        self.apply_forecast_transport_projection(
            self.forecast_transport_projection_for_block(block_sequence, &policy),
        )?;
        self.apply_parameter_batch(
            self.forecast_parameter_batch_for_block(block_sequence, &policy),
        )?;
        if self.prework_forecast_mode == RuntimePreworkForecastMode::Disabled {
            return Ok(0);
        }
        let _ = processing_epoch;
        Ok(self.reconcile_prework_window_with_forecast(block_sequence, &policy))
    }

    pub fn prepare_plugin_dispatch_state_for_block(
        &mut self,
        processing_epoch: u64,
        block_sequence: u64,
    ) -> Result<RuntimePluginDispatchState, RuntimeError> {
        if self.prework_forecast_mode == RuntimePreworkForecastMode::Disabled {
            return Ok(RuntimePluginDispatchState {
                transport: self.applied_transport,
                parameter_batch: None,
            });
        }

        let Some(policy) = self.prework_forecast_policy.clone() else {
            return Ok(RuntimePluginDispatchState {
                transport: self.applied_transport,
                parameter_batch: None,
            });
        };

        let transport = self.forecast_transport_projection_for_block(block_sequence, &policy);
        let parameter_batch = self.forecast_parameter_batch_for_block(block_sequence, &policy);
        self.apply_forecast_transport_projection(transport)?;
        self.apply_parameter_batch(parameter_batch.clone())?;
        let _ = processing_epoch;
        let _ = self.reconcile_prework_window_with_forecast(block_sequence, &policy);

        Ok(RuntimePluginDispatchState {
            transport: Some(transport),
            parameter_batch: Some(parameter_batch),
        })
    }

    fn apply_forecast_transport_projection(
        &mut self,
        projection: TransportProjection,
    ) -> Result<(), RuntimeError> {
        if projection.tempo_bpm <= 0.0 {
            return Err(RuntimeError::new(
                RuntimeErrorKind::InvalidRequest,
                "tempo_bpm must be positive",
            ));
        }
        self.applied_transport = Some(projection);
        self.timeline.update_transport_state(projection);
        self.engine.snapshot.transport_epoch = self.timeline.transport_epoch;
        self.engine.snapshot.transport_transition = None;
        self.engine.snapshot.transport_loop_wrapped = false;
        Ok(())
    }

    pub fn service_prework_lane(
        &mut self,
        processing_epoch: u64,
        cycles: usize,
    ) -> Result<usize, RuntimeError> {
        if self.prework_forecast_mode == RuntimePreworkForecastMode::Disabled {
            return Ok(0);
        }
        let policy = self.prework_forecast_policy.clone().ok_or_else(|| {
            RuntimeError::new(
                RuntimeErrorKind::InvalidState,
                "runtime prework forecast policy must be set before servicing the prework lane",
            )
        })?;
        self.service_prework_lane_with_policy(
            processing_epoch,
            cycles,
            policy.prepare_budget_per_cycle,
        )
    }

    pub fn next_planned_prework_block_sequence(
        &self,
        after_block_sequence: Option<u64>,
    ) -> Option<u64> {
        self.engine
            .prework_queue
            .iter()
            .filter_map(|cache| {
                let target = cache.source_block_sequence;
                match after_block_sequence {
                    Some(after) if target <= after => None,
                    _ => Some(target),
                }
            })
            .min()
    }

    pub fn plan_prework_window_block_sequences(
        &mut self,
        current_block_sequence: u64,
        desired_count: usize,
    ) -> Vec<u64> {
        if !self.engine.snapshot.prework_cache_enabled {
            return Vec::new();
        }

        let mut retained_sequences = self
            .engine
            .prework_queue
            .iter()
            .filter_map(|cache| {
                let target = cache.source_block_sequence;
                (target > current_block_sequence).then_some(target)
            })
            .collect::<Vec<_>>();
        retained_sequences.sort_unstable();
        retained_sequences.dedup();

        if retained_sequences.len() > desired_count {
            retained_sequences.truncate(desired_count);
            self.engine.retire_prework_entries_matching(
                |cache| {
                    cache.source_block_sequence > current_block_sequence
                        && !retained_sequences.contains(&cache.source_block_sequence)
                },
                RuntimePreworkInvalidationReason::PlanningWindowRevised,
            );
        } else if desired_count == 0 {
            self.engine.retire_prework_entries_matching(
                |cache| cache.source_block_sequence > current_block_sequence,
                RuntimePreworkInvalidationReason::PlanningWindowRevised,
            );
            retained_sequences.clear();
        }

        let mut next_sequence = current_block_sequence.saturating_add(1);
        while retained_sequences.len() < desired_count {
            if !retained_sequences.contains(&next_sequence) {
                retained_sequences.push(next_sequence);
            }
            next_sequence = next_sequence.saturating_add(1);
        }
        retained_sequences
    }

    fn prime_pending_prework_targets(
        &mut self,
        processing_epoch: u64,
        budget: usize,
        max_backlog_class: RuntimePreworkBacklogClass,
    ) -> Result<usize, RuntimeError> {
        if budget == 0 || !self.control.configured {
            return Ok(0);
        }
        let prepared =
            self.service_pending_prework_cycle(processing_epoch, budget, max_backlog_class)?;
        if prepared > 0 {
            self.engine.transition_prework_service_state(
                RuntimePreworkServiceState::Pending,
                Some(processing_epoch),
            );
        }
        Ok(prepared)
    }

    fn build_engine_execution_context(
        &self,
        processing_epoch: u64,
        block_sequence: u64,
    ) -> GraphExecutionContext {
        self.build_engine_execution_context_with_overrides(
            processing_epoch,
            block_sequence,
            None,
            None,
        )
    }

    fn build_engine_execution_context_with_overrides(
        &self,
        processing_epoch: u64,
        block_sequence: u64,
        parameter_epoch_override: Option<u64>,
        transport_override: Option<TransportProjection>,
    ) -> GraphExecutionContext {
        let transport = self.resolve_transport(transport_override);
        GraphExecutionContext {
            processing_epoch,
            block_sequence,
            projection_epoch: self.projection_epoch,
            parameter_epoch: parameter_epoch_override.unwrap_or(self.latest_parameter_epoch),
            configured_block_size: self.config.graph.block_size,
            anticipative_enabled: self.anticipative_enabled,
            transport_playing: transport.map(|t| t.playing).unwrap_or(false),
            transport_tempo_bpm: transport.map(|t| t.tempo_bpm).unwrap_or(0.0),
            timeline_position_samples: transport.map(|t| t.timeline_position_samples).unwrap_or(0),
        }
    }

    fn resolve_transport(
        &self,
        transport_override: Option<TransportProjection>,
    ) -> Option<TransportProjection> {
        transport_override.or(self.applied_transport)
    }

    fn advance_engine_transport(&mut self, frame_count: i64) -> RuntimeEngineTransportAdvance {
        let Some(mut transport) = self.applied_transport else {
            return RuntimeEngineTransportAdvance::default();
        };
        let start_samples = Some(transport.timeline_position_samples);
        if !transport.playing || frame_count <= 0 {
            return RuntimeEngineTransportAdvance {
                start_samples,
                end_samples: start_samples,
                loop_wrapped: false,
            };
        }

        let advanced = transport
            .timeline_position_samples
            .saturating_add(frame_count);
        let mut loop_wrapped = false;
        transport.timeline_position_samples = if let Some(loop_region) = transport.loop_state {
            let loop_start = loop_region.start_samples;
            let loop_end = loop_region.end_samples;
            if loop_end > loop_start && advanced >= loop_end {
                loop_wrapped = true;
                let loop_len = loop_end.saturating_sub(loop_start);
                loop_start.saturating_add((advanced - loop_start).rem_euclid(loop_len))
            } else {
                advanced
            }
        } else {
            advanced
        };
        self.applied_transport = Some(transport);
        RuntimeEngineTransportAdvance {
            start_samples,
            end_samples: Some(transport.timeline_position_samples),
            loop_wrapped,
        }
    }

